INSERT INTO "avengers_heroes" ("id", "themeId", "displayName", "eligibility", "archetype", "portrait", "contentVersion", "metadata") VALUES
  ('spider-man', 'avengers-doomsday', 'Spider-Man', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/spider-man.webp', 'avengers-content-v1', '{"stats":{"power":84,"agility":95,"resistance":75,"ability":84},"maxEnergy":232,"maxAbilityPoints":86,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Web Strike","es":"Web Strike"},"description":{"en":"Spider-Man lashes out with a rapid web-assisted strike.","es":"Spider-Man descarga un golpe veloz ayudado por telarañas."}},"offensiveAbility":{"id":"spider-man-offensive","name":"Web Barrage","localizedName":{"en":"Web Barrage","es":"Web Barrage"},"description":{"en":"Spider-Man fires a rapid web assault across the opposing formation.","es":"Spider-Man lanza una ráfaga de telarañas sobre la formación rival."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"spider-man-support","name":"Spider-Sense Cover","localizedName":{"en":"Spider-Sense Cover","es":"Spider-Sense Cover"},"description":{"en":"Spider-Man uses spider-sense and web lines to give the team room to move.","es":"Spider-Man usa su sentido arácnido y sus telarañas para abrirle espacio al equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["daredevil","white-tiger"],"rivals":["punisher"],"biography":{"en":"Peter Parker is a brilliant young scientist whose spider abilities, agility and instinct make him one of New York''s most dependable protectors. Behind the mask he balances school, work and loss, meeting danger with quick wit and a deep sense of responsibility. He turns mistakes into reasons to act more carefully next time.","es":"Peter Parker es un joven científico brillante cuyas habilidades arácnidas, agilidad e instinto lo convierten en uno de los protectores más confiables de Nueva York. Detrás de la máscara equilibra estudios, trabajo y pérdidas, y enfrenta el peligro con ingenio y un profundo sentido de la responsabilidad. Convierte sus errores en razones para actuar con más cuidado la próxima vez."},"tournamentMotivation":{"en":"Peter cannot ignore a warning that entire worlds may be at risk. He enters because ordinary people would suffer first, and because his responsibility does not stop at the borders of New York. The tournament gives him a chance to protect lives he may never meet. He would rather save one frightened neighborhood than chase a heroic headline.","es":"Peter no puede ignorar una advertencia que pone en riesgo a mundos enteros. Entra porque la gente común sería la primera en sufrir y porque su responsabilidad no termina en las fronteras de Nueva York. El torneo le ofrece la oportunidad de proteger vidas que quizá nunca conozca. Preferiría salvar un barrio asustado antes que perseguir un titular heroico."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"spider-man-lead","name":"Web Command","localizedName":{"en":"Web Command","es":"Web Command"},"description":{"en":"Spider-Man coordinates the team through speed, improvisation and web tactics.","es":"Spider-Man coordina al equipo con velocidad, improvisación y tácticas de telaraña."},"effect":"DISRUPT","potency":0.15}}}'),
  ('doctor-strange', 'avengers-doomsday', 'Doctor Strange', 'PREFERRED', 'MYSTIC', '/assets/heroes/doctor-strange.webp', 'avengers-content-v1', '{"stats":{"power":60,"agility":69,"resistance":66,"ability":96},"maxEnergy":193,"maxAbilityPoints":152,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Mystic Bolt","es":"Mystic Bolt"},"description":{"en":"Doctor Strange fires a precise bolt of eldritch energy.","es":"Doctor Strange dispara un rayo preciso de energía mística."}},"offensiveAbility":{"id":"doctor-strange-offensive","name":"Crimson Bands","localizedName":{"en":"Crimson Bands","es":"Crimson Bands"},"description":{"en":"Doctor Strange binds the opposing formation with the Crimson Bands of Cyttorak.","es":"Doctor Strange atrapa a la formación rival con las Bandas Carmesí de Cyttorak."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"doctor-strange-support","name":"Ward of the Vishanti","localizedName":{"en":"Ward of the Vishanti","es":"Ward of the Vishanti"},"description":{"en":"Doctor Strange channels a healing ward that restores the team''s strength.","es":"Doctor Strange canaliza un hechizo sanador que devuelve fuerzas al equipo."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["scarlet-witch","wiccan"],"rivals":["ghost-rider"],"biography":{"en":"Stephen Strange is the Sorcerer Supreme, a former surgeon who rebuilt his life through the mystic arts. He guards the boundaries between dimensions with knowledge, discipline and a willingness to confront forces that ordinary science cannot explain. His medical training still shapes the precision with which he protects a patient reality.","es":"Stephen Strange es el Hechicero Supremo, un antiguo cirujano que reconstruyó su vida mediante las artes místicas. Protege los límites entre dimensiones con conocimiento, disciplina y la voluntad de enfrentar fuerzas que la ciencia común no puede explicar. Su formación médica aún guía la precisión con la que protege cada realidad herida."},"tournamentMotivation":{"en":"The warning about a broken ancient agreement touches Strange directly. He joins to understand what has happened to the barriers between realities and to prevent a dimensional crisis from consuming innocent worlds. Every battle may reveal the danger he needs to stop. The cost of inaction is something he understands both as a doctor and a sorcerer.","es":"La advertencia sobre un antiguo acuerdo roto afecta directamente a Strange. Se une para comprender qué ocurre con las barreras entre realidades y evitar que una crisis dimensional consuma mundos inocentes. Cada batalla puede revelar la amenaza que debe detener. Comprende el costo de no actuar tanto como médico como hechicero."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"doctor-strange-lead","name":"Eye of Agamotto","localizedName":{"en":"Eye of Agamotto","es":"Eye of Agamotto"},"description":{"en":"Doctor Strange leads through foresight and disciplined mystical strategy.","es":"Doctor Strange lidera con visión del futuro y estrategia mística disciplinada."},"effect":"HEAL","potency":1.1}}}'),
  ('captain-america', 'avengers-doomsday', 'Captain America', 'PREFERRED', 'GUARDIAN', '/assets/heroes/captain-america.webp', 'avengers-content-v1', '{"stats":{"power":67,"agility":78,"resistance":98,"ability":88},"maxEnergy":299,"maxAbilityPoints":114,"primaryRole":"SUPPORT","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Shield Bash","es":"Shield Bash"},"description":{"en":"Captain America drives his shield into the nearest opening.","es":"Captain America clava su escudo en la abertura más cercana."}},"offensiveAbility":{"id":"captain-america-offensive","name":"Ricochet Shield","localizedName":{"en":"Ricochet Shield","es":"Ricochet Shield"},"description":{"en":"Captain America hurls his shield through the opposing formation and brings it back.","es":"Captain America lanza su escudo contra la formación rival y lo recupera."},"apCost":30,"multiplier":1},"supportAbility":{"id":"captain-america-support","name":"Rallying Shield","localizedName":{"en":"Rallying Shield","es":"Rallying Shield"},"description":{"en":"Captain America uses the shield to cover allies and steady their defense.","es":"Captain America usa el escudo para cubrir a sus aliados y afirmar su defensa."},"apCost":25,"effect":"RESISTANCE","potency":0.15},"allies":["iron-man","wonder-man"],"rivals":[],"biography":{"en":"Steve Rogers is a super-soldier whose greatest strength is the conviction to protect people when fear makes that difficult. As Captain America, he combines disciplined combat, strategic judgment and compassion, leading by example rather than by authority alone. His shield represents a promise to stand where the danger is greatest.","es":"Steve Rogers es un supersoldado cuya mayor fuerza es la convicción de proteger a la gente cuando el miedo lo vuelve difícil. Como Captain America, combina combate disciplinado, criterio estratégico y compasión, y lidera con el ejemplo más que con la autoridad. Su escudo representa la promesa de colocarse donde el peligro sea mayor."},"tournamentMotivation":{"en":"Steve enters because a threat to many realities is a responsibility shared by anyone able to help. He wants the teams to cooperate instead of competing for glory, and he will use the tournament to learn whom he can trust when the crisis reaches every home. He will judge success by lives protected, not by the score of the tournament.","es":"Steve entra porque una amenaza para muchas realidades es responsabilidad de todo aquel que pueda ayudar. Quiere que los equipos cooperen en lugar de competir por gloria, y usará el torneo para saber en quién confiar cuando la crisis alcance cada hogar. Medirá el éxito por las vidas protegidas, no por el marcador del torneo."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"DEFENSIVE","ability":{"id":"captain-america-lead","name":"Avengers Rally","localizedName":{"en":"Avengers Rally","es":"Avengers Rally"},"description":{"en":"Captain America turns courage, discipline and teamwork into a decisive command.","es":"Captain America convierte el valor, la disciplina y el trabajo en equipo en una orden decisiva."},"effect":"PROTECT","potency":0.2}}}'),
  ('thor', 'avengers-doomsday', 'Thor', 'PREFERRED', 'BRUISER', '/assets/heroes/thor.webp', 'avengers-content-v1', '{"stats":{"power":95,"agility":60,"resistance":96,"ability":56},"maxEnergy":307,"maxAbilityPoints":67,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Mjolnir Slam","es":"Mjolnir Slam"},"description":{"en":"Thor brings Mjolnir down with thunderous force.","es":"Thor descarga a Mjolnir con una fuerza atronadora."}},"offensiveAbility":{"id":"thor-offensive","name":"Thunderstrike","localizedName":{"en":"Thunderstrike","es":"Thunderstrike"},"description":{"en":"Thor calls lightning through Mjolnir across the opposing formation.","es":"Thor canaliza un relámpago por Mjolnir contra la formación rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"thor-support","name":"Stormcall","localizedName":{"en":"Stormcall","es":"Stormcall"},"description":{"en":"Thor channels thunder to strengthen the team''s attacks.","es":"Thor canaliza el trueno para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["beta-ray-bill","hulk","iron-man","valkyrie"],"rivals":["hercules"],"biography":{"en":"Thor is the Asgardian God of Thunder, a warrior prince who commands lightning through Mjolnir and carries the memory of many battles across the Nine Realms. His pride has matured into a fierce loyalty to friends, allies and the worlds under his protection. The thunder he commands is matched by memories of realms he could not save.","es":"Thor es el Dios del Trueno asgardiano, un príncipe guerrero que invoca rayos mediante Mjolnir y carga con la memoria de muchas batallas a través de los Nueve Reinos. Su orgullo maduró hasta convertirse en una lealtad feroz hacia sus amigos y los mundos que protege. El trueno que domina se acompaña de recuerdos de reinos que no pudo salvar."},"tournamentMotivation":{"en":"Thor has seen what happens when one realm believes its troubles are someone else''s concern. He accepts the tournament to stand with other champions, judge the threat with his own eyes and defend every realm whose people cannot fight for themselves. He sees fellowship among the teams as the beginning of a stronger defense.","es":"Thor ha visto qué ocurre cuando un reino cree que sus problemas pertenecen a otros. Acepta el torneo para estar junto a otros campeones, evaluar la amenaza con sus propios ojos y defender cada reino cuyos habitantes no puedan luchar por sí mismos. Ve la unión entre los equipos como el comienzo de una defensa más fuerte."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"PRAGMATIC","ability":{"id":"thor-lead","name":"Asgardian Charge","localizedName":{"en":"Asgardian Charge","es":"Asgardian Charge"},"description":{"en":"Thor leads with the boldness of an Asgardian warrior.","es":"Thor lidera con la audacia de un guerrero asgardiano."},"effect":"STRIKE","potency":1.8}}}'),
  ('black-widow', 'avengers-doomsday', 'Black Widow', 'PREFERRED', 'TACTICIAN', '/assets/heroes/black-widow.webp', 'avengers-content-v1', '{"stats":{"power":65,"agility":75,"resistance":82,"ability":87},"maxEnergy":266,"maxAbilityPoints":123,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Widow''s Bite","es":"Widow''s Bite"},"description":{"en":"Black Widow strikes with precise spycraft and a shock of red-room training.","es":"Black Widow ataca con precisión de espía y la descarga de su entrenamiento de la Habitación Roja."}},"offensiveAbility":{"id":"black-widow-offensive","name":"Red Room Barrage","localizedName":{"en":"Red Room Barrage","es":"Red Room Barrage"},"description":{"en":"Black Widow combines firearms and martial skill in a controlled assault.","es":"Black Widow combina armas de fuego y artes marciales en una ofensiva controlada."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"black-widow-support","name":"Covering Takedown","localizedName":{"en":"Covering Takedown","es":"Covering Takedown"},"description":{"en":"Black Widow creates an opening with covering fire and tactical movement.","es":"Black Widow abre un espacio con fuego de cobertura y movimiento táctico."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["hawkeye","hulk"],"rivals":[],"biography":{"en":"Natasha Romanoff is a former spy who turned a life built on manipulation into a career devoted to protecting people. Black Widow relies on intelligence, preparation, close combat and hard choices, reading a room faster than most opponents can raise a weapon. She has learned to turn an uncertain room into a plan before anyone notices the danger.","es":"Natasha Romanoff es una exespía que transformó una vida construida sobre la manipulación en una carrera dedicada a proteger a la gente. Black Widow depende de la inteligencia, la preparación, el combate cercano y decisiones difíciles, y lee una situación antes de que el rival pueda levantar un arma. Aprendió a convertir una sala incierta en un plan antes de que otros noten el peligro."},"tournamentMotivation":{"en":"Natasha does not need a promise of glory to act. She joins because a multiversal emergency demands preparation before panic spreads, and because someone must notice the risks others miss. She will study every team while making sure civilians are not treated as expendable. Her first questions will concern civilians, exits and who is making decisions.","es":"Natasha no necesita una promesa de gloria para actuar. Se une porque una emergencia multiversal exige preparación antes de que cunda el pánico y porque alguien debe advertir los riesgos que otros pasan por alto. Estudiará a cada equipo sin aceptar que los civiles sean sacrificables. Sus primeras preguntas serán por los civiles, las salidas y quién toma las decisiones."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"black-widow-lead","name":"Covert Coordination","localizedName":{"en":"Covert Coordination","es":"Covert Coordination"},"description":{"en":"Black Widow turns preparation and intelligence into a ruthless team plan.","es":"Black Widow convierte la preparación y la inteligencia en un plan de equipo implacable."},"effect":"PROTECT","potency":0.18}}}'),
  ('wolverine', 'avengers-doomsday', 'Wolverine', 'PREFERRED', 'BRUISER', '/assets/heroes/wolverine.webp', 'avengers-content-v1', '{"stats":{"power":91,"agility":42,"resistance":83,"ability":60},"maxEnergy":323,"maxAbilityPoints":83,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Adamantium Slash","es":"Adamantium Slash"},"description":{"en":"Wolverine cuts through the opening with adamantium claws.","es":"Wolverine atraviesa la abertura con sus garras de adamantium."}},"offensiveAbility":{"id":"wolverine-offensive","name":"Berserker Rush","localizedName":{"en":"Berserker Rush","es":"Berserker Rush"},"description":{"en":"Wolverine charges with claws and relentless mutant fury.","es":"Wolverine carga con sus garras y una furia mutante implacable."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"wolverine-support","name":"Berserker Momentum","localizedName":{"en":"Berserker Momentum","es":"Berserker Momentum"},"description":{"en":"Wolverine turns his relentless drive into momentum for the team''s attacks.","es":"Wolverine convierte su impulso implacable en fuerza para los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["quicksilver","storm"],"rivals":["cyclops","deadpool","hulk"],"biography":{"en":"Logan is a mutant survivor with an adamantium skeleton, retractable claws and a healing factor that has carried him through wars, laboratories and long years of loss. Beneath the ferocity he protects younger mutants and values the chosen family he once thought impossible. His memories are painful, but they also tell him what survival asks of the powerless.","es":"Logan es un superviviente mutante con esqueleto de adamantium, garras retráctiles y un factor curativo que lo atravesó por guerras, laboratorios y largos años de pérdidas. Bajo su ferocidad protege a los mutantes jóvenes y valora la familia elegida que creyó imposible. Sus recuerdos duelen, pero también le enseñan qué exige sobrevivir sin poder."},"tournamentMotivation":{"en":"Logan has no interest in speeches about being the strongest. He enters because vulnerable people will pay the price if worlds collide, and because standing beside the X-Men gives him a better chance to keep his friends and their students alive. He will not promise a clean fight; he promises to keep his people standing.","es":"A Logan no le interesan los discursos sobre ser el más fuerte. Entra porque la gente vulnerable pagará el precio si los mundos chocan y porque luchar junto a los X-Men le da una mejor oportunidad de mantener con vida a sus amigos y alumnos. No promete una pelea limpia: promete mantener en pie a los suyos."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"PRAGMATIC","ability":{"id":"wolverine-lead","name":"Primal Command","localizedName":{"en":"Primal Command","es":"Primal Command"},"description":{"en":"Wolverine leads from the front with instinct and fearless resolve.","es":"Wolverine lidera desde el frente con instinto y valor indomable."},"effect":"STRIKE","potency":1.8}}}'),
  ('reed-richards', 'avengers-doomsday', 'Reed Richards / Mister Fantastic', 'PREFERRED', 'TACTICIAN', '/assets/heroes/reed-richards.webp', 'avengers-content-v1', '{"stats":{"power":66,"agility":78,"resistance":68,"ability":88},"maxEnergy":265,"maxAbilityPoints":124,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Elastic Jab","es":"Elastic Jab"},"description":{"en":"Reed Richards / Mister Fantastic stretches a fist through an unexpected angle.","es":"Reed Richards / Mister Fantastic estira el puño desde un ángulo inesperado."}},"offensiveAbility":{"id":"reed-richards-offensive","name":"Fantastic Flurry","localizedName":{"en":"Fantastic Flurry","es":"Fantastic Flurry"},"description":{"en":"Reed Richards / Mister Fantastic turns elastic reach and scientific precision into a sweeping assault.","es":"Reed Richards / Mister Fantastic convierte su alcance elástico y su precisión científica en una ofensiva amplia."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"reed-richards-support","name":"Elastic Feint","localizedName":{"en":"Elastic Feint","es":"Elastic Feint"},"description":{"en":"Reed Richards / Mister Fantastic reconfigures the battlefield to clear hindering effects from the team.","es":"Reed Richards / Mister Fantastic reconfigura el campo de batalla para despejar los efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["invisible-woman","the-thing"],"rivals":["namor"],"biography":{"en":"Reed Richards, Mister Fantastic, is a pioneering scientist whose elastic body is only one expression of his remarkable mind. As a member of the Fantastic Four, he approaches cosmic mysteries through experimentation, imagination and an unwavering duty to bring his family home safely. He treats every impossible question as a responsibility rather than a curiosity.","es":"Reed Richards, Mister Fantastic, es un científico pionero cuyo cuerpo elástico es apenas una expresión de su mente extraordinaria. Como miembro de los Cuatro Fantásticos, aborda los misterios cósmicos con experimentación, imaginación y el deber inquebrantable de mantener a salvo a su familia. Trata cada pregunta imposible como una responsabilidad y no como una simple curiosidad."},"tournamentMotivation":{"en":"Reed joins to investigate the collapse of reality rather than simply fight its symptoms. The tournament places unusual powers and evidence in one place, giving him a chance to understand the threat while Sue, Johnny and Ben stand beside him. The answers matter because his family will live with whatever the teams discover.","es":"Reed se une para investigar el colapso de la realidad en lugar de combatir solo sus síntomas. El torneo reúne poderes y evidencias inusuales en un mismo lugar, lo que le permite comprender la amenaza junto a Sue, Johnny y Ben. Las respuestas importan porque su familia vivirá con lo que descubran los equipos."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"PRAGMATIC","ability":{"id":"reed-richards-lead","name":"Fantastic Strategy","localizedName":{"en":"Fantastic Strategy","es":"Fantastic Strategy"},"description":{"en":"Reed Richards / Mister Fantastic guides the team through science, preparation and adaptive planning.","es":"Reed Richards / Mister Fantastic guía al equipo con ciencia, preparación y planificación adaptable."},"effect":"PROTECT","potency":0.18}}}'),
  ('iron-man', 'avengers-doomsday', 'Iron Man', 'PREFERRED', 'TACTICIAN', '/assets/heroes/iron-man.webp', 'avengers-content-v1', '{"stats":{"power":72,"agility":61,"resistance":75,"ability":86},"maxEnergy":231,"maxAbilityPoints":130,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Repulsor Shot","es":"Repulsor Shot"},"description":{"en":"Iron Man fires a focused repulsor burst from his armor.","es":"Iron Man dispara una ráfaga concentrada de sus repulsores."}},"offensiveAbility":{"id":"iron-man-offensive","name":"Unibeam Sweep","localizedName":{"en":"Unibeam Sweep","es":"Unibeam Sweep"},"description":{"en":"Iron Man opens the chest reactor and sweeps the opposing formation with a Unibeam.","es":"Iron Man abre el reactor del pecho y barre la formación rival con un Unirrayo."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"iron-man-support","name":"Armor Diagnostics","localizedName":{"en":"Armor Diagnostics","es":"Armor Diagnostics"},"description":{"en":"Iron Man runs armor diagnostics that clear harmful effects from the team.","es":"Iron Man ejecuta un diagnóstico de la armadura que limpia los efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["captain-america","thor"],"rivals":[],"biography":{"en":"Tony Stark is an inventor whose armor turns engineering, nerve and relentless iteration into a super-heroic arsenal. Iron Man''s confidence can fill a room, but his best work comes from accepting responsibility for the consequences of the technology he creates. Every suit is also an argument that preparation can turn fear into action.","es":"Tony Stark es un inventor cuya armadura convierte la ingeniería, el coraje y la mejora constante en un arsenal heroico. La confianza de Iron Man puede llenar una habitación, pero su mejor trabajo nace de asumir la responsabilidad por las consecuencias de la tecnología que crea. Cada armadura también demuestra que la preparación puede convertir el miedo en acción."},"tournamentMotivation":{"en":"Tony enters to gather facts before the multiversal warning becomes a catastrophe. He wants to test solutions against the best teams available, protect the people who depend on Earth''s defenders and make sure a crisis of this scale is met with more than optimism. He wants useful data, but he will not sacrifice people to obtain it.","es":"Tony entra para reunir datos antes de que la advertencia multiversal se convierta en catástrofe. Quiere probar soluciones frente a los mejores equipos, proteger a quienes dependen de los defensores de la Tierra y asegurar que una crisis así se enfrente con algo más que optimismo. Quiere datos útiles, pero no sacrificará personas para conseguirlos."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"DEFENSIVE","ability":{"id":"iron-man-lead","name":"Stark Protocol","localizedName":{"en":"Stark Protocol","es":"Stark Protocol"},"description":{"en":"Iron Man coordinates technology, timing and calculated risk.","es":"Iron Man coordina tecnología, sincronización y riesgo calculado."},"effect":"PROTECT","potency":0.18}}}'),
  ('black-panther', 'avengers-doomsday', 'Black Panther', 'PREFERRED', 'TACTICIAN', '/assets/heroes/black-panther.webp', 'avengers-content-v1', '{"stats":{"power":58,"agility":63,"resistance":64,"ability":97},"maxEnergy":248,"maxAbilityPoints":132,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Vibranium Claw","es":"Vibranium Claw"},"description":{"en":"Black Panther strikes with vibranium claws and silent precision.","es":"Black Panther ataca con garras de vibranio y precisión silenciosa."}},"offensiveAbility":{"id":"black-panther-offensive","name":"Kinetic Pounce","localizedName":{"en":"Kinetic Pounce","es":"Kinetic Pounce"},"description":{"en":"Black Panther releases stored kinetic force in a sudden panther-like assault.","es":"Black Panther libera fuerza cinética acumulada en una ofensiva felina y repentina."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"black-panther-support","name":"Panther''s Poise","localizedName":{"en":"Panther''s Poise","es":"Panther''s Poise"},"description":{"en":"Black Panther uses calm movement and Wakandan training to clear harmful effects.","es":"Black Panther usa movimientos serenos y entrenamiento wakandiano para limpiar efectos perjudiciales."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["shuri"],"rivals":["mbaku","namor"],"biography":{"en":"T''Challa is the king of Wakanda and a strategist whose enhanced senses, training and vibranium suit make him a precise protector. Black Panther balances ancient tradition with scientific progress, carrying the welfare and sovereignty of his people into every decision. He carries Wakanda''s history without allowing tradition to close the door to change.","es":"T''Challa es el rey de Wakanda y un estratega cuyos sentidos mejorados, entrenamiento y traje de vibranium lo convierten en un protector preciso. Black Panther equilibra la tradición ancestral con el progreso científico y lleva el bienestar y la soberanía de su pueblo en cada decisión. Lleva la historia de Wakanda sin permitir que la tradición cierre la puerta al cambio."},"tournamentMotivation":{"en":"T''Challa accepts because a threat that crosses realities cannot be answered by one nation alone. He will represent Wakanda without surrendering its independence, learn which allies respect responsibility and return with knowledge that can keep his people safe. The tournament must produce allies, not obligations that compromise Wakanda.","es":"T''Challa acepta porque una amenaza que cruza realidades no puede ser respondida por una sola nación. Representará a Wakanda sin renunciar a su independencia, buscará aliados responsables y volverá con conocimiento capaz de mantener a salvo a su pueblo. El torneo debe producir aliados, no obligaciones que comprometan a Wakanda."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"black-panther-lead","name":"Wakandan Command","localizedName":{"en":"Wakandan Command","es":"Wakandan Command"},"description":{"en":"Black Panther leads through strategy, tradition and absolute composure.","es":"Black Panther lidera con estrategia, tradición y serenidad absoluta."},"effect":"PROTECT","potency":0.18}}}'),
  ('captain-marvel', 'avengers-doomsday', 'Captain Marvel', 'PREFERRED', 'BLASTER', '/assets/heroes/captain-marvel.webp', 'avengers-content-v1', '{"stats":{"power":90,"agility":80,"resistance":77,"ability":91},"maxEnergy":228,"maxAbilityPoints":142,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Photon Burst","es":"Photon Burst"},"description":{"en":"Captain Marvel drives a burst of photon energy through the opening.","es":"Captain Marvel descarga un estallido de energía fotónica por la abertura."}},"offensiveAbility":{"id":"captain-marvel-offensive","name":"Binary Crash","localizedName":{"en":"Binary Crash","es":"Binary Crash"},"description":{"en":"Captain Marvel channels binary power into a blazing assault across the enemy line.","es":"Captain Marvel canaliza el poder binario en una ofensiva ardiente contra la línea enemiga."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"captain-marvel-support","name":"Cosmic Charge","localizedName":{"en":"Cosmic Charge","es":"Cosmic Charge"},"description":{"en":"Captain Marvel channels cosmic power to strengthen the team''s attacks.","es":"Captain Marvel canaliza poder cósmico para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["beta-ray-bill","monica-rambeau","ms-marvel","winter-soldier"],"rivals":["rogue"],"biography":{"en":"Carol Danvers is Captain Marvel, a former Air Force pilot whose cosmic powers let her fly, absorb energy and release it with immense force. Years of service taught her to combine direct action with judgment, especially when an entire planet depends on a single decision. She knows that distance is no excuse when a distress signal crosses the stars.","es":"Carol Danvers es Captain Marvel, una ex piloto de la Fuerza Aérea cuyos poderes cósmicos le permiten volar, absorber energía y liberarla con una fuerza inmensa. Años de servicio le enseñaron a combinar acción directa y criterio cuando un planeta entero depende de una decisión. Sabe que la distancia no es excusa cuando una señal de auxilio cruza las estrellas."},"tournamentMotivation":{"en":"Carol has defended worlds beyond Earth and knows how quickly a distant emergency becomes personal. She enters to measure the threat, coordinate with other protectors and make sure the response is strong enough for civilizations that cannot call for help. She will measure every plan against the worlds that cannot defend their own skies.","es":"Carol ha defendido mundos más allá de la Tierra y sabe lo rápido que una emergencia lejana se vuelve personal. Entra para medir la amenaza, coordinarse con otros protectores y asegurar una respuesta suficiente para civilizaciones que no pueden pedir ayuda. Evaluará cada plan según los mundos que no pueden defender sus propios cielos."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"captain-marvel-lead","name":"Binary Command","localizedName":{"en":"Binary Command","es":"Binary Command"},"description":{"en":"Captain Marvel leads with cosmic confidence and relentless forward momentum.","es":"Captain Marvel lidera con confianza cósmica e impulso implacable."},"effect":"STRIKE","potency":1.7}}}'),
  ('hulk', 'avengers-doomsday', 'Hulk', 'PREFERRED', 'BRUISER', '/assets/heroes/hulk.webp', 'avengers-content-v1', '{"stats":{"power":87,"agility":67,"resistance":82,"ability":66},"maxEnergy":336,"maxAbilityPoints":60,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Gamma Smash","es":"Gamma Smash"},"description":{"en":"Hulk answers the opening with overwhelming gamma strength.","es":"Hulk responde a la abertura con una fuerza gamma arrolladora."}},"offensiveAbility":{"id":"hulk-offensive","name":"Thunderous Leap","localizedName":{"en":"Thunderous Leap","es":"Thunderous Leap"},"description":{"en":"Hulk leaps into the formation and smashes through it with gamma fury.","es":"Hulk salta contra la formación y la rompe con furia gamma."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"hulk-support","name":"Gamma Rally","localizedName":{"en":"Gamma Rally","es":"Gamma Rally"},"description":{"en":"Hulk turns raw strength into momentum for the team''s attacks.","es":"Hulk convierte la fuerza bruta en impulso para los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["black-widow","thor"],"rivals":["the-thing","wolverine"],"biography":{"en":"Bruce Banner is a gifted physicist whose exposure to gamma radiation created the Hulk, a towering force whose strength rises with anger. Banner and Hulk are bound by a difficult partnership, yet both have repeatedly chosen to protect people when no gentler answer remains. Banner''s patience and Hulk''s force are different answers to the same protective instinct.","es":"Bruce Banner es un físico brillante cuya exposición a la radiación gamma creó a Hulk, una fuerza gigantesca cuyo poder crece con la ira. Banner y Hulk están unidos por una difícil convivencia, pero ambos han elegido proteger a la gente cuando no queda una respuesta más amable. La paciencia de Banner y la fuerza de Hulk son respuestas distintas al mismo instinto protector."},"tournamentMotivation":{"en":"Banner joins because the warning concerns forces no laboratory can contain alone. He hopes cooperation will prevent panic and keep the Hulk pointed at the danger rather than at frightened people, while accepting that some worlds may need the strength only he can provide. He wants the teams to see strength as a responsibility, not permission to intimidate.","es":"Banner se une porque la advertencia habla de fuerzas que ningún laboratorio puede contener por sí solo. Espera que la cooperación evite el pánico y mantenga a Hulk enfocado en el peligro, mientras acepta que algunos mundos quizá necesiten la fuerza que solo él puede aportar. Quiere que los equipos vean la fuerza como responsabilidad, no como permiso para intimidar."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"hulk-lead","name":"Hulk''s Roar","localizedName":{"en":"Hulk''s Roar","es":"Hulk''s Roar"},"description":{"en":"Hulk drives the team forward through sheer force of will.","es":"Hulk empuja al equipo con pura fuerza de voluntad."},"effect":"STRIKE","potency":1.8}}}'),
  ('scarlet-witch', 'avengers-doomsday', 'Scarlet Witch', 'PREFERRED', 'MYSTIC', '/assets/heroes/scarlet-witch.webp', 'avengers-content-v1', '{"stats":{"power":53,"agility":60,"resistance":58,"ability":92},"maxEnergy":209,"maxAbilityPoints":143,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Hex Bolt","es":"Hex Bolt"},"description":{"en":"Scarlet Witch fires a bolt of scarlet chaos energy.","es":"Scarlet Witch dispara un rayo de energía caótica escarlata."}},"offensiveAbility":{"id":"scarlet-witch-offensive","name":"Chaos Surge","localizedName":{"en":"Chaos Surge","es":"Chaos Surge"},"description":{"en":"Scarlet Witch warps probability into a devastating wave of chaos magic.","es":"Scarlet Witch retuerce la probabilidad en una devastadora oleada de magia del caos."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"scarlet-witch-support","name":"Hex Ward","localizedName":{"en":"Hex Ward","es":"Hex Ward"},"description":{"en":"Scarlet Witch channels chaos magic to restore the team''s fighting strength.","es":"Scarlet Witch canaliza magia del caos para devolver fuerzas de combate al equipo."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["doctor-strange","magik"],"rivals":[],"biography":{"en":"Wanda Maximoff is the Scarlet Witch, a powerful wielder of chaos magic whose emotions and imagination can reshape the battlefield. Her history has taught her the cost of uncontrolled power, making her protective of people who fear what they cannot understand. She knows imagination can heal a broken life as easily as it can endanger one.","es":"Wanda Maximoff es Scarlet Witch, una poderosa usuaria de la magia del caos cuyas emociones e imaginación pueden transformar el campo de batalla. Su historia le enseñó el costo del poder sin control y la volvió protectora de quienes temen lo que no comprenden. Sabe que la imaginación puede sanar una vida rota con la misma facilidad con que puede ponerla en peligro."},"tournamentMotivation":{"en":"Wanda enters because a warning about damaged realities demands someone who understands how fragile the world can be. She wants to help before fear turns into another tragedy, and to learn whether the gathered heroes can protect lives without repeating old mistakes. She will listen for the human consequences hidden behind every cosmic explanation.","es":"Wanda entra porque una advertencia sobre realidades dañadas exige a alguien que comprenda lo frágil que puede ser el mundo. Quiere ayudar antes de que el miedo cause otra tragedia y descubrir si los héroes reunidos pueden proteger vidas sin repetir viejos errores. Escuchará las consecuencias humanas ocultas detrás de cada explicación cósmica."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"scarlet-witch-lead","name":"Nexus of Chaos","localizedName":{"en":"Nexus of Chaos","es":"Nexus of Chaos"},"description":{"en":"Scarlet Witch guides reality-warping power with focused intent.","es":"Scarlet Witch guía el poder que altera la realidad con intención concentrada."},"effect":"HEAL","potency":1.1}}}'),
  ('vision', 'avengers-doomsday', 'Vision', 'PREFERRED', 'TACTICIAN', '/assets/heroes/vision.webp', 'avengers-content-v1', '{"stats":{"power":72,"agility":68,"resistance":77,"ability":97},"maxEnergy":264,"maxAbilityPoints":126,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Solar Beam","es":"Solar Beam"},"description":{"en":"Vision fires a focused beam of solar energy.","es":"Vision dispara un rayo concentrado de energía solar."}},"offensiveAbility":{"id":"vision-offensive","name":"Density Shift","localizedName":{"en":"Density Shift","es":"Density Shift"},"description":{"en":"Vision phases through the defense and strikes with changing density.","es":"Vision atraviesa la defensa y golpea cambiando su densidad."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"vision-support","name":"Phase Reset","localizedName":{"en":"Phase Reset","es":"Phase Reset"},"description":{"en":"Vision uses precise phasing to clear harmful effects from the team.","es":"Vision usa una fase precisa para limpiar efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["ant-man","falcon"],"rivals":["wonder-man"],"biography":{"en":"Vision is a synthetic Avenger created with advanced technology and a mind capable of empathy, reason and independent judgment. He can alter his density, fly and channel solar energy, yet his defining strength is the choice to treat every life as more than a calculation. His synthetic perspective gives him patience with questions that have no immediate answer.","es":"Vision es un Vengador sintético creado con tecnología avanzada y una mente capaz de sentir empatía, razonar y decidir por sí misma. Puede alterar su densidad, volar y canalizar energía solar, pero su mayor fuerza es elegir que cada vida sea algo más que un cálculo. Su perspectiva sintética le da paciencia ante preguntas sin respuesta inmediata."},"tournamentMotivation":{"en":"Vision joins to help turn a frightening warning into a reasoned response. He wants the teams to share knowledge instead of acting from fear, and to protect the many forms of life that could be lost if reality''s boundaries continue to fail. He wants a shared record of what happens so no community is protected too late.","es":"Vision se une para convertir una advertencia aterradora en una respuesta razonada. Quiere que los equipos compartan conocimiento en lugar de actuar por miedo y proteger las muchas formas de vida que podrían perderse si las fronteras de la realidad siguen fallando. Quiere un registro compartido de lo ocurrido para que ninguna comunidad sea protegida tarde."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"vision-lead","name":"Synthesis Protocol","localizedName":{"en":"Synthesis Protocol","es":"Synthesis Protocol"},"description":{"en":"Vision coordinates logic, empathy and perfect timing.","es":"Vision coordina lógica, empatía y sincronización perfecta."},"effect":"PROTECT","potency":0.18}}}'),
  ('hawkeye', 'avengers-doomsday', 'Hawkeye', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/hawkeye.webp', 'avengers-content-v1', '{"stats":{"power":79,"agility":88,"resistance":55,"ability":82},"maxEnergy":216,"maxAbilityPoints":94,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Precision Shot","es":"Precision Shot"},"description":{"en":"Hawkeye puts an arrow exactly where the defense opens.","es":"Hawkeye clava una flecha justo donde se abre la defensa."}},"offensiveAbility":{"id":"hawkeye-offensive","name":"Trick Arrow Volley","localizedName":{"en":"Trick Arrow Volley","es":"Trick Arrow Volley"},"description":{"en":"Hawkeye unleashes a volley of specialized trick arrows.","es":"Hawkeye desata una lluvia de flechas especiales."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"hawkeye-support","name":"Covering Arrows","localizedName":{"en":"Covering Arrows","es":"Covering Arrows"},"description":{"en":"Hawkeye uses a rain of arrows to give the team room to reposition.","es":"Hawkeye usa una lluvia de flechas para que el equipo pueda reposicionarse."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["black-widow","wasp"],"rivals":["deadpool"],"biography":{"en":"Clint Barton is Hawkeye, a master archer whose ordinary human limits never stopped him from standing beside super-soldiers and gods. He brings field experience, trick arrows, dry humor and a stubborn instinct to protect the teammates who rely on him. Clint''s best weapon is often the calm observation that keeps a mission from going wrong.","es":"Clint Barton es Hawkeye, un arquero maestro cuyos límites humanos nunca le impidieron luchar junto a supersoldados y dioses. Aporta experiencia de campo, flechas especiales, humor seco y el instinto persistente de proteger a quienes cuentan con él. El mejor arma de Clint suele ser la observación serena que evita que una misión falle."},"tournamentMotivation":{"en":"Clint knows that the people threatened by a cosmic crisis will not have powers to defend them. He enters because a steady hand and a clear view still matter, especially when larger-than-life heroes need someone who remembers the human cost. He will make the complicated warning understandable to people who are not superhuman.","es":"Clint sabe que las personas amenazadas por una crisis cósmica no tendrán poderes para defenderse. Entra porque una mano firme y una mirada clara siguen importando, sobre todo cuando los héroes enormes necesitan recordar el costo humano. Hará comprensible la advertencia para quienes no son superhumanos."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"hawkeye-lead","name":"Bullseye Call","localizedName":{"en":"Bullseye Call","es":"Bullseye Call"},"description":{"en":"Hawkeye turns battlefield awareness into a precise team command.","es":"Hawkeye convierte la lectura del campo en una orden precisa para el equipo."},"effect":"DISRUPT","potency":0.15}}}'),
  ('wasp', 'avengers-doomsday', 'Wasp', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/wasp.webp', 'avengers-content-v1', '{"stats":{"power":78,"agility":91,"resistance":60,"ability":78},"maxEnergy":223,"maxAbilityPoints":81,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Stinger Jab","es":"Stinger Jab"},"description":{"en":"Wasp dives in with a bio-electric sting.","es":"Wasp se lanza con una picadura bioeléctrica."}},"offensiveAbility":{"id":"wasp-offensive","name":"Pym-Sting Barrage","localizedName":{"en":"Pym-Sting Barrage","es":"Pym-Sting Barrage"},"description":{"en":"Wasp changes size and floods the enemy line with stinging blasts.","es":"Wasp cambia de tamaño y llena la línea enemiga de descargas punzantes."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"wasp-support","name":"Shrink-and-Scatter","localizedName":{"en":"Shrink-and-Scatter","es":"Shrink-and-Scatter"},"description":{"en":"Wasp uses size-changing movement to sharpen the team''s mobility.","es":"Wasp usa cambios de tamaño para agudizar la movilidad del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["ant-man","hawkeye"],"rivals":[],"biography":{"en":"Janet van Dyne is the Wasp, a founding Avenger whose size-changing suit gives her speed, flight and bio-electric stings. She is a skilled tactician and an experienced team-builder, combining sharp fashion sense with the courage to make the first move. Janet knows a small opening can become the decisive advantage for an entire team.","es":"Janet van Dyne es Wasp, una Vengadora fundadora cuyo traje de tamaño variable le da velocidad, vuelo y descargas bioeléctricas. Es una estratega experta y una constructora de equipos, con gran estilo y el valor de dar el primer paso. Janet sabe que una pequeña apertura puede ser la ventaja decisiva de todo un equipo."},"tournamentMotivation":{"en":"Janet joins because teams facing unfamiliar worlds need coordination as much as power. She wants to keep the larger heroes focused, protect the people caught in the confusion and prove that careful leadership can connect champions who have never fought together. She wants the tournament to reward cooperation and quick thinking, not only force.","es":"Janet se une porque los equipos que enfrentan mundos desconocidos necesitan coordinación tanto como poder. Quiere mantener concentrados a los héroes más grandes, proteger a quienes queden atrapados en la confusión y demostrar que un liderazgo atento puede unir campeones desconocidos. Quiere que el torneo premie la cooperación y la rapidez mental, no solo la fuerza."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"DEFENSIVE","ability":{"id":"wasp-lead","name":"Swarm Tactics","localizedName":{"en":"Swarm Tactics","es":"Swarm Tactics"},"description":{"en":"Wasp coordinates speed, size and bio-electric timing.","es":"Wasp coordina velocidad, tamaño y sincronización bioeléctrica."},"effect":"DISRUPT","potency":0.15}}}'),
  ('ant-man', 'avengers-doomsday', 'Ant-Man', 'PREFERRED', 'TACTICIAN', '/assets/heroes/ant-man.webp', 'avengers-content-v1', '{"stats":{"power":68,"agility":62,"resistance":63,"ability":90},"maxEnergy":270,"maxAbilityPoints":113,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Pym Strike","es":"Pym Strike"},"description":{"en":"Ant-Man changes size at the instant of impact.","es":"Ant-Man cambia de tamaño justo en el momento del impacto."}},"offensiveAbility":{"id":"ant-man-offensive","name":"Giant-Man Crash","localizedName":{"en":"Giant-Man Crash","es":"Giant-Man Crash"},"description":{"en":"Ant-Man grows into a crushing charge against the opposing formation.","es":"Ant-Man crece hasta convertirse en una embestida contra la formación rival."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"ant-man-support","name":"Quantum Reposition","localizedName":{"en":"Quantum Reposition","es":"Quantum Reposition"},"description":{"en":"Ant-Man uses size-changing movement to clear hindering effects from the team.","es":"Ant-Man usa cambios de tamaño para despejar efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["vision","wasp"],"rivals":[],"biography":{"en":"Scott Lang is Ant-Man, a former thief who became a hero through courage, humor and a suit that lets him grow, shrink and command ants. His scientific curiosity is matched by a fierce devotion to his daughter and to the second chances he was given. His best plans often begin with noticing a detail everyone else considered too small.","es":"Scott Lang es Ant-Man, un antiguo ladrón que se convirtió en héroe mediante coraje, humor y un traje que le permite crecer, encogerse y comandar hormigas. Su curiosidad científica iguala su devoción por su hija y por las segundas oportunidades que recibió. Sus mejores planes suelen comenzar al notar un detalle que otros consideraron demasiado pequeño."},"tournamentMotivation":{"en":"Scott enters because a threat to many realities also threatens every family living inside them, including his own. He may joke when the pressure rises, but he intends to use the tournament to keep ordinary people from paying for a crisis they did not cause. He will keep asking how the crisis affects families while experts discuss its scale.","es":"Scott entra porque una amenaza para muchas realidades también amenaza a cada familia que vive en ellas, incluida la suya. Puede bromear bajo presión, pero piensa usar el torneo para evitar que la gente común pague por una crisis que no provocó. Seguirá preguntando cómo afecta la crisis a las familias mientras los expertos discuten su escala."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"ant-man-lead","name":"Quantum Plan","localizedName":{"en":"Quantum Plan","es":"Quantum Plan"},"description":{"en":"Ant-Man turns scientific improvisation into a reliable team plan.","es":"Ant-Man convierte la improvisación científica en un plan confiable para el equipo."},"effect":"PROTECT","potency":0.18}}}'),
  ('falcon', 'avengers-doomsday', 'Falcon', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/falcon.webp', 'avengers-content-v1', '{"stats":{"power":77,"agility":91,"resistance":56,"ability":72},"maxEnergy":229,"maxAbilityPoints":97,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Wingblade Strike","es":"Wingblade Strike"},"description":{"en":"Falcon cuts through the opening with a wing-assisted strike.","es":"Falcon atraviesa la abertura con un golpe asistido por sus alas."}},"offensiveAbility":{"id":"falcon-offensive","name":"Aerial Dive","localizedName":{"en":"Aerial Dive","es":"Aerial Dive"},"description":{"en":"Falcon dives from above with the Redwing and his wings at full speed.","es":"Falcon se lanza desde el cielo con Redwing y sus alas a toda velocidad."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"falcon-support","name":"Wingman Cover","localizedName":{"en":"Wingman Cover","es":"Wingman Cover"},"description":{"en":"Falcon uses aerial positioning to give the team room to move.","es":"Falcon usa su posición aérea para abrirle espacio al equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["vision","winter-soldier"],"rivals":[],"biography":{"en":"Sam Wilson is Falcon, an aerial hero whose wings, drone support and empathy make him an exceptional rescue specialist. He understands both the burden of the Captain America legacy and the importance of listening before asking people to follow. His wings are built for rescue as much as for combat, and he never forgets the difference.","es":"Sam Wilson es Falcon, un héroe aéreo cuyas alas, drones y empatía lo convierten en un especialista excepcional en rescates. Comprende tanto el peso del legado de Captain America como la importancia de escuchar antes de pedir que otros lo sigan. Sus alas sirven tanto para rescatar como para combatir, y nunca olvida la diferencia."},"tournamentMotivation":{"en":"Sam joins to keep the response centered on people rather than on spectacle. He wants the teams to share leadership, evacuate those caught between worlds and ensure that the strongest fighters remember why the fight matters. He will turn the tournament into a network of people who can answer one another''s calls.","es":"Sam se une para mantener la respuesta centrada en las personas y no en el espectáculo. Quiere que los equipos compartan el liderazgo, evacúen a quienes queden entre mundos y recuerden por qué vale la pena luchar. Convertirá el torneo en una red de personas capaces de responder al llamado ajeno."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"PRAGMATIC","ability":{"id":"falcon-lead","name":"Aerial Command","localizedName":{"en":"Aerial Command","es":"Aerial Command"},"description":{"en":"Falcon leads by reading the battlefield from above.","es":"Falcon lidera leyendo el campo de batalla desde las alturas."},"effect":"DISRUPT","potency":0.15}}}'),
  ('winter-soldier', 'avengers-doomsday', 'Winter Soldier', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/winter-soldier.webp', 'avengers-content-v1', '{"stats":{"power":83,"agility":86,"resistance":67,"ability":66},"maxEnergy":270,"maxAbilityPoints":90,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Armored Burst","es":"Armored Burst"},"description":{"en":"Winter Soldier answers with a controlled burst from his rifle.","es":"Winter Soldier responde con una ráfaga controlada de su rifle."}},"offensiveAbility":{"id":"winter-soldier-offensive","name":"Precision Suppression","localizedName":{"en":"Precision Suppression","es":"Precision Suppression"},"description":{"en":"Winter Soldier combines rifle fire and the metal arm in a disciplined assault.","es":"Winter Soldier combina el fuego de su rifle y el brazo metálico en una ofensiva disciplinada."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"winter-soldier-support","name":"Tactical Advance","localizedName":{"en":"Tactical Advance","es":"Tactical Advance"},"description":{"en":"Winter Soldier uses cover and movement to sharpen the team''s positioning.","es":"Winter Soldier usa cobertura y movimiento para mejorar la posición del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["captain-marvel","falcon"],"rivals":[],"biography":{"en":"Bucky Barnes is the Winter Soldier, a veteran who survived weaponization, manipulation and the long work of reclaiming his own choices. His enhanced body and combat skill are formidable, but his quieter strength is the determination to use his past to prevent others from being turned into weapons. He knows recovery is measured in choices made after someone else has taken them away.","es":"Bucky Barnes es Winter Soldier, un veterano que sobrevivió a la militarización, la manipulación y al largo proceso de recuperar sus propias decisiones. Su cuerpo mejorado y su habilidad de combate son formidables, pero su fuerza más profunda es impedir que otros sean convertidos en armas. Sabe que recuperarse se mide en decisiones tomadas después de que otro las haya arrebatado."},"tournamentMotivation":{"en":"Bucky accepts because the crisis sounds like the kind of power struggle that leaves people without a choice. He will stand with the teams, learn who is being endangered and make sure the vulnerable are protected before anyone turns the emergency into another chain of command. He will watch for coercion as carefully as he watches the battlefield.","es":"Bucky acepta porque la crisis parece el tipo de lucha de poder que deja a la gente sin elección. Estará junto a los equipos, descubrirá quién está en peligro y protegerá a los vulnerables antes de que alguien convierta la emergencia en otra cadena de mando. Vigilará la coerción con el mismo cuidado con que vigila el campo de batalla."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"winter-soldier-lead","name":"Soldier''s Formation","localizedName":{"en":"Soldier''s Formation","es":"Soldier''s Formation"},"description":{"en":"Winter Soldier turns hard-earned battlefield discipline into a clear plan.","es":"Winter Soldier convierte la disciplina ganada en batalla en un plan claro."},"effect":"DISRUPT","potency":0.15}}}'),
  ('elektra', 'avengers-doomsday', 'Elektra', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/elektra.webp', 'avengers-content-v1', '{"stats":{"power":69,"agility":97,"resistance":69,"ability":70},"maxEnergy":248,"maxAbilityPoints":96,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Sai Thrust","es":"Sai Thrust"},"description":{"en":"Elektra drives a sai through the opening with assassin precision.","es":"Elektra clava un sai en la abertura con precisión de asesina."}},"offensiveAbility":{"id":"elektra-offensive","name":"Assassin''s Flurry","localizedName":{"en":"Assassin''s Flurry","es":"Assassin''s Flurry"},"description":{"en":"Elektra unleashes a blinding flurry of sai strikes.","es":"Elektra desata una ráfaga cegadora de golpes con sus sais."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"elektra-support","name":"Shadow Step","localizedName":{"en":"Shadow Step","es":"Shadow Step"},"description":{"en":"Elektra uses speed and misdirection to improve the team''s movement.","es":"Elektra usa velocidad y engaño para mejorar el movimiento del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["punisher"],"rivals":["daredevil"],"biography":{"en":"Elektra Natchios is a master of martial arts and the sai, shaped by grief, discipline and a life spent near the line between assassin and hero. Her independence is hard-won, and every act of loyalty is a decision she makes for herself rather than an order she obeys. She carries grief without allowing it to become an excuse for serving violence.","es":"Elektra Natchios domina las artes marciales y el sai, marcada por el duelo, la disciplina y una vida en la frontera entre asesina y heroína. Su independencia le costó mucho, y cada acto de lealtad es una decisión propia, no una orden que obedece. Lleva el duelo sin permitir que se convierta en una excusa para servir a la violencia."},"tournamentMotivation":{"en":"Elektra does not enter for a banner or a promise of praise. She sees a threat that will reach people with no way to defend themselves, and chooses to place her skills where they can prevent the next death instead of serving another master. Her loyalty will be earned in action, one endangered life at a time.","es":"Elektra no entra por una bandera ni por promesas de reconocimiento. Ve una amenaza que alcanzará a personas incapaces de defenderse y decide poner sus habilidades allí donde puedan evitar la próxima muerte, sin servir a otro amo. Su lealtad se ganará con acciones, una vida en peligro a la vez."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"elektra-lead","name":"Hand Discipline","localizedName":{"en":"Hand Discipline","es":"Hand Discipline"},"description":{"en":"Elektra leads through focus, patience and lethal precision.","es":"Elektra lidera con concentración, paciencia y precisión letal."},"effect":"DISRUPT","potency":0.15}}}'),
  ('spider-woman', 'avengers-doomsday', 'Spider-Woman', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/spider-woman.webp', 'avengers-content-v1', '{"stats":{"power":80,"agility":96,"resistance":63,"ability":73},"maxEnergy":258,"maxAbilityPoints":84,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Venom Jab","es":"Venom Jab"},"description":{"en":"Spider-Woman lands a charged venom strike.","es":"Spider-Woman conecta un golpe cargado de veneno bioeléctrico."}},"offensiveAbility":{"id":"spider-woman-offensive","name":"Venom Blast","localizedName":{"en":"Venom Blast","es":"Venom Blast"},"description":{"en":"Spider-Woman releases a sweeping venom blast across the enemy line.","es":"Spider-Woman libera una descarga de veneno bioeléctrico sobre la línea enemiga."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"spider-woman-support","name":"Toxin Sense","localizedName":{"en":"Toxin Sense","es":"Toxin Sense"},"description":{"en":"Spider-Woman uses heightened senses to sharpen the team''s movement.","es":"Spider-Woman usa sus sentidos aumentados para agudizar el movimiento del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":[],"rivals":[],"biography":{"en":"Jessica Drew is Spider-Woman, a former agent whose altered biology grants her strength, agility, venom blasts and the ability to glide through danger. She has survived manipulation and reinvention, building an independent life while remaining fiercely protective of the people she trusts. Jessica''s independence is a boundary she protects as carefully as any teammate.","es":"Jessica Drew es Spider-Woman, una exagente cuya biología alterada le otorga fuerza, agilidad, descargas de veneno y la capacidad de planear en medio del peligro. Sobrevivió a la manipulación y a varias reinvenciones, y construyó una vida independiente protegiendo a quienes confía. La independencia de Jessica es un límite que protege tanto como a cualquier compañero."},"tournamentMotivation":{"en":"Jessica joins because she recognizes the look of a crisis being managed by people who know more than they share. She will protect civilians, ask the questions other teams avoid and use the tournament to make sure no world becomes collateral damage. She will compare every official explanation with the people who bear its consequences.","es":"Jessica se une porque reconoce el aspecto de una crisis administrada por personas que saben más de lo que cuentan. Protegerá a los civiles, hará las preguntas que otros eviten y usará el torneo para que ningún mundo se convierta en daño colateral. Comparará cada explicación oficial con las personas que sufren sus consecuencias."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"spider-woman-lead","name":"Webline Tactics","localizedName":{"en":"Webline Tactics","es":"Webline Tactics"},"description":{"en":"Spider-Woman coordinates mobility, venom and fast tactical choices.","es":"Spider-Woman coordina movilidad, veneno y decisiones tácticas veloces."},"effect":"DISRUPT","potency":0.15}}}'),
  ('daredevil', 'avengers-doomsday', 'Daredevil', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/daredevil.webp', 'avengers-content-v1', '{"stats":{"power":68,"agility":86,"resistance":75,"ability":78},"maxEnergy":218,"maxAbilityPoints":90,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Billy Club Strike","es":"Billy Club Strike"},"description":{"en":"Daredevil whips his billy clubs through the opening.","es":"Daredevil lanza sus bastones contra la abertura."}},"offensiveAbility":{"id":"daredevil-offensive","name":"Radar Assault","localizedName":{"en":"Radar Assault","es":"Radar Assault"},"description":{"en":"Daredevil fights through the formation guided by radar sense.","es":"Daredevil atraviesa la formación guiado por su sentido radar."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"daredevil-support","name":"Radar Focus","localizedName":{"en":"Radar Focus","es":"Radar Focus"},"description":{"en":"Daredevil uses radar awareness to give the team room to reposition.","es":"Daredevil usa su percepción radar para que el equipo pueda reposicionarse."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["spider-man"],"rivals":["elektra","punisher"],"biography":{"en":"Matt Murdock is Daredevil, a blind lawyer whose heightened senses create a radar-like awareness of movement, sound and danger. He protects Hell''s Kitchen through disciplined martial arts, legal advocacy and a belief that justice must include people the powerful overlook. He hears fear in a voice and a heartbeat long before it reaches a public report.","es":"Matt Murdock es Daredevil, un abogado ciego cuyos sentidos aumentados crean una percepción similar a un radar para el movimiento, el sonido y el peligro. Protege Hell''s Kitchen mediante artes marciales, defensa legal y la convicción de que la justicia debe incluir a quienes los poderosos ignoran. Percibe el miedo en una voz y en un latido mucho antes de que aparezca en un informe."},"tournamentMotivation":{"en":"Matt enters because a multiversal threat will hurt neighborhoods long before it reaches a battlefield. He wants the powerful teams to remember the people beneath the crisis, and he will bring the same attention to hidden danger that he brings to every street in Hell''s Kitchen. He will keep the crisis connected to the individual lives hidden inside it.","es":"Matt entra porque una amenaza multiversal dañará los barrios mucho antes de llegar a un campo de batalla. Quiere que los equipos poderosos recuerden a las personas detrás de la crisis y aportará la misma atención al peligro oculto que aporta a cada calle de Hell''s Kitchen. Mantendrá la crisis conectada con las vidas individuales que contiene."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"daredevil-lead","name":"Hell''s Kitchen Resolve","localizedName":{"en":"Hell''s Kitchen Resolve","es":"Hell''s Kitchen Resolve"},"description":{"en":"Daredevil leads with instinct, courage and unshakable resolve.","es":"Daredevil lidera con instinto, valor y determinación inquebrantable."},"effect":"DISRUPT","potency":0.15}}}'),
  ('deadpool', 'avengers-doomsday', 'Deadpool', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/deadpool.webp', 'avengers-content-v1', '{"stats":{"power":71,"agility":84,"resistance":69,"ability":77},"maxEnergy":252,"maxAbilityPoints":100,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Katana Slash","es":"Katana Slash"},"description":{"en":"Deadpool cuts through the opening with a reckless katana slash.","es":"Deadpool atraviesa la abertura con un tajo temerario de katana."}},"offensiveAbility":{"id":"deadpool-offensive","name":"Fourth-Wall Barrage","localizedName":{"en":"Fourth-Wall Barrage","es":"Fourth-Wall Barrage"},"description":{"en":"Deadpool combines twin katanas, guns and impossible improvisation.","es":"Deadpool combina dos katanas, armas de fuego e improvisación imposible."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"deadpool-support","name":"Chaotic Cover","localizedName":{"en":"Chaotic Cover","es":"Chaotic Cover"},"description":{"en":"Deadpool turns unpredictable movement into room for the team to move.","es":"Deadpool convierte sus movimientos impredecibles en espacio para el equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["shang-chi"],"rivals":["hawkeye","punisher","squirrel-girl","wolverine"],"biography":{"en":"Wade Wilson is Deadpool, a fast-talking mercenary with accelerated healing, expert weapons training and a talent for turning chaos into an advantage. Beneath the jokes and scars is someone who understands betrayal and occasionally chooses to protect people when walking away would be easier. His healing factor keeps him moving, but his choices still leave marks on everyone around him.","es":"Wade Wilson es Deadpool, un mercenario de lengua rápida con curación acelerada, dominio de las armas y talento para convertir el caos en ventaja. Bajo los chistes y las cicatrices hay alguien que conoce la traición y a veces elige proteger a otros cuando sería más fácil irse. Su factor curativo lo mantiene en pie, pero sus decisiones aún dejan marcas en quienes lo rodean."},"tournamentMotivation":{"en":"Wade claims he joined for the challenge, but a threat capable of erasing worlds is difficult even for him to dismiss. He wants to see who can be trusted, keep dangerous people from making the only decisions and leave at least a few innocents alive afterward. He will pretend not to care until someone vulnerable needs the help only he will give.","es":"Wade dice que se unió por el desafío, pero incluso para él es difícil ignorar una amenaza capaz de borrar mundos. Quiere descubrir en quién confiar, impedir que las personas peligrosas tomen todas las decisiones y dejar con vida a algunos inocentes. Fingirá que no le importa hasta que alguien vulnerable necesite la ayuda que solo él dará."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"deadpool-lead","name":"Merc with a Plan","localizedName":{"en":"Merc with a Plan","es":"Merc with a Plan"},"description":{"en":"Deadpool leads through chaos, confidence and a plan that somehow works.","es":"Deadpool lidera con caos, confianza y un plan que, de algún modo, funciona."},"effect":"DISRUPT","potency":0.15}}}'),
  ('punisher', 'avengers-doomsday', 'Punisher', 'PREFERRED', 'TACTICIAN', '/assets/heroes/punisher.webp', 'avengers-content-v1', '{"stats":{"power":71,"agility":60,"resistance":72,"ability":92},"maxEnergy":234,"maxAbilityPoints":113,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Controlled Fire","es":"Controlled Fire"},"description":{"en":"Punisher opens fire with a disciplined burst from his weapon.","es":"Punisher abre fuego con una ráfaga disciplinada de su arma."}},"offensiveAbility":{"id":"punisher-offensive","name":"Arsenal Barrage","localizedName":{"en":"Arsenal Barrage","es":"Arsenal Barrage"},"description":{"en":"Punisher brings multiple weapons to bear across the opposing formation.","es":"Punisher descarga su arsenal completo sobre la formación rival."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"punisher-support","name":"Covering Fire","localizedName":{"en":"Covering Fire","es":"Covering Fire"},"description":{"en":"Punisher lays down covering fire so the team can reposition safely.","es":"Punisher sostiene fuego de cobertura para que el equipo se reposicione a salvo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["elektra"],"rivals":["daredevil","deadpool","luke-cage","spider-man","war-machine"],"biography":{"en":"Frank Castle is the Punisher, a former Marine who wages a relentless war on criminals with military training, firearms and uncompromising focus. He is not a symbol of hope, but his mission is clear: make sure predators cannot keep hurting people who have no protection. He trusts preparation more than speeches and consequences more than reputation.","es":"Frank Castle es Punisher, un exmarine que libra una guerra implacable contra criminales con entrenamiento militar, armas de fuego y concentración absoluta. No es un símbolo de esperanza, pero su misión es clara: impedir que los depredadores sigan dañando a quienes no tienen protección. Confía más en la preparación que en los discursos y en las consecuencias que en la reputación."},"tournamentMotivation":{"en":"Frank enters because worlds in collapse create predators, refugees and victims long before anyone calls it a war. He does not trust grand promises, but he understands the need to protect civilians and will use the tournament to put himself between them and whatever comes next. Frank will choose the position that protects civilians, even when nobody applauds it.","es":"Frank entra porque los mundos en colapso crean depredadores, refugiados y víctimas mucho antes de que alguien lo llame guerra. No confía en grandes promesas, pero entiende la necesidad de proteger a los civiles y se interpondrá entre ellos y lo que venga después. Frank elegirá la posición que proteja a los civiles, aunque nadie la aplauda."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"punisher-lead","name":"Punisher''s Tactics","localizedName":{"en":"Punisher''s Tactics","es":"Punisher''s Tactics"},"description":{"en":"Punisher turns military planning and ruthless focus into a team command.","es":"Punisher convierte la planificación militar y la concentración implacable en una orden de equipo."},"effect":"PROTECT","potency":0.18}}}'),
  ('shang-chi', 'avengers-doomsday', 'Shang-Chi', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/shang-chi.webp', 'avengers-content-v1', '{"stats":{"power":80,"agility":85,"resistance":63,"ability":67},"maxEnergy":268,"maxAbilityPoints":80,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Ten Rings Strike","es":"Ten Rings Strike"},"description":{"en":"Shang-Chi drives a balanced martial-arts strike through the opening.","es":"Shang-Chi descarga un golpe de artes marciales equilibrado por la abertura."}},"offensiveAbility":{"id":"shang-chi-offensive","name":"Dragon''s Fury","localizedName":{"en":"Dragon''s Fury","es":"Dragon''s Fury"},"description":{"en":"Shang-Chi turns the Ten Rings into a spiraling offensive assault.","es":"Shang-Chi convierte los Diez Anillos en una ofensiva arrolladora."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"shang-chi-support","name":"Centered Breath","localizedName":{"en":"Centered Breath","es":"Centered Breath"},"description":{"en":"Shang-Chi uses disciplined breathing to sharpen the team''s movement.","es":"Shang-Chi usa una respiración disciplinada para agudizar el movimiento del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["deadpool","echo"],"rivals":[],"biography":{"en":"Shang-Chi is a master martial artist who turned away from the violent legacy imposed on him and built his own path. His control, timing and understanding of chi make him dangerous without weapons, while humility keeps his skill from becoming arrogance. His quiet confidence is the result of discipline, not a need to dominate a room.","es":"Shang-Chi es un maestro de las artes marciales que rechazó el legado violento que le impusieron y construyó su propio camino. Su control, precisión y dominio del chi lo vuelven peligroso sin armas, mientras la humildad evita que su habilidad se convierta en arrogancia. Su confianza serena nace de la disciplina y no de la necesidad de dominar una sala."},"tournamentMotivation":{"en":"Shang-Chi enters to protect people from the kind of power that once shaped his life without consent. He believes disciplined cooperation can prevent fear from becoming control, and he will meet unfamiliar champions with patience before deciding how to fight. He will seek a peaceful understanding first, without confusing peace with surrender.","es":"Shang-Chi entra para proteger a la gente del tipo de poder que alguna vez moldeó su vida sin su consentimiento. Cree que la cooperación disciplinada puede impedir que el miedo se convierta en control y enfrentará a campeones desconocidos con paciencia antes de luchar. Buscará primero un entendimiento pacífico, sin confundir paz con rendición."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"shang-chi-lead","name":"Master of the Ten Rings","localizedName":{"en":"Master of the Ten Rings","es":"Master of the Ten Rings"},"description":{"en":"Shang-Chi leads through balance, timing and martial-arts discipline.","es":"Shang-Chi lidera con equilibrio, ritmo y disciplina marcial."},"effect":"DISRUPT","potency":0.15}}}'),
  ('storm', 'avengers-doomsday', 'Storm', 'PREFERRED', 'BLASTER', '/assets/heroes/storm.webp', 'avengers-content-v1', '{"stats":{"power":73,"agility":82,"resistance":75,"ability":96},"maxEnergy":239,"maxAbilityPoints":111,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Wind Cutter","es":"Wind Cutter"},"description":{"en":"Storm sends a razor-edged gust through the opening.","es":"Storm envía una ráfaga cortante por la abertura."}},"offensiveAbility":{"id":"storm-offensive","name":"Lightning Tempest","localizedName":{"en":"Lightning Tempest","es":"Lightning Tempest"},"description":{"en":"Storm calls lightning and wind across the opposing formation.","es":"Storm desata rayos y viento sobre la formación rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"storm-support","name":"Eye of the Storm","localizedName":{"en":"Eye of the Storm","es":"Eye of the Storm"},"description":{"en":"Storm channels weather control to strengthen the team''s attacks.","es":"Storm canaliza el control del clima para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["cyclops","wolverine"],"rivals":[],"biography":{"en":"Ororo Munroe is Storm, an omega-level mutant who commands wind, lightning and pressure with extraordinary precision. A former thief, queen and longtime member of the X-Men, she leads through empathy, clarity and the refusal to abandon people caught in conflict. Her weather responds to emotion, yet her leadership remains deliberate when everyone else panics.","es":"Ororo Munroe es Storm, una mutante de nivel omega que controla el viento, los rayos y la presión con precisión extraordinaria. Fue ladrona, reina y miembro histórica de los X-Men; lidera con empatía, claridad y la negativa a abandonar a quienes quedan atrapados en un conflicto. Su clima responde a la emoción, pero su liderazgo sigue siendo deliberado cuando los demás entran en pánico."},"tournamentMotivation":{"en":"Ororo joins because the collapse of realities threatens every community, not only the powerful. She wants the gathered teams to protect the vulnerable, to act with dignity across cultures and to ensure that no frightened population is left alone beneath a hostile sky. She will judge the teams by how they treat the powerless between battles.","es":"Ororo se une porque el colapso de las realidades amenaza a cada comunidad, no solo a los poderosos. Quiere que los equipos protejan a los vulnerables, actúen con dignidad entre culturas y no dejen sola a ninguna población bajo un cielo hostil. Juzgará a los equipos por cómo tratan a los indefensos entre batallas."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"DEFENSIVE","ability":{"id":"storm-lead","name":"Weather Command","localizedName":{"en":"Weather Command","es":"Weather Command"},"description":{"en":"Storm leads by reading the sky and the battle as one system.","es":"Storm lidera leyendo el cielo y la batalla como un mismo sistema."},"effect":"STRIKE","potency":1.7}}}'),
  ('cyclops', 'avengers-doomsday', 'Cyclops', 'PREFERRED', 'TACTICIAN', '/assets/heroes/cyclops.webp', 'avengers-content-v1', '{"stats":{"power":78,"agility":61,"resistance":77,"ability":98},"maxEnergy":215,"maxAbilityPoints":133,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Optic Burst","es":"Optic Burst"},"description":{"en":"Cyclops fires a focused optic beam through the opening.","es":"Cyclops dispara un rayo óptico concentrado por la abertura."}},"offensiveAbility":{"id":"cyclops-offensive","name":"Ruby Beam","localizedName":{"en":"Ruby Beam","es":"Ruby Beam"},"description":{"en":"Cyclops unleashes a sustained optic beam across the opposing formation.","es":"Cyclops desata un rayo óptico sostenido sobre la formación rival."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"cyclops-support","name":"Tactical Visor","localizedName":{"en":"Tactical Visor","es":"Tactical Visor"},"description":{"en":"Cyclops uses controlled optic precision to clear hindering effects from the team.","es":"Cyclops usa la precisión óptica controlada para despejar efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["jean-grey","storm"],"rivals":["wolverine"],"biography":{"en":"Scott Summers is Cyclops, the disciplined field leader of the X-Men whose optic blasts require constant control. He thinks in formations, contingencies and evacuation routes, but his command is rooted in protecting teammates and building a future where mutants do not have to live at war. He turns discipline into a way for frightened teammates to trust the next command.","es":"Scott Summers es Cyclops, el disciplinado líder de campo de los X-Men cuyos rayos ópticos requieren control constante. Piensa en formaciones, contingencias y rutas de evacuación, pero su mando nace de proteger a sus compañeros y construir un futuro sin guerra para los mutantes. Convierte la disciplina en una forma de que sus compañeros confíen en la próxima orden."},"tournamentMotivation":{"en":"Scott enters to keep the crisis from becoming another conflict decided over mutant lives. He will assess every team, coordinate with unfamiliar leaders and turn the tournament into a training ground for cooperation rather than a contest that leaves the vulnerable behind. Scott wants a plan that protects people even if the strongest team does not win.","es":"Scott entra para impedir que la crisis se convierta en otro conflicto decidido sobre vidas mutantes. Evaluará a cada equipo, coordinará con líderes desconocidos y convertirá el torneo en entrenamiento para cooperar, no en una competencia que abandone a los vulnerables. Scott quiere un plan que proteja a la gente aunque no gane el equipo más fuerte."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"DEFENSIVE","ability":{"id":"cyclops-lead","name":"Field Commander","localizedName":{"en":"Field Commander","es":"Field Commander"},"description":{"en":"Cyclops turns discipline and battlefield geometry into a clear order.","es":"Cyclops convierte la disciplina y la geometría del campo en una orden clara."},"effect":"PROTECT","potency":0.18}}}'),
  ('jean-grey', 'avengers-doomsday', 'Jean Grey', 'PREFERRED', 'MYSTIC', '/assets/heroes/jean-grey.webp', 'avengers-content-v1', '{"stats":{"power":65,"agility":59,"resistance":72,"ability":93},"maxEnergy":231,"maxAbilityPoints":145,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Psychic Pulse","es":"Psychic Pulse"},"description":{"en":"Jean Grey strikes with a focused telekinetic pulse.","es":"Jean Grey ataca con un pulso telequinético concentrado."}},"offensiveAbility":{"id":"jean-grey-offensive","name":"Phoenix Force","localizedName":{"en":"Phoenix Force","es":"Phoenix Force"},"description":{"en":"Jean Grey unleashes a blazing wave of Phoenix power.","es":"Jean Grey desata una oleada ardiente del poder Fénix."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"jean-grey-support","name":"Telekinetic Focus","localizedName":{"en":"Telekinetic Focus","es":"Telekinetic Focus"},"description":{"en":"Jean Grey uses psychic control to restore the team''s fighting strength.","es":"Jean Grey usa control psíquico para devolver fuerzas de combate al equipo."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["cyclops","professor-x"],"rivals":[],"biography":{"en":"Jean Grey is a powerful telepath and telekinetic whose empathy lets her feel the emotional currents of a room as sharply as its physical danger. She has faced overwhelming forces without surrendering her compassion, and she remains devoted to the people she loves. Her power is immense, but her empathy keeps another person''s pain from becoming background noise.","es":"Jean Grey es una poderosa telépata y telequinética cuya empatía le permite percibir las corrientes emocionales de una sala con tanta claridad como su peligro físico. Ha enfrentado fuerzas abrumadoras sin renunciar a la compasión y sigue dedicada a las personas que ama. Su poder es inmenso, pero su empatía impide que el dolor ajeno se vuelva ruido de fondo."},"tournamentMotivation":{"en":"Jean enters because she can sense how fear might spread when worlds begin to touch. She wants to calm that fear, protect minds as well as bodies and help the assembled heroes choose cooperation before panic turns their power against one another. She will help the teams recognize fear before fear controls their decisions.","es":"Jean entra porque puede percibir cómo se propagaría el miedo cuando los mundos comiencen a tocarse. Quiere calmarlo, proteger mentes además de cuerpos y ayudar a que los héroes elijan cooperar antes de que el pánico vuelva sus poderes contra ellos. Ayudará a los equipos a reconocer el miedo antes de que controle sus decisiones."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"jean-grey-lead","name":"Phoenix Guidance","localizedName":{"en":"Phoenix Guidance","es":"Phoenix Guidance"},"description":{"en":"Jean Grey leads through empathy, psychic insight and immense restraint.","es":"Jean Grey lidera con empatía, percepción psíquica y una enorme contención."},"effect":"HEAL","potency":1.1}}}'),
  ('professor-x', 'avengers-doomsday', 'Professor X', 'PREFERRED', 'MYSTIC', '/assets/heroes/professor-x.webp', 'avengers-content-v1', '{"stats":{"power":48,"agility":63,"resistance":58,"ability":91},"maxEnergy":193,"maxAbilityPoints":131,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Psychic Lance","es":"Psychic Lance"},"description":{"en":"Professor X drives a focused psychic lance through the opening.","es":"Professor X clava una lanza psíquica concentrada en la abertura."}},"offensiveAbility":{"id":"professor-x-offensive","name":"Cerebral Wave","localizedName":{"en":"Cerebral Wave","es":"Cerebral Wave"},"description":{"en":"Professor X strikes the opposing formation with a wave of psychic force.","es":"Professor X golpea la formación rival con una oleada de fuerza psíquica."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"professor-x-support","name":"Mind Link","localizedName":{"en":"Mind Link","es":"Mind Link"},"description":{"en":"Professor X channels a healing psychic link through the team.","es":"Professor X canaliza un vínculo psíquico sanador por todo el equipo."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["gambit","jean-grey"],"rivals":[],"biography":{"en":"Charles Xavier is the founder of the X-Men, a powerful telepath who believes humans and mutants can build a shared future. He teaches, counsels and coordinates from a mind trained to see possibilities, while carrying the responsibility of every student who trusts his guidance. His greatest lesson is that a mind''s potential matters only when it serves others.","es":"Charles Xavier es el fundador de los X-Men, un poderoso telépata que cree que humanos y mutantes pueden construir un futuro compartido. Enseña, aconseja y coordina con una mente entrenada para ver posibilidades, cargando con la responsabilidad de cada alumno que confía en él. Su mayor enseñanza es que el potencial de una mente solo importa cuando sirve a otros."},"tournamentMotivation":{"en":"Charles joins to keep a multiversal emergency from becoming an excuse for fear between peoples. He hopes the tournament can create dialogue between powerful communities, protect the next generation and demonstrate that survival does not require abandoning coexistence. He will make room for unfamiliar voices, especially those usually excluded from command.","es":"Charles se une para evitar que una emergencia multiversal se convierta en una excusa para el miedo entre pueblos. Espera que el torneo cree diálogo entre comunidades poderosas, proteja a la próxima generación y demuestre que sobrevivir no exige abandonar la convivencia. Dará espacio a voces desconocidas, especialmente a quienes suelen quedar fuera del mando."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"professor-x-lead","name":"Cerebral Command","localizedName":{"en":"Cerebral Command","es":"Cerebral Command"},"description":{"en":"Professor X coordinates every mind through calm strategic insight.","es":"Professor X coordina cada mente con una visión estratégica serena."},"effect":"HEAL","potency":1.1}}}'),
  ('star-lord', 'avengers-doomsday', 'Star-Lord', 'PREFERRED', 'TACTICIAN', '/assets/heroes/star-lord.webp', 'avengers-content-v1', '{"stats":{"power":60,"agility":75,"resistance":68,"ability":85},"maxEnergy":270,"maxAbilityPoints":127,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Quad Blaster Burst","es":"Quad Blaster Burst"},"description":{"en":"Star-Lord fires both quad blasters in a sharp opening burst.","es":"Star-Lord dispara sus dos quad blasters en una ráfaga precisa."}},"offensiveAbility":{"id":"star-lord-offensive","name":"Element Gun Barrage","localizedName":{"en":"Element Gun Barrage","es":"Element Gun Barrage"},"description":{"en":"Star-Lord switches elemental modes and floods the enemy line with firepower.","es":"Star-Lord cambia de modo elemental y llena la línea enemiga de potencia de fuego."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"star-lord-support","name":"Rallying Mix","localizedName":{"en":"Rallying Mix","es":"Rallying Mix"},"description":{"en":"Star-Lord uses improvisation and battlefield rhythm to clear hindering effects.","es":"Star-Lord usa improvisación y ritmo de combate para despejar efectos perjudiciales."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["rocket-raccoon","yondu"],"rivals":[],"biography":{"en":"Peter Quill is Star-Lord, a half-human spacefarer who became captain of the Guardians of the Galaxy through bold improvisation and hard-earned loyalty. He masks grief with swagger, but his instincts are tuned to finding a way home for a family assembled from unlikely survivors. His bravado hides a captain who has learned that a crew survives by trusting one another.","es":"Peter Quill es Star-Lord, un viajero espacial mitad humano que se convirtió en capitán de los Guardianes de la Galaxia mediante improvisación audaz y lealtad ganada con esfuerzo. Oculta el duelo con fanfarronería, pero siempre busca un camino de regreso para su familia de supervivientes improbables. Su fanfarronería oculta a un capitán que aprendió que una tripulación sobrevive confiando."},"tournamentMotivation":{"en":"Peter has seen worlds fall when nobody arrives in time. He accepts the tournament to represent the Guardians, protect the people beyond Earth''s horizon and keep powerful strangers from making a cosmic emergency worse through ego or fear. He wants a team capable of coming back for the people left behind.","es":"Peter ha visto caer mundos cuando nadie llega a tiempo. Acepta el torneo para representar a los Guardianes, proteger a quienes están más allá del horizonte terrestre y evitar que extraños poderosos empeoren una emergencia cósmica por ego o miedo. Quiere un equipo capaz de regresar por las personas que queden atrás."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"star-lord-lead","name":"Legendary Outlaw Plan","localizedName":{"en":"Legendary Outlaw Plan","es":"Legendary Outlaw Plan"},"description":{"en":"Star-Lord turns daring improvisation into a plan the team can follow.","es":"Star-Lord convierte la improvisación arriesgada en un plan que el equipo puede seguir."},"effect":"PROTECT","potency":0.18}}}'),
  ('rocket-raccoon', 'avengers-doomsday', 'Rocket Raccoon', 'PREFERRED', 'TACTICIAN', '/assets/heroes/rocket-raccoon.webp', 'avengers-content-v1', '{"stats":{"power":82,"agility":75,"resistance":69,"ability":92},"maxEnergy":260,"maxAbilityPoints":126,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Blaster Burst","es":"Blaster Burst"},"description":{"en":"Rocket Raccoon fires a compact blaster burst at the opening.","es":"Rocket Raccoon dispara una ráfaga compacta de bláster contra la abertura."}},"offensiveAbility":{"id":"rocket-raccoon-offensive","name":"Big Gun Barrage","localizedName":{"en":"Big Gun Barrage","es":"Big Gun Barrage"},"description":{"en":"Rocket Raccoon unloads an oversized weapon across the opposing formation.","es":"Rocket Raccoon descarga un arma descomunal sobre la formación rival."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"rocket-raccoon-support","name":"Gadget Patch","localizedName":{"en":"Gadget Patch","es":"Gadget Patch"},"description":{"en":"Rocket Raccoon uses a battlefield gadget to clear harmful effects from the team.","es":"Rocket Raccoon usa un dispositivo de combate para limpiar efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["gamora","star-lord"],"rivals":[],"biography":{"en":"Rocket is a genetically engineered, cybernetically enhanced raccoon with an engineer''s mind, a marksman''s instincts and a history of surviving experiments that treated him as property. He builds weapons and machines quickly, but values the odd family that chose him more than he admits. He builds with scraps because he knows how much value others overlook in a survivor.","es":"Rocket es un mapache modificado genéticamente y mejorado cibernéticamente, con mente de ingeniero, instinto de tirador y una historia de experimentos que lo trataron como propiedad. Construye armas y máquinas con rapidez, pero valora a su extraña familia más de lo que admite. Construye con restos porque sabe cuánto valor suelen ignorar en un superviviente."},"tournamentMotivation":{"en":"Rocket joins because the people trapped in collapsing worlds remind him of those nobody bothered to rescue. He wants enough information to build a solution, enough firepower to defend it and enough allies to keep the powerful from treating lives like spare parts. Rocket will look for a practical escape plan before anyone celebrates a theoretical victory.","es":"Rocket se une porque las personas atrapadas en mundos que colapsan le recuerdan a quienes nadie se molestó en rescatar. Quiere información para construir una solución, potencia para defenderla y aliados que impidan tratar vidas como piezas de repuesto. Rocket buscará una salida práctica antes de celebrar una victoria teórica."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"rocket-raccoon-lead","name":"Tactical Gadgetry","localizedName":{"en":"Tactical Gadgetry","es":"Tactical Gadgetry"},"description":{"en":"Rocket Raccoon leads through traps, gadgets and unapologetic preparation.","es":"Rocket Raccoon lidera con trampas, dispositivos y una preparación sin disculpas."},"effect":"PROTECT","potency":0.18}}}'),
  ('gamora', 'avengers-doomsday', 'Gamora', 'PREFERRED', 'SKIRMISHER', '/assets/heroes/gamora.webp', 'avengers-content-v1', '{"stats":{"power":66,"agility":98,"resistance":70,"ability":75},"maxEnergy":257,"maxAbilityPoints":81,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Godslayer Cut","es":"Godslayer Cut"},"description":{"en":"Gamora draws the Godslayer blade through the opening.","es":"Gamora traza un corte con la espada Godslayer por la abertura."}},"offensiveAbility":{"id":"gamora-offensive","name":"Godslayer Frenzy","localizedName":{"en":"Godslayer Frenzy","es":"Godslayer Frenzy"},"description":{"en":"Gamora turns the Godslayer blade into a relentless assault.","es":"Gamora convierte la espada Godslayer en una ofensiva implacable."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"gamora-support","name":"Assassin''s Footwork","localizedName":{"en":"Assassin''s Footwork","es":"Assassin''s Footwork"},"description":{"en":"Gamora uses precise movement to sharpen the team''s mobility.","es":"Gamora usa movimientos precisos para agudizar la movilidad del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["drax","rocket-raccoon"],"rivals":["nebula"],"biography":{"en":"Gamora is a master assassin who escaped a life shaped by Thanos and became one of the Guardians of the Galaxy. Her strength, precision and tactical discipline are tempered by the difficult work of choosing compassion over the violence she was taught. Her precision is not cruelty; it is the discipline she chose after escaping someone else''s design.","es":"Gamora es una asesina maestra que escapó de una vida moldeada por Thanos y se convirtió en una de las Guardianes de la Galaxia. Su fuerza, precisión y disciplina táctica conviven con el esfuerzo de elegir compasión frente a la violencia que le enseñaron. Su precisión no es crueldad: es la disciplina que eligió después de escapar de un diseño ajeno."},"tournamentMotivation":{"en":"Gamora enters because she knows what happens when one power decides that entire populations are acceptable losses. She will fight for worlds that cannot resist, test the intentions of the other teams and refuse to let survival become an excuse for tyranny. She will protect the powerless even when the safest choice would be to leave first.","es":"Gamora entra porque sabe qué ocurre cuando un poder decide que poblaciones enteras son pérdidas aceptables. Luchará por los mundos que no pueden resistir, pondrá a prueba las intenciones de los equipos y no permitirá que la supervivencia sea excusa para la tiranía. Protegerá a los indefensos aunque lo más seguro fuera marcharse primero."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"PRAGMATIC","ability":{"id":"gamora-lead","name":"Zealot Command","localizedName":{"en":"Zealot Command","es":"Zealot Command"},"description":{"en":"Gamora leads with discipline, focus and hard-earned battle instinct.","es":"Gamora lidera con disciplina, concentración e instinto de combate ganado."},"effect":"DISRUPT","potency":0.15}}}'),
  ('human-torch', 'avengers-doomsday', 'Human Torch', 'PREFERRED', 'BLASTER', '/assets/heroes/human-torch.webp', 'avengers-content-v1', '{"stats":{"power":74,"agility":76,"resistance":61,"ability":84},"maxEnergy":256,"maxAbilityPoints":130,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Flame Fist","es":"Flame Fist"},"description":{"en":"Human Torch drives a blazing fist through the opening.","es":"Human Torch descarga un puño en llamas por la abertura."}},"offensiveAbility":{"id":"human-torch-offensive","name":"Nova Burst","localizedName":{"en":"Nova Burst","es":"Nova Burst"},"description":{"en":"Human Torch engulfs the opposing formation in a burst of nova flame.","es":"Human Torch envuelve la formación rival en una explosión de fuego nova."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"human-torch-support","name":"Flame Screen","localizedName":{"en":"Flame Screen","es":"Flame Screen"},"description":{"en":"Human Torch uses controlled flame to strengthen the team''s attacks.","es":"Human Torch usa fuego controlado para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["invisible-woman","the-thing"],"rivals":["namor"],"biography":{"en":"Johnny Storm is the Human Torch, a fearless Fantastic Four adventurer who transforms into living flame, flies at incredible speed and shapes heat into controlled force. His confidence and competitive streak conceal a generous brother who always returns when his family needs him. Johnny''s flame is spectacular, but his courage is measured by when he lowers it to help.","es":"Johnny Storm es Human Torch, un aventurero intrépido de los Cuatro Fantásticos que se convierte en llama viviente, vuela a gran velocidad y moldea el calor con precisión. Su confianza y espíritu competitivo esconden a un hermano generoso que siempre vuelve cuando su familia lo necesita. La llama de Johnny es espectacular, pero su coraje se mide por cuándo la baja para ayudar."},"tournamentMotivation":{"en":"Johnny enters because the warning sounds bigger than any stunt he has attempted. He wants to keep the Fantastic Four together, prove that courage is more than bravado and make sure people facing a threat between worlds see a hero arrive instead of a spectacle. He wants his family and the other teams to face the unknown without losing their humanity.","es":"Johnny entra porque la advertencia parece mayor que cualquier hazaña que haya intentado. Quiere mantener unidos a los Cuatro Fantásticos, demostrar que el valor es algo más que fanfarronería y que quienes sufran entre mundos vean llegar un héroe, no un espectáculo. Quiere que su familia y los demás equipos enfrenten lo desconocido sin perder humanidad."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"human-torch-lead","name":"Supernova Call","localizedName":{"en":"Supernova Call","es":"Supernova Call"},"description":{"en":"Human Torch leads with daring energy and the courage to burn brighter.","es":"Human Torch lidera con energía audaz y el valor de arder más fuerte."},"effect":"STRIKE","potency":1.7}}}'),
  ('blade', 'avengers-doomsday', 'Blade', 'ELIGIBLE', 'SKIRMISHER', '/assets/heroes/blade.webp', 'avengers-content-v1', '{"stats":{"power":72,"agility":95,"resistance":59,"ability":68},"maxEnergy":256,"maxAbilityPoints":81,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Sword Draw","es":"Sword Draw"},"description":{"en":"Blade draws his sword in a single precise motion.","es":"Blade desenvaina su espada con un movimiento preciso."}},"offensiveAbility":{"id":"blade-offensive","name":"Daywalker Barrage","localizedName":{"en":"Daywalker Barrage","es":"Daywalker Barrage"},"description":{"en":"Blade combines swordplay and vampire-hunting firepower.","es":"Blade combina esgrima y potencia de fuego de cazavampiros."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"blade-support","name":"Hunter''s Focus","localizedName":{"en":"Hunter''s Focus","es":"Hunter''s Focus"},"description":{"en":"Blade uses hard-earned hunting instincts to sharpen team movement.","es":"Blade usa instintos de cazador para agudizar el movimiento del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":[],"rivals":["ghost-rider"],"biography":{"en":"Eric Brooks is Blade, a half-vampire hunter who uses enhanced strength, speed and senses against supernatural predators. He carries the knowledge of the darkness he fights without allowing it to define him, relying on discipline, weapons and a refusal to leave unfinished threats behind. He knows the supernatural has rules, even when the people facing it do not know them yet.","es":"Eric Brooks es Blade, un cazador mitad vampiro que usa fuerza, velocidad y sentidos mejorados contra depredadores sobrenaturales. Conoce la oscuridad que combate sin permitir que lo defina, y depende de la disciplina, las armas y la negativa a dejar amenazas inconclusas. Sabe que lo sobrenatural tiene reglas, aunque quienes lo enfrentan todavía no las conozcan."},"tournamentMotivation":{"en":"Blade joins because supernatural danger never stays inside one city for long. He does not need to understand every cosmic detail to recognize a breach that could feed monsters, and he will use the tournament to keep vulnerable worlds from becoming hunting grounds. He will follow evidence and protect the living before chasing a legend.","es":"Blade se une porque el peligro sobrenatural nunca permanece mucho tiempo en una sola ciudad. No necesita conocer cada detalle cósmico para reconocer una brecha que podría alimentar monstruos y usará el torneo para que los mundos vulnerables no se conviertan en cotos de caza. Seguirá las pruebas y protegerá a los vivos antes de perseguir una leyenda."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"blade-lead","name":"Daywalker Hunt","localizedName":{"en":"Daywalker Hunt","es":"Daywalker Hunt"},"description":{"en":"Blade leads through preparation, resolve and relentless pursuit.","es":"Blade lidera con preparación, determinación y persecución implacable."},"effect":"DISRUPT","potency":0.15}}}'),
  ('ms-marvel', 'avengers-doomsday', 'Ms. Marvel — Carol Danvers', 'ELIGIBLE', 'BLASTER', '/assets/heroes/ms-marvel.webp', 'avengers-content-v1', '{"stats":{"power":80,"agility":69,"resistance":73,"ability":85},"maxEnergy":250,"maxAbilityPoints":115,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Photon Strike","es":"Photon Strike"},"description":{"en":"Ms. Marvel — Carol Danvers channels a controlled burst of photon energy through the opening.","es":"Ms. Marvel — Carol Danvers canaliza una descarga controlada de energía fotónica sobre la abertura."}},"offensiveAbility":{"id":"ms-marvel-offensive","name":"Fracture Rescue","localizedName":{"en":"Fracture Rescue","es":"Fracture Rescue"},"description":{"en":"Ms. Marvel — Carol Danvers crosses the breach in a burst of flight and photon force to break the enemy line.","es":"Ms. Marvel — Carol Danvers cruza la fractura con un estallido de vuelo y fuerza fotónica para romper la línea enemiga."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"ms-marvel-support","name":"Photon Aegis","localizedName":{"en":"Photon Aegis","es":"Photon Aegis"},"description":{"en":"Ms. Marvel — Carol Danvers casts a focused photon barrier that reinforces allies under pressure.","es":"Ms. Marvel — Carol Danvers proyecta una barrera fotónica enfocada que refuerza a los aliados bajo presión."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["captain-marvel","war-machine"],"rivals":["rogue"],"biography":{"en":"On Earth-921, Carol Danvers never adopted the name Captain Marvel. She continued as Ms. Marvel and became one of the Avengers'' leaders. When incursions began tearing down the borders between universes, Carol crossed a fracture while trying to save her Earth and became stranded in the main universe, where she discovers that another version of herself chose a different path and became Captain Marvel.","es":"En la Tierra-921, Carol Danvers nunca adoptó el nombre Captain Marvel. Continuó su carrera como Ms. Marvel y terminó convirtiéndose en una de las líderes de los Avengers. Cuando las incursiones comenzaron a destruir las fronteras entre universos, Carol atravesó una de las fracturas intentando salvar su Tierra. Quedó varada en el universo principal, donde descubre que otra versión de ella misma tomó un camino diferente y se convirtió en Captain Marvel."},"tournamentMotivation":{"en":"Carol enters to protect the surviving worlds and find a way back to the Earth she could not abandon. As a stranded Avengers leader, she will coordinate the teams, keep the incursions from consuming another reality and face the unsettling truth of meeting the Carol Danvers who became Captain Marvel. Her resolve is grounded in rescue, accountability and the people still waiting for her return.","es":"Carol participa para proteger los mundos sobrevivientes y encontrar un camino de regreso a la Tierra que no pudo abandonar. Como líder de los Avengers varada entre realidades, coordinará a los equipos, impedirá que las incursiones consuman otra realidad y enfrentará la inquietante verdad de conocer a la Carol Danvers que se convirtió en Captain Marvel. Su determinación nace del rescate, la responsabilidad y las personas que todavía esperan su regreso."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"ms-marvel-lead","name":"Earth-921 Resolve","localizedName":{"en":"Earth-921 Resolve","es":"Earth-921 Resolve"},"description":{"en":"Ms. Marvel — Carol Danvers leads across realities with rescue discipline, accountability and unshaken resolve.","es":"Ms. Marvel — Carol Danvers lidera entre realidades con disciplina de rescate, responsabilidad y determinación inquebrantable."},"effect":"STRIKE","potency":1.7}}}'),
  ('gambit', 'avengers-doomsday', 'Gambit', 'ELIGIBLE', 'SKIRMISHER', '/assets/heroes/gambit.webp', 'avengers-content-v1', '{"stats":{"power":75,"agility":93,"resistance":61,"ability":69},"maxEnergy":230,"maxAbilityPoints":75,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Kinetic Card","es":"Kinetic Card"},"description":{"en":"Gambit charges a playing card and flicks it into the opening.","es":"Gambit carga una carta y la lanza contra la abertura."}},"offensiveAbility":{"id":"gambit-offensive","name":"Charged Cardstorm","localizedName":{"en":"Charged Cardstorm","es":"Charged Cardstorm"},"description":{"en":"Gambit floods the opposing formation with charged cards and staff strikes.","es":"Gambit llena la formación rival de cartas cargadas y golpes de bastón."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"gambit-support","name":"Kinetic Misdirection","localizedName":{"en":"Kinetic Misdirection","es":"Kinetic Misdirection"},"description":{"en":"Gambit uses charged objects and misdirection to sharpen team movement.","es":"Gambit usa objetos cargados y engaños para agudizar el movimiento del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["professor-x","rogue"],"rivals":[],"biography":{"en":"Remy LeBeau is Gambit, a charming thief and member of the X-Men who charges objects with explosive kinetic energy. He fights with a staff, cards and improvisation, carrying regret from his past while choosing loyalty to the people who gave him another chance. His charm is a defense, but his loyalty is the part of him he no longer hides.","es":"Remy LeBeau es Gambit, un ladrón carismático y miembro de los X-Men que carga objetos con energía cinética explosiva. Lucha con bastón, cartas e improvisación, y lleva el pesar de su pasado mientras elige ser leal a quienes le dieron otra oportunidad. Su encanto es una defensa, pero su lealtad es la parte que ya no oculta."},"tournamentMotivation":{"en":"Remy enters because a crisis crossing realities offers no safe place to hide and too many people to leave behind. He wants to repay the trust of the X-Men, protect communities that cannot bargain with cosmic powers and prove that his choices belong to him now. He will risk his own reputation before asking an innocent community to risk its future.","es":"Remy entra porque una crisis que cruza realidades no deja un escondite seguro ni permite abandonar a demasiadas personas. Quiere devolver la confianza de los X-Men, proteger comunidades sin poder frente a fuerzas cósmicas y demostrar que ahora sus decisiones le pertenecen. Arriesgará su reputación antes de pedir a una comunidad inocente que arriesgue su futuro."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"AGGRESSIVE","ability":{"id":"gambit-lead","name":"Ragin'' Cajun Gambit","localizedName":{"en":"Ragin'' Cajun Gambit","es":"Ragin'' Cajun Gambit"},"description":{"en":"Gambit leads with charm, risk and perfectly timed kinetic flair.","es":"Gambit lidera con encanto, riesgo y estilo cinético perfectamente calculado."},"effect":"DISRUPT","potency":0.15}}}'),
  ('rogue', 'avengers-doomsday', 'Rogue', 'ELIGIBLE', 'BRUISER', '/assets/heroes/rogue.webp', 'avengers-content-v1', '{"stats":{"power":84,"agility":51,"resistance":87,"ability":51},"maxEnergy":338,"maxAbilityPoints":71,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Power Leech","es":"Power Leech"},"description":{"en":"Rogue strikes while drawing on borrowed power.","es":"Rogue ataca mientras toma fuerza prestada."}},"offensiveAbility":{"id":"rogue-offensive","name":"Absorption Overload","localizedName":{"en":"Absorption Overload","es":"Absorption Overload"},"description":{"en":"Rogue unleashes a surge of absorbed power across the opposing line.","es":"Rogue desata una oleada de poder absorbido sobre la línea rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"rogue-support","name":"Borrowed Strength","localizedName":{"en":"Borrowed Strength","es":"Borrowed Strength"},"description":{"en":"Rogue turns absorbed power into momentum for the team''s attacks.","es":"Rogue convierte el poder absorbido en impulso para los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["gambit","nightcrawler"],"rivals":["captain-marvel","ms-marvel"],"biography":{"en":"Rogue is a powerful mutant whose touch can absorb another person''s memories, skills and powers. After years of fearing her own ability, she found belonging with the X-Men and learned to use that gift with restraint, courage and respect for the person on the other side of her hand. She treats another person''s memories as a responsibility, never as a prize to be collected.","es":"Rogue es una poderosa mutante cuyo contacto puede absorber recuerdos, habilidades y poderes ajenos. Tras años de temer su propia capacidad, encontró un lugar junto a los X-Men y aprendió a usarla con control, coraje y respeto por la persona que tiene delante. Trata los recuerdos ajenos como una responsabilidad, nunca como un premio que coleccionar."},"tournamentMotivation":{"en":"Rogue enters because she knows how easily power can erase a person''s sense of self. She wants to protect vulnerable communities, stand with the X-Men and help the teams face the crisis without treating one another as tools to be used and discarded. Rogue wants the teams to protect one another''s identities as carefully as their bodies.","es":"Rogue entra porque sabe con qué facilidad el poder puede borrar la identidad de una persona. Quiere proteger comunidades vulnerables, estar junto a los X-Men y enfrentar la crisis sin que los equipos se traten como herramientas descartables. Rogue quiere que los equipos protejan sus identidades con el mismo cuidado que sus cuerpos."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"rogue-lead","name":"X-Men Resolve","localizedName":{"en":"X-Men Resolve","es":"X-Men Resolve"},"description":{"en":"Rogue leads with courage, adaptability and the strength of many heroes.","es":"Rogue lidera con valor, adaptabilidad y la fuerza de muchos héroes."},"effect":"STRIKE","potency":1.8}}}'),
  ('the-thing', 'avengers-doomsday', 'The Thing', 'ELIGIBLE', 'BRUISER', '/assets/heroes/the-thing.webp', 'avengers-content-v1', '{"stats":{"power":96,"agility":61,"resistance":86,"ability":62},"maxEnergy":326,"maxAbilityPoints":71,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Rock Fist","es":"Rock Fist"},"description":{"en":"The Thing drives a rocky fist into the opening.","es":"The Thing descarga un puño de piedra sobre la abertura."}},"offensiveAbility":{"id":"the-thing-offensive","name":"Yancy Street Charge","localizedName":{"en":"Yancy Street Charge","es":"Yancy Street Charge"},"description":{"en":"The Thing charges through the formation with orange-rock strength.","es":"The Thing arremete contra la formación con su fuerza de piedra anaranjada."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"the-thing-support","name":"Rocky Momentum","localizedName":{"en":"Rocky Momentum","es":"Rocky Momentum"},"description":{"en":"The Thing turns his rocky strength into momentum for the team''s attacks.","es":"The Thing convierte su fuerza pétrea en impulso para los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["human-torch","reed-richards"],"rivals":["hulk"],"biography":{"en":"Ben Grimm is the Thing, a pilot and longtime member of the Fantastic Four whose rocky body gives him immense strength and durability. He often speaks plainly and fights head-on, but his defining quality is a steadfast heart that keeps his family together when fear takes over. Ben''s jokes make the weight easier to carry, but they never lessen his commitment to his family.","es":"Ben Grimm es The Thing, un piloto y miembro histórico de los Cuatro Fantásticos cuyo cuerpo rocoso le da una fuerza y resistencia inmensas. Habla claro y pelea de frente, pero su rasgo esencial es un corazón firme que mantiene unida a su familia cuando aparece el miedo. Los chistes de Ben alivian el peso, pero nunca reducen su compromiso con la familia."},"tournamentMotivation":{"en":"Ben enters because Reed''s warning is serious and because no one gets to threaten his family without meeting him first. He will stand between ordinary people and the danger, keep Johnny grounded and make sure the Fantastic Four face the unknown together. He will be the wall between the unknown and anyone who has no way to face it.","es":"Ben entra porque la advertencia de Reed es seria y porque nadie amenaza a su familia sin enfrentarse primero con él. Se pondrá entre la gente común y el peligro, mantendrá a Johnny con los pies en la tierra y afrontará lo desconocido junto a los Cuatro Fantásticos. Será el muro entre lo desconocido y quien no tenga cómo enfrentarlo."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":{"profile":"BALANCED","ability":{"id":"the-thing-lead","name":"Blue-Eyed Leadership","localizedName":{"en":"Blue-Eyed Leadership","es":"Blue-Eyed Leadership"},"description":{"en":"The Thing leads with loyalty, grit and the courage to stand his ground.","es":"The Thing lidera con lealtad, coraje y la decisión de no retroceder."},"effect":"STRIKE","potency":1.8}}}'),
  ('invisible-woman', 'avengers-doomsday', 'Invisible Woman', 'COMPANION_ONLY', 'GUARDIAN', '/assets/heroes/invisible-woman.webp', 'avengers-content-v1', '{"stats":{"power":79,"agility":65,"resistance":94,"ability":85},"maxEnergy":274,"maxAbilityPoints":102,"primaryRole":"SUPPORT","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Forceful Palm","es":"Forceful Palm"},"description":{"en":"Invisible Woman strikes with a focused invisible force.","es":"Invisible Woman ataca con una fuerza invisible concentrada."}},"offensiveAbility":{"id":"invisible-woman-offensive","name":"Invisible Pressure","localizedName":{"en":"Invisible Pressure","es":"Invisible Pressure"},"description":{"en":"Invisible Woman crushes the opening with unseen force.","es":"Invisible Woman aplasta la abertura con una fuerza invisible."},"apCost":30,"multiplier":1},"supportAbility":{"id":"invisible-woman-support","name":"Invisible Barrier","localizedName":{"en":"Invisible Barrier","es":"Invisible Barrier"},"description":{"en":"Invisible Woman raises an invisible shield around the team.","es":"Invisible Woman levanta un escudo invisible alrededor del equipo."},"apCost":25,"effect":"RESISTANCE","potency":0.15},"allies":["human-torch","reed-richards"],"rivals":["namor"],"biography":{"en":"Susan Storm Richards is Invisible Woman, a founding member of the Fantastic Four who bends light and creates powerful force fields. Her calm judgment, scientific curiosity and fierce protectiveness make her the family''s emotional anchor and one of its most formidable defenders. Her force fields can be precise enough to protect one person or strong enough to hold a team together.","es":"Susan Storm Richards es Invisible Woman, miembro fundadora de los Cuatro Fantásticos, capaz de curvar la luz y crear poderosos campos de fuerza. Su criterio sereno, curiosidad científica y protección feroz la convierten en el ancla emocional y defensiva de su familia. Sus campos de fuerza pueden proteger a una persona con precisión o sostener unido a un equipo entero."},"tournamentMotivation":{"en":"Sue enters because families and communities across realities deserve protection while others study the crisis. She will keep her team together, shield people who cannot fight and bring the Fantastic Four''s patience and courage to a threat no one can yet fully understand. Sue wants the tournament to leave families with a future, not only champions with a trophy.","es":"Sue entra porque las familias y comunidades de todas las realidades merecen protección mientras otros estudian la crisis. Mantendrá unido a su equipo, protegerá a quienes no puedan luchar y llevará la paciencia y el coraje de los Cuatro Fantásticos ante una amenaza que nadie comprende por completo. Sue quiere que el torneo deje un futuro para las familias, no solo un trofeo para los campeones."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('nightcrawler', 'avengers-doomsday', 'Nightcrawler', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/nightcrawler.webp', 'avengers-content-v1', '{"stats":{"power":67,"agility":96,"resistance":57,"ability":76},"maxEnergy":262,"maxAbilityPoints":86,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Bamf Strike","es":"Bamf Strike"},"description":{"en":"Nightcrawler teleports into the opening with a sudden strike.","es":"Nightcrawler se teletransporta a la abertura con un golpe repentino."}},"offensiveAbility":{"id":"nightcrawler-offensive","name":"Teleporting Flurry","localizedName":{"en":"Teleporting Flurry","es":"Teleporting Flurry"},"description":{"en":"Nightcrawler blinks through the formation and strikes from every angle.","es":"Nightcrawler se teletransporta por la formación y golpea desde todos los ángulos."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"nightcrawler-support","name":"Bamf Evasion","localizedName":{"en":"Bamf Evasion","es":"Bamf Evasion"},"description":{"en":"Nightcrawler uses teleportation to sharpen the team''s movement.","es":"Nightcrawler usa la teleportación para agudizar el movimiento del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["colossus","rogue"],"rivals":[],"biography":{"en":"Kurt Wagner is Nightcrawler, a blue-furred mutant who teleports in bursts of smoke and fights with acrobatic grace. His faith, humor and compassion survived persecution, giving him a talent for making frightened people feel less alone even in the middle of danger. He treats every teleport as a chance to carry someone toward safety rather than away from it.","es":"Kurt Wagner es Nightcrawler, un mutante de pelaje azul que se teletransporta entre nubes de humo y combate con gracia acrobática. Su fe, humor y compasión sobrevivieron a la persecución, y sabe hacer que la gente asustada se sienta menos sola incluso en peligro. Ve cada teletransporte como una oportunidad de llevar a alguien hacia la seguridad."},"tournamentMotivation":{"en":"Kurt joins because no world should be abandoned simply because its people look different or lack power. He wants to rescue those caught between realities, keep the X-Men compassionate under pressure and remind the teams that courage can arrive with a smile. He will look for the frightened person who cannot cross the next barrier alone.","es":"Kurt se une porque ningún mundo debe ser abandonado solo porque sus habitantes sean diferentes o carezcan de poder. Quiere rescatar a quienes queden entre realidades, mantener la compasión de los X-Men y recordar que el valor también puede llegar con una sonrisa. Buscará a la persona asustada que no pueda cruzar sola la próxima barrera."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('colossus', 'avengers-doomsday', 'Colossus', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/colossus.webp', 'avengers-content-v1', '{"stats":{"power":88,"agility":54,"resistance":83,"ability":51},"maxEnergy":311,"maxAbilityPoints":57,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Steel Fist","es":"Steel Fist"},"description":{"en":"Colossus drives an armored fist through the opening.","es":"Colossus descarga un puño acorazado sobre la abertura."}},"offensiveAbility":{"id":"colossus-offensive","name":"Organic Steel Charge","localizedName":{"en":"Organic Steel Charge","es":"Organic Steel Charge"},"description":{"en":"Colossus crashes through the formation in organic steel.","es":"Colossus irrumpe contra la formación convertido en acero orgánico."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"colossus-support","name":"Steel Momentum","localizedName":{"en":"Steel Momentum","es":"Steel Momentum"},"description":{"en":"Colossus turns his organic steel into force that drives the team''s attacks.","es":"Colossus convierte su acero orgánico en fuerza para impulsar los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["beast","nightcrawler"],"rivals":[],"biography":{"en":"Piotr Rasputin is Colossus, a gentle artist and member of the X-Men who transforms his body into organic steel. His strength and durability are matched by humility, loyalty and a willingness to place himself between danger and the people who cannot withstand it. His body can bear an enormous impact, but his gentleness determines what he protects with it.","es":"Piotr Rasputin es Colossus, un artista amable y miembro de los X-Men que transforma su cuerpo en acero orgánico. Su fuerza y resistencia se igualan con humildad, lealtad y la voluntad de ponerse entre el peligro y quienes no pueden soportarlo. Su cuerpo soporta impactos enormes, pero su gentileza decide qué protege con él."},"tournamentMotivation":{"en":"Piotr joins to serve as a shield for his teammates and for communities that have no champion. He trusts the X-Men''s example, wants to prevent fear from dividing humans and mutants and will carry whatever burden lets others reach safety. Piotr will carry the hardest burden so students and families have room to escape.","es":"Piotr se une para ser escudo de sus compañeros y de las comunidades que no tienen un campeón. Confía en el ejemplo de los X-Men, quiere impedir que el miedo divida a humanos y mutantes y cargará con cualquier peso que permita a otros llegar a salvo. Piotr cargará con el peso más duro para que estudiantes y familias puedan escapar."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('beast', 'avengers-doomsday', 'Beast', 'COMPANION_ONLY', 'TACTICIAN', '/assets/heroes/beast.webp', 'avengers-content-v1', '{"stats":{"power":63,"agility":77,"resistance":63,"ability":86},"maxEnergy":249,"maxAbilityPoints":113,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Feral Swipe","es":"Feral Swipe"},"description":{"en":"Beast answers with a powerful blue-furred swipe.","es":"Beast responde con un potente zarpazo de pelaje azul."}},"offensiveAbility":{"id":"beast-offensive","name":"Blue-Fur Barrage","localizedName":{"en":"Blue-Fur Barrage","es":"Blue-Fur Barrage"},"description":{"en":"Beast combines acrobatics and brute force in a sweeping assault.","es":"Beast combina acrobacias y fuerza bruta en una ofensiva amplia."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"beast-support","name":"Scientific Remedy","localizedName":{"en":"Scientific Remedy","es":"Scientific Remedy"},"description":{"en":"Beast uses science and quick hands to clear harmful effects.","es":"Beast usa ciencia y manos rápidas para limpiar efectos perjudiciales."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["colossus","iceman"],"rivals":[],"biography":{"en":"Hank McCoy is Beast, a brilliant mutant scientist whose blue-furred form combines remarkable strength and agility with a gift for research. He moves between laboratory and fieldwork, believing knowledge should serve coexistence rather than become another instrument of fear. His curiosity is tempered by the knowledge that a discovery can hurt people when handled without care.","es":"Hank McCoy es Beast, un brillante científico mutante cuya forma de pelaje azul combina fuerza y agilidad extraordinarias con un don para la investigación. Se mueve entre el laboratorio y el campo, convencido de que el conocimiento debe servir a la convivencia. Su curiosidad se equilibra con saber que un descubrimiento puede dañar si se usa sin cuidado."},"tournamentMotivation":{"en":"Hank enters to study the dimensional warning and make sure decisions are based on evidence rather than panic. He wants to protect students and civilians, share useful knowledge across teams and prevent a scientific crisis from becoming a political excuse for persecution. He wants shared evidence before shared power, so fear cannot write the conclusion.","es":"Hank entra para estudiar la advertencia dimensional y asegurar que las decisiones se basen en pruebas, no en pánico. Quiere proteger a estudiantes y civiles, compartir conocimiento útil entre equipos y evitar que una crisis científica se convierta en una excusa para perseguir. Quiere pruebas compartidas antes que poder compartido, para que el miedo no escriba la conclusión."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('iceman', 'avengers-doomsday', 'Iceman', 'COMPANION_ONLY', 'BLASTER', '/assets/heroes/iceman.webp', 'avengers-content-v1', '{"stats":{"power":91,"agility":68,"resistance":58,"ability":94},"maxEnergy":241,"maxAbilityPoints":135,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Ice Shard","es":"Ice Shard"},"description":{"en":"Iceman launches a shard of ice through the opening.","es":"Iceman lanza un fragmento de hielo por la abertura."}},"offensiveAbility":{"id":"iceman-offensive","name":"Absolute Zero","localizedName":{"en":"Absolute Zero","es":"Absolute Zero"},"description":{"en":"Iceman freezes the opposing formation beneath a wave of cold.","es":"Iceman congela la formación rival bajo una oleada de frío."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"iceman-support","name":"Ice Rampart","localizedName":{"en":"Ice Rampart","es":"Ice Rampart"},"description":{"en":"Iceman raises ice cover to strengthen the team''s attacks.","es":"Iceman levanta una cobertura de hielo para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["beast","psylocke"],"rivals":[],"biography":{"en":"Bobby Drake is Iceman, an omega-level mutant who can create, shape and become ice. His humor masks a thoughtful hero who has spent years learning that control is not the same as suppression, and that his power can preserve life as readily as it can stop an attacker. He can turn a dangerous space into a bridge, a shelter or a pause long enough to breathe.","es":"Bobby Drake es Iceman, un mutante de nivel omega que puede crear, moldear y convertirse en hielo. Su humor oculta a un héroe reflexivo que aprendió que el control no es represión y que su poder puede preservar la vida tanto como detener a un atacante. Puede convertir un espacio peligroso en puente, refugio o pausa suficiente para respirar."},"tournamentMotivation":{"en":"Bobby joins because people need time and safe routes when realities become unstable. He wants to protect the younger mutants, cool conflicts before they become disasters and help the X-Men show that immense power can be used with care. Bobby will protect people from the heat of panic as carefully as from physical danger.","es":"Bobby se une porque la gente necesita tiempo y rutas seguras cuando las realidades se vuelven inestables. Quiere proteger a los mutantes jóvenes, enfriar los conflictos antes de que sean desastres y mostrar que un gran poder puede usarse con cuidado. Bobby protegerá a la gente del calor del pánico tanto como del peligro físico."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('psylocke', 'avengers-doomsday', 'Psylocke', 'COMPANION_ONLY', 'MYSTIC', '/assets/heroes/psylocke.webp', 'avengers-content-v1', '{"stats":{"power":49,"agility":63,"resistance":66,"ability":97},"maxEnergy":209,"maxAbilityPoints":133,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Psychic Blade","es":"Psychic Blade"},"description":{"en":"Psylocke cuts through the opening with a psychic blade.","es":"Psylocke corta la abertura con una hoja psíquica."}},"offensiveAbility":{"id":"psylocke-offensive","name":"Psi-Katana Flurry","localizedName":{"en":"Psi-Katana Flurry","es":"Psi-Katana Flurry"},"description":{"en":"Psylocke unleashes a storm of psychic katana strikes.","es":"Psylocke desata una tormenta de tajos con su katana psíquica."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"psylocke-support","name":"Mindful Focus","localizedName":{"en":"Mindful Focus","es":"Mindful Focus"},"description":{"en":"Psylocke uses psychic focus to restore the team''s fighting strength.","es":"Psylocke usa concentración psíquica para devolver fuerzas de combate al equipo."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["iceman","jubilee"],"rivals":[],"biography":{"en":"Betsy Braddock is Psylocke, a telepathic warrior who shapes psychic energy into blades and precise attacks. Her life has crossed cultures, bodies and battlefields, teaching her to protect her identity and use discipline when the mind can be as dangerous as any weapon. Her psychic blades require focus, and her life has taught her to defend the mind behind every face.","es":"Betsy Braddock es Psylocke, una guerrera telépata que convierte la energía psíquica en hojas y ataques precisos. Su vida cruzó culturas, cuerpos y campos de batalla, y le enseñó a proteger su identidad y actuar con disciplina cuando la mente puede ser un arma. Sus hojas psíquicas exigen concentración, y su vida le enseñó a defender la mente detrás de cada rostro."},"tournamentMotivation":{"en":"Betsy enters because a crisis between realities will test minds as much as muscles. She intends to defend her teammates from manipulation, protect people whose thoughts cannot shield them and ensure that power does not erase the identities it claims to save. She will challenge any solution that treats a person''s mind as an acceptable battlefield.","es":"Betsy entra porque una crisis entre realidades pondrá a prueba tanto las mentes como los músculos. Defenderá a sus compañeros de la manipulación, protegerá a quienes no pueden resguardar sus pensamientos y evitará que el poder borre las identidades que pretende salvar. Cuestionará cualquier solución que trate la mente de alguien como un campo de batalla aceptable."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('jubilee', 'avengers-doomsday', 'Jubilee', 'COMPANION_ONLY', 'BLASTER', '/assets/heroes/jubilee.webp', 'avengers-content-v1', '{"stats":{"power":86,"agility":76,"resistance":69,"ability":86},"maxEnergy":268,"maxAbilityPoints":104,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Plasma Spark","es":"Plasma Spark"},"description":{"en":"Jubilee fires a burst of dazzling plasma.","es":"Jubilee dispara una ráfaga de plasma deslumbrante."}},"offensiveAbility":{"id":"jubilee-offensive","name":"Firework Burst","localizedName":{"en":"Firework Burst","es":"Firework Burst"},"description":{"en":"Jubilee fills the opposing formation with explosive fireworks.","es":"Jubilee llena la formación rival de fuegos artificiales explosivos."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"jubilee-support","name":"Blinding Flare","localizedName":{"en":"Blinding Flare","es":"Blinding Flare"},"description":{"en":"Jubilee uses controlled light to strengthen the team''s attacks.","es":"Jubilee usa luz controlada para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["kitty-pryde","psylocke"],"rivals":[],"biography":{"en":"Jubilation Lee is Jubilee, a young mutant who creates colorful plasmoids that burst with controlled force. Her energy, humor and loyalty make her more than the team''s spark; she has grown into a protector who refuses to let hardship take away her joy. Her bright energy is a deliberate refusal to let persecution decide what joy is allowed to look like.","es":"Jubilation Lee es Jubilee, una joven mutante que crea plasmoides coloridos que estallan con fuerza controlada. Su energía, humor y lealtad la vuelven más que la chispa del equipo: creció como protectora sin permitir que las dificultades le quitaran la alegría. Su energía brillante es la decisión de no dejar que la persecución defina la alegría."},"tournamentMotivation":{"en":"Jubilee joins because younger mutants deserve to see heroes choose them when the stakes become frightening. She wants to keep families together, support the X-Men and prove that optimism is not denial; it is the energy that helps people keep moving. She will give frightened young people a reason to believe the adults have not abandoned them.","es":"Jubilee se une porque los mutantes jóvenes merecen ver que los héroes los eligen cuando la situación se vuelve aterradora. Quiere mantener unidas a las familias, apoyar a los X-Men y demostrar que el optimismo no es negación, sino la energía para seguir avanzando. Dará a los jóvenes asustados una razón para creer que los adultos no los abandonaron."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('kitty-pryde', 'avengers-doomsday', 'Kitty Pryde / Shadowcat', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/kitty-pryde.webp', 'avengers-content-v1', '{"stats":{"power":68,"agility":94,"resistance":73,"ability":74},"maxEnergy":234,"maxAbilityPoints":90,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Phasing Strike","es":"Phasing Strike"},"description":{"en":"Kitty Pryde / Shadowcat phases through the defense and strikes from within.","es":"Kitty Pryde / Shadowcat atraviesa la defensa y golpea desde dentro."}},"offensiveAbility":{"id":"kitty-pryde-offensive","name":"Phased Assault","localizedName":{"en":"Phased Assault","es":"Phased Assault"},"description":{"en":"Kitty Pryde / Shadowcat moves through the formation with untouchable precision.","es":"Kitty Pryde / Shadowcat atraviesa la formación con una precisión intocable."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"kitty-pryde-support","name":"Phasing Rescue","localizedName":{"en":"Phasing Rescue","es":"Phasing Rescue"},"description":{"en":"Kitty Pryde / Shadowcat uses phasing to sharpen the team''s mobility.","es":"Kitty Pryde / Shadowcat usa su intangibilidad para agudizar la movilidad del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["jubilee","magik"],"rivals":[],"biography":{"en":"Kitty Pryde, also known as Shadowcat, is a gifted X-Men hero who can phase through solid matter and protect others with ingenuity. She grew from a young student into a teacher and leader, carrying technical skill and hard-earned confidence into every mission. She knows a barrier is a problem to solve, not a reason to leave someone on the other side.","es":"Kitty Pryde, también conocida como Shadowcat, es una heroína talentosa de los X-Men que atraviesa la materia y protege a otros con ingenio. Pasó de ser una estudiante a convertirse en maestra y líder, llevando habilidad técnica y confianza ganada a cada misión. Sabe que una barrera es un problema por resolver, no una razón para dejar a alguien del otro lado."},"tournamentMotivation":{"en":"Kitty enters because the people trapped between realities will need someone able to reach them through walls, barriers and confusion. She wants to protect students and civilians, connect teams that do not yet trust each other and turn the tournament into a rescue effort as well as a contest. Kitty will connect teams through practical rescues before asking them to trust one another.","es":"Kitty entra porque quienes queden atrapados entre realidades necesitarán a alguien capaz de atravesar muros, barreras y confusión. Quiere proteger a estudiantes y civiles, conectar equipos que aún no confían entre sí y convertir el torneo también en una misión de rescate. Kitty conectará a los equipos mediante rescates concretos antes de pedir confianza."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('magik', 'avengers-doomsday', 'Magik', 'COMPANION_ONLY', 'MYSTIC', '/assets/heroes/magik.webp', 'avengers-content-v1', '{"stats":{"power":47,"agility":78,"resistance":55,"ability":93},"maxEnergy":232,"maxAbilityPoints":129,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Soulsword Slash","es":"Soulsword Slash"},"description":{"en":"Magik cuts through the opening with the Soulsword.","es":"Magik corta la abertura con la Soulsword."}},"offensiveAbility":{"id":"magik-offensive","name":"Stepping Disc Assault","localizedName":{"en":"Stepping Disc Assault","es":"Stepping Disc Assault"},"description":{"en":"Magik opens stepping discs and attacks from impossible angles.","es":"Magik abre discos de teletransporte y ataca desde ángulos imposibles."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"magik-support","name":"Limbo Ward","localizedName":{"en":"Limbo Ward","es":"Limbo Ward"},"description":{"en":"Magik channels Limbo magic to restore the team''s strength.","es":"Magik canaliza magia del Limbo para devolver fuerzas al equipo."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["ghost-rider","kitty-pryde","scarlet-witch","x-23"],"rivals":[],"biography":{"en":"Illyana Rasputin is Magik, a mutant sorcerer who rules a path through Limbo and wields the Soulsword. Her teleportation and magic were forged through trauma, yet she protects her friends with a blunt courage that refuses to confuse darkness with evil. Her knowledge of Limbo taught her that surviving darkness does not mean becoming part of it.","es":"Illyana Rasputin es Magik, una hechicera mutante que abre caminos por el Limbo y empuña la Espada Alma. Su teletransportación y magia nacieron del trauma, pero protege a sus amigos con un coraje directo que no confunde la oscuridad con el mal. Su conocimiento del Limbo le enseñó que sobrevivir a la oscuridad no significa pertenecer a ella."},"tournamentMotivation":{"en":"Illyana joins because barriers between realities are not an abstract idea to her; they are places she has crossed and survived. She wants to keep hostile forces from reaching innocent worlds and give the X-Men a guide through dangers others cannot even see. She will open a path for those without one, even when the destination frightens her too.","es":"Illyana se une porque las barreras entre realidades no son una idea abstracta para ella: son lugares que atravesó y sobrevivió. Quiere impedir que fuerzas hostiles alcancen mundos inocentes y guiar a los X-Men por peligros que otros ni siquiera pueden ver. Abrirá un camino para quienes no lo tengan, aunque el destino también la asuste."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('x-23', 'avengers-doomsday', 'X-23 / Laura Kinney', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/x-23.webp', 'avengers-content-v1', '{"stats":{"power":70,"agility":93,"resistance":63,"ability":76},"maxEnergy":252,"maxAbilityPoints":90,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Claw Rake","es":"Claw Rake"},"description":{"en":"X-23 / Laura Kinney rips through the opening with adamantium claws.","es":"X-23 / Laura Kinney desgarra la abertura con garras de adamantium."}},"offensiveAbility":{"id":"x-23-offensive","name":"Berserker Talons","localizedName":{"en":"Berserker Talons","es":"Berserker Talons"},"description":{"en":"X-23 / Laura Kinney turns speed and claws into a relentless assault.","es":"X-23 / Laura Kinney convierte velocidad y garras en una ofensiva implacable."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"x-23-support","name":"Hunter''s Footwork","localizedName":{"en":"Hunter''s Footwork","es":"Hunter''s Footwork"},"description":{"en":"X-23 / Laura Kinney uses predator instincts to sharpen the team''s mobility.","es":"X-23 / Laura Kinney usa instintos de depredadora para agudizar la movilidad del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["cable","magik"],"rivals":[],"biography":{"en":"Laura Kinney is X-23, a mutant with claws, heightened senses and a healing factor who was raised as a weapon before choosing her own name and life. She remains fierce in combat, but her identity is now defined by found family, compassion and self-determination. Every choice she makes now is proof that a weapon can become a person with a future.","es":"Laura Kinney es X-23, una mutante con garras, sentidos aumentados y factor curativo que fue criada como arma antes de elegir su propio nombre y vida. Sigue siendo feroz en combate, pero su identidad ahora la definen la familia elegida, la compasión y la autodeterminación. Cada elección que hace demuestra que un arma puede convertirse en una persona con futuro."},"tournamentMotivation":{"en":"Laura enters to protect the people who gave her a life beyond violence, especially younger mutants who deserve choices she was denied. She will confront the threat directly, but her real measure of victory is bringing her chosen family home. Laura will put the safety of younger mutants ahead of any demand to prove herself.","es":"Laura entra para proteger a quienes le dieron una vida más allá de la violencia, especialmente a los mutantes jóvenes que merecen las opciones que a ella le negaron. Enfrentará la amenaza de frente, pero medirá la victoria por el regreso de su familia elegida. Laura pondrá la seguridad de los mutantes jóvenes por delante de demostrar su valor."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('cable', 'avengers-doomsday', 'Cable', 'COMPANION_ONLY', 'TACTICIAN', '/assets/heroes/cable.webp', 'avengers-content-v1', '{"stats":{"power":60,"agility":61,"resistance":73,"ability":92},"maxEnergy":239,"maxAbilityPoints":100,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Telekinetic Strike","es":"Telekinetic Strike"},"description":{"en":"Cable drives a telekinetic blow through the opening.","es":"Cable descarga un golpe telequinético sobre la abertura."}},"offensiveAbility":{"id":"cable-offensive","name":"Future Arsenal","localizedName":{"en":"Future Arsenal","es":"Future Arsenal"},"description":{"en":"Cable combines heavy weapons and telekinesis across the enemy line.","es":"Cable combina armas pesadas y telequinesis sobre la línea rival."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"cable-support","name":"Time-Soldier Reset","localizedName":{"en":"Time-Soldier Reset","es":"Time-Soldier Reset"},"description":{"en":"Cable uses tactical technology to clear harmful effects from the team.","es":"Cable usa tecnología táctica para limpiar efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["x-23"],"rivals":["bishop"],"biography":{"en":"Nathan Summers is Cable, a time-displaced soldier and telekinetic whose cybernetic body bears the cost of wars fought for mutant survival. He carries hard-earned military judgment, but his strongest instinct is to protect the people who might otherwise inherit the future he has already seen. His implants and memories are reminders that survival always has a human price.","es":"Nathan Summers es Cable, un soldado desplazado en el tiempo y telequinético cuyo cuerpo cibernético carga el costo de guerras por la supervivencia mutante. Tiene criterio militar ganado a la fuerza, pero su instinto principal es proteger a quienes podrían heredar un futuro que él ya conoció. Sus implantes y recuerdos le recuerdan que sobrevivir siempre tiene un precio humano."},"tournamentMotivation":{"en":"Cable joins because a warning about collapsing realities sounds like the beginning of the kind of disaster he has spent his life trying to prevent. He will not claim to know this future, but he will prepare the teams, protect the young and act before history demands another sacrifice. He will prepare contingencies without mistaking preparation for certainty.","es":"Cable se une porque una advertencia sobre realidades que colapsan suena al inicio de la clase de desastre que intentó evitar toda su vida. No afirma conocer este futuro, pero preparará a los equipos, protegerá a los jóvenes y actuará antes de que la historia exija otro sacrificio. Preparará contingencias sin confundir preparación con certeza."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('bishop', 'avengers-doomsday', 'Bishop', 'COMPANION_ONLY', 'BLASTER', '/assets/heroes/bishop.webp', 'avengers-content-v1', '{"stats":{"power":75,"agility":84,"resistance":74,"ability":89},"maxEnergy":261,"maxAbilityPoints":115,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Energy Shot","es":"Energy Shot"},"description":{"en":"Bishop absorbs incoming energy and fires it back.","es":"Bishop absorbe energía entrante y la devuelve en un disparo."}},"offensiveAbility":{"id":"bishop-offensive","name":"Energy Drain","localizedName":{"en":"Energy Drain","es":"Energy Drain"},"description":{"en":"Bishop turns stolen energy into a blast across the opposing line.","es":"Bishop convierte la energía robada en una descarga sobre la línea rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"bishop-support","name":"Energy Redirect","localizedName":{"en":"Energy Redirect","es":"Energy Redirect"},"description":{"en":"Bishop channels stored energy to strengthen the team''s attacks.","es":"Bishop canaliza energía almacenada para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["quicksilver"],"rivals":["cable"],"biography":{"en":"Lucas Bishop is a mutant soldier from a troubled future who can absorb and redirect energy. Trained as a law-enforcement officer and shaped by conflict, he joined the X-Men to prevent the catastrophes that once defined his history, even when trust had to be earned slowly. He carries the discipline of a future police force while learning to live outside its assumptions.","es":"Lucas Bishop es un soldado mutante de un futuro difícil que absorbe y redirige energía. Entrenado como agente de seguridad y marcado por el conflicto, se unió a los X-Men para evitar las catástrofes que definieron su historia, aunque la confianza tuviera que ganarse. Lleva la disciplina de una fuerza policial futura mientras aprende a vivir fuera de sus supuestos."},"tournamentMotivation":{"en":"Bishop enters because a future where realities fail would punish people who never had a chance to choose differently. He will watch for warning signs, protect the X-Men and help the teams act early without pretending that every danger can be solved by force. Bishop will protect the present without treating it as a script already written.","es":"Bishop entra porque un futuro donde fallen las realidades castigaría a personas que nunca pudieron elegir distinto. Vigilará las señales de peligro, protegerá a los X-Men y ayudará a actuar pronto sin fingir que toda amenaza se resuelve con fuerza. Bishop protegerá el presente sin tratarlo como un guion ya escrito."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('drax', 'avengers-doomsday', 'Drax', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/drax.webp', 'avengers-content-v1', '{"stats":{"power":86,"agility":64,"resistance":91,"ability":71},"maxEnergy":305,"maxAbilityPoints":59,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Destroyer Blow","es":"Destroyer Blow"},"description":{"en":"Drax answers the opening with a destroyer''s strike.","es":"Drax responde a la abertura con un golpe del Destructor."}},"offensiveAbility":{"id":"drax-offensive","name":"Destroyer''s Charge","localizedName":{"en":"Destroyer''s Charge","es":"Destroyer''s Charge"},"description":{"en":"Drax charges straight through the opposing formation.","es":"Drax arremete de frente contra la formación rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"drax-support","name":"Warrior''s Focus","localizedName":{"en":"Warrior''s Focus","es":"Warrior''s Focus"},"description":{"en":"Drax turns single-minded purpose into momentum for the team.","es":"Drax convierte su propósito inquebrantable en impulso para el equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["gamora","groot"],"rivals":[],"biography":{"en":"Drax is a Guardian of the Galaxy whose immense strength and direct manner hide a loyal heart. Once driven by vengeance, he found purpose among friends who taught him that protecting a family can be as meaningful as defeating an enemy. His literal honesty makes him easy to underestimate until the fight becomes personal.","es":"Drax es un Guardián de la Galaxia cuya enorme fuerza y manera directa esconden un corazón leal. Antes lo impulsaba la venganza, pero encontró un propósito junto a amigos que le enseñaron que proteger una familia importa tanto como derrotar a un enemigo. Su honestidad literal hace que lo subestimen hasta que la lucha se vuelve personal."},"tournamentMotivation":{"en":"Drax joins because he understands what it means to lose a home and the people who made it one. He will fight for worlds whose defenders are gone, stand beside the Guardians and make certain the crisis does not take another family without a fight. He will stay when others retreat because leaving a family behind is not acceptable to him.","es":"Drax se une porque entiende lo que significa perder un hogar y a quienes lo convertían en hogar. Luchará por mundos cuyos defensores ya no están, estará junto a los Guardianes y no permitirá que la crisis se lleve otra familia sin resistencia. Se quedará cuando otros retrocedan porque para él abandonar una familia no es aceptable."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('groot', 'avengers-doomsday', 'Groot', 'COMPANION_ONLY', 'GUARDIAN', '/assets/heroes/groot.webp', 'avengers-content-v1', '{"stats":{"power":69,"agility":70,"resistance":87,"ability":76},"maxEnergy":275,"maxAbilityPoints":110,"primaryRole":"SUPPORT","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Branch Strike","es":"Branch Strike"},"description":{"en":"Groot swings a heavy branch through the opening.","es":"Groot balancea una rama pesada sobre la abertura."}},"offensiveAbility":{"id":"groot-offensive","name":"Rooted Rampage","localizedName":{"en":"Rooted Rampage","es":"Rooted Rampage"},"description":{"en":"Groot surges across the battlefield with roots and branches.","es":"Groot se abalanza por el campo de batalla con raíces y ramas."},"apCost":30,"multiplier":1},"supportAbility":{"id":"groot-support","name":"Living Cover","localizedName":{"en":"Living Cover","es":"Living Cover"},"description":{"en":"Groot grows living cover around the team.","es":"Groot hace crecer una cobertura viviente alrededor del equipo."},"apCost":25,"effect":"RESISTANCE","potency":0.15},"allies":["drax","mantis"],"rivals":[],"biography":{"en":"Groot is a sentient tree-like Guardian whose roots, branches and remarkable regeneration make him both protector and battlefield shelter. He communicates in a simple phrase, but his loyalty, patience and willingness to grow around his friends speak clearly to everyone who travels with him. His roots make a living promise that protection can grow around everyone, not only the strongest.","es":"Groot es un Guardián arbóreo consciente cuyas raíces, ramas y notable regeneración lo convierten en protector y refugio de batalla. Se comunica con una frase sencilla, pero su lealtad, paciencia y voluntad de crecer junto a sus amigos hablan con claridad. Sus raíces prometen que la protección puede crecer alrededor de todos, no solo de los fuertes."},"tournamentMotivation":{"en":"Groot joins because the Guardians defend families wherever they find them, and collapsing worlds would leave too many people without shelter. He will stand between danger and the frightened, grow where a path is needed and keep his friends together. Groot will make space for the small, the lost and the friends who need somewhere to stand.","es":"Groot se une porque los Guardianes defienden a las familias donde las encuentran, y los mundos que colapsan dejarían a demasiadas personas sin refugio. Se interpondrá ante el peligro, crecerá donde haga falta un camino y mantendrá unidos a sus amigos. Groot hará lugar para los pequeños, los perdidos y los amigos que necesiten dónde estar."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('mantis', 'avengers-doomsday', 'Mantis', 'COMPANION_ONLY', 'MYSTIC', '/assets/heroes/mantis.webp', 'avengers-content-v1', '{"stats":{"power":59,"agility":57,"resistance":56,"ability":91},"maxEnergy":207,"maxAbilityPoints":134,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Empathic Touch","es":"Empathic Touch"},"description":{"en":"Mantis strikes with a precise empathic pulse.","es":"Mantis ataca con un pulso empático preciso."}},"offensiveAbility":{"id":"mantis-offensive","name":"Empathic Wave","localizedName":{"en":"Empathic Wave","es":"Empathic Wave"},"description":{"en":"Mantis sends a wave of empathic force through the opposing formation.","es":"Mantis envía una oleada de fuerza empática por la formación rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"mantis-support","name":"Emotional Recenter","localizedName":{"en":"Emotional Recenter","es":"Emotional Recenter"},"description":{"en":"Mantis uses empathy to restore the team''s strength.","es":"Mantis usa empatía para devolver fuerzas al equipo."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["groot","nebula"],"rivals":[],"biography":{"en":"Mantis is an empathic Guardian who senses emotions and can influence them through touch. Raised apart from ordinary society, she learned to understand herself through friendship, turning unusual sensitivity into a source of compassion and a way to calm people in crisis. Her sensitivity can be overwhelming, but it also lets her notice pain that others hide.","es":"Mantis es una Guardiana empática que percibe las emociones y puede influir en ellas mediante el contacto. Criada apartada de la sociedad común, aprendió a comprenderse a través de la amistad y convirtió su sensibilidad en compasión para calmar crisis. Su sensibilidad puede abrumarla, pero también le permite notar el dolor que otros ocultan."},"tournamentMotivation":{"en":"Mantis enters because fear can destroy cooperation before any cosmic enemy arrives. She wants to help frightened teams listen to one another, protect civilians from panic and remind powerful heroes that every reality is made of feelings as well as stars. She wants the teams to name their fear so it cannot quietly choose their actions.","es":"Mantis entra porque el miedo puede destruir la cooperación antes de que llegue cualquier enemigo cósmico. Quiere ayudar a que los equipos se escuchen, proteger a los civiles del pánico y recordar que cada realidad está hecha de sentimientos además de estrellas. Quiere que los equipos nombren su miedo para que no elija sus acciones en silencio."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('nebula', 'avengers-doomsday', 'Nebula', 'COMPANION_ONLY', 'TACTICIAN', '/assets/heroes/nebula.webp', 'avengers-content-v1', '{"stats":{"power":81,"agility":61,"resistance":73,"ability":87},"maxEnergy":247,"maxAbilityPoints":105,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Cybernetic Blade","es":"Cybernetic Blade"},"description":{"en":"Nebula cuts through the opening with a cybernetic blade.","es":"Nebula corta la abertura con una hoja cibernética."}},"offensiveAbility":{"id":"nebula-offensive","name":"Neural Overload","localizedName":{"en":"Neural Overload","es":"Neural Overload"},"description":{"en":"Nebula floods the opposing formation with cybernetic force.","es":"Nebula inunda la formación rival con fuerza cibernética."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"nebula-support","name":"System Purge","localizedName":{"en":"System Purge","es":"System Purge"},"description":{"en":"Nebula uses cybernetic precision to clear harmful effects from the team.","es":"Nebula usa precisión cibernética para limpiar efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["adam-warlock","mantis"],"rivals":["gamora"],"biography":{"en":"Nebula is a cybernetically altered survivor who endured brutal training and constant comparison before choosing the Guardians as her family. Her tactical mind, mechanical upgrades and hard-edged honesty come from a life she is determined to define on her own terms. She understands machinery and betrayal, and neither has to determine what she becomes next.","es":"Nebula es una superviviente alterada cibernéticamente que soportó entrenamiento brutal y comparaciones constantes antes de elegir a los Guardianes como familia. Su mente táctica, mejoras mecánicas y honestidad áspera nacen de una vida que ahora define por sí misma. Comprende la maquinaria y la traición, y ninguna de las dos debe decidir quién será después."},"tournamentMotivation":{"en":"Nebula joins because she knows what happens when powerful people treat entire worlds as tools. She wants to protect the family she chose, learn who is manipulating the crisis and make sure the vulnerable are not measured by someone else''s idea of usefulness. Nebula will protect her chosen family while refusing to let anyone own the outcome.","es":"Nebula se une porque sabe qué ocurre cuando los poderosos tratan mundos enteros como herramientas. Quiere proteger a la familia que eligió, descubrir quién manipula la crisis y evitar que los vulnerables sean valorados por la utilidad que otros les asignen. Nebula protegerá a su familia elegida sin permitir que nadie sea dueño del resultado."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('adam-warlock', 'avengers-doomsday', 'Adam Warlock', 'COMPANION_ONLY', 'MYSTIC', '/assets/heroes/adam-warlock.webp', 'avengers-content-v1', '{"stats":{"power":45,"agility":69,"resistance":73,"ability":98},"maxEnergy":194,"maxAbilityPoints":150,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Soulfire Bolt","es":"Soulfire Bolt"},"description":{"en":"Adam Warlock fires a bolt of golden soulfire.","es":"Adam Warlock dispara un rayo de fuego álmico dorado."}},"offensiveAbility":{"id":"adam-warlock-offensive","name":"Soul Gem Barrage","localizedName":{"en":"Soul Gem Barrage","es":"Soul Gem Barrage"},"description":{"en":"Adam Warlock channels cosmic soul energy across the opposing formation.","es":"Adam Warlock canaliza energía cósmica del alma sobre la formación rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"adam-warlock-support","name":"Soul Mend","localizedName":{"en":"Soul Mend","es":"Soul Mend"},"description":{"en":"Adam Warlock channels restorative soul energy through the team.","es":"Adam Warlock canaliza energía restauradora del alma por todo el equipo."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["beta-ray-bill","nebula","nova"],"rivals":[],"biography":{"en":"Adam Warlock is a cosmic being created to become an ideal protector, still learning how wisdom, power and free will fit together. He channels immense energy and approaches ordinary emotions with curiosity, often discovering that compassion cannot be engineered into existence. His immense power is still searching for a moral language of its own.","es":"Adam Warlock es un ser cósmico creado para ser un protector ideal y que aún aprende cómo encajan sabiduría, poder y libre albedrío. Canaliza una energía inmensa y observa las emociones con curiosidad, descubriendo que la compasión no puede fabricarse. Su poder inmenso todavía busca un lenguaje moral propio."},"tournamentMotivation":{"en":"Adam enters to understand the danger and the people living inside it, not merely to display his power. He wants to protect developing civilizations, learn from the other teams and choose a response guided by judgment rather than by the purpose he was originally designed to serve. He will choose the response that preserves freedom to learn rather than one that ends every question.","es":"Adam entra para comprender el peligro y a las personas que viven dentro de él, no solo para mostrar su poder. Quiere proteger civilizaciones en desarrollo, aprender de los equipos y elegir una respuesta guiada por criterio, no por el propósito para el que fue creado. Elegirá la respuesta que preserve la libertad de aprender, no la que cierre toda pregunta."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('nova', 'avengers-doomsday', 'Nova', 'COMPANION_ONLY', 'BLASTER', '/assets/heroes/nova.webp', 'avengers-content-v1', '{"stats":{"power":80,"agility":75,"resistance":73,"ability":87},"maxEnergy":266,"maxAbilityPoints":122,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Nova Punch","es":"Nova Punch"},"description":{"en":"Nova drives Nova Force through a focused punch.","es":"Nova descarga la Fuerza Nova en un puñetazo concentrado."}},"offensiveAbility":{"id":"nova-offensive","name":"Nova Force Burst","localizedName":{"en":"Nova Force Burst","es":"Nova Force Burst"},"description":{"en":"Nova releases a blazing Nova Force assault.","es":"Nova libera una ofensiva ardiente de la Fuerza Nova."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"nova-support","name":"Nova Guard","localizedName":{"en":"Nova Guard","es":"Nova Guard"},"description":{"en":"Nova channels Nova Force to strengthen the team''s attacks.","es":"Nova canaliza la Fuerza Nova para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["adam-warlock","monica-rambeau","yondu"],"rivals":[],"biography":{"en":"Richard Rider is Nova, a human champion empowered by the Nova Force and connected to the legacy of the intergalactic Nova Corps. He brings flight, energy projection and the weight of a cosmic police force to every mission, while remembering the lives behind its reports. The Nova Force gives him reach, but reports from ruined worlds give that reach meaning.","es":"Richard Rider es Nova, un campeón humano fortalecido por la Fuerza Nova y ligado al legado del Cuerpo Nova intergaláctico. Aporta vuelo, proyección de energía y el peso de una fuerza policial cósmica, sin olvidar las vidas detrás de cada informe. La Fuerza Nova le da alcance, pero los informes de mundos arruinados le dan sentido."},"tournamentMotivation":{"en":"Richard joins because he has seen how quickly a cosmic emergency becomes a mass evacuation. He wants the teams to coordinate before worlds lose their protectors, and he will treat the tournament as a chance to defend civilians rather than as a contest for prestige. Richard will prioritize evacuation and communication before any display of force.","es":"Richard se une porque ha visto lo rápido que una emergencia cósmica se convierte en una evacuación masiva. Quiere coordinar a los equipos antes de que los mundos pierdan a sus protectores y tratará el torneo como defensa civil, no como una competencia de prestigio. Richard priorizará la evacuación y la comunicación antes de mostrar fuerza."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('yondu', 'avengers-doomsday', 'Yondu', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/yondu.webp', 'avengers-content-v1', '{"stats":{"power":67,"agility":89,"resistance":60,"ability":73},"maxEnergy":243,"maxAbilityPoints":79,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Yaka Arrow","es":"Yaka Arrow"},"description":{"en":"Yondu guides a whistling arrow through the opening.","es":"Yondu guía una flecha silbante por la abertura."}},"offensiveAbility":{"id":"yondu-offensive","name":"Arrow Storm","localizedName":{"en":"Arrow Storm","es":"Arrow Storm"},"description":{"en":"Yondu sends the Yaka arrow weaving through the opposing formation.","es":"Yondu hace que la flecha Yaka se abra paso por la formación rival."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"yondu-support","name":"Whistling Cover","localizedName":{"en":"Whistling Cover","es":"Whistling Cover"},"description":{"en":"Yondu uses the Yaka arrow to give the team room to move.","es":"Yondu usa la flecha Yaka para abrirle espacio al equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["nova","star-lord"],"rivals":[],"biography":{"en":"Yondu Udonta is a veteran spacefarer whose whistle guides a devastating arrow through impossible paths. A former Ravager leader, he carries a rough exterior and a protective instinct that eventually made him a father figure to the misfits who became his crew. His arrow is precise because he learned to trust instinct without abandoning responsibility.","es":"Yondu Udonta es un veterano del espacio cuyo silbido guía una flecha por trayectorias imposibles. Antiguo líder de los Ravagers, lleva una apariencia áspera y un instinto protector que lo convirtió en figura paterna para los inadaptados de su tripulación. Su flecha es precisa porque aprendió a confiar en el instinto sin abandonar la responsabilidad."},"tournamentMotivation":{"en":"Yondu joins because he knows crews and colonies are often left to fend for themselves when the powerful look toward the next prize. He will protect the people he calls his own, read the room before trusting anyone and keep a path open for escape. He will keep a route open for the people who never get invited to grand plans.","es":"Yondu se une porque sabe que tripulaciones y colonias suelen quedar abandonadas cuando los poderosos miran hacia el próximo premio. Protegerá a quienes considera suyos, observará antes de confiar y mantendrá abierta una ruta de escape. Mantendrá una salida para quienes nunca son invitados a los grandes planes."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('mbaku', 'avengers-doomsday', 'M’Baku', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/mbaku.webp', 'avengers-content-v1', '{"stats":{"power":90,"agility":47,"resistance":83,"ability":59},"maxEnergy":314,"maxAbilityPoints":62,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Jabari Fist","es":"Jabari Fist"},"description":{"en":"M’Baku drives a Jabari fist into the opening.","es":"M’Baku descarga un puño Jabari sobre la abertura."}},"offensiveAbility":{"id":"mbaku-offensive","name":"Gorilla Charge","localizedName":{"en":"Gorilla Charge","es":"Gorilla Charge"},"description":{"en":"M’Baku crashes forward with the strength of the Jabari tribe.","es":"M’Baku irrumpe con la fuerza de la tribu Jabari."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"mbaku-support","name":"Tribal Rally","localizedName":{"en":"Tribal Rally","es":"Tribal Rally"},"description":{"en":"M’Baku turns fierce loyalty into momentum for the team''s attacks.","es":"M’Baku convierte la lealtad feroz en impulso para los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["okoye"],"rivals":["black-panther"],"biography":{"en":"M''Baku is the proud leader of the Jabari, a powerful Wakandan warrior who values tradition, courage and the obligations of community. His strength is matched by a blunt intelligence that can challenge royalty while remaining loyal to Wakanda''s survival. His pride is tied to the Jabari, not to winning approval from the outside world.","es":"M''Baku es el orgulloso líder de los Jabari, un poderoso guerrero wakandiano que valora la tradición, el coraje y las obligaciones comunitarias. Su fuerza se acompaña de una inteligencia directa capaz de cuestionar a la realeza sin dejar de ser leal a la supervivencia de Wakanda. Su orgullo está ligado a los Jabari y no a obtener aprobación del mundo exterior."},"tournamentMotivation":{"en":"M''Baku enters because no ruler can ignore a danger that may reach his people from beyond their world. He will defend Wakanda''s dignity, test the courage of the assembled champions and ensure that aid does not become another form of domination. He will accept cooperation only when it protects Wakanda without erasing its voice.","es":"M''Baku entra porque ningún gobernante puede ignorar un peligro capaz de alcanzar a su pueblo desde más allá de su mundo. Defenderá la dignidad de Wakanda, pondrá a prueba a los campeones y evitará que la ayuda se convierta en dominación. Aceptará cooperar solo cuando proteja a Wakanda sin borrar su voz."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('okoye', 'avengers-doomsday', 'Okoye', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/okoye.webp', 'avengers-content-v1', '{"stats":{"power":79,"agility":94,"resistance":72,"ability":86},"maxEnergy":267,"maxAbilityPoints":81,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Dora Spear","es":"Dora Spear"},"description":{"en":"Okoye drives a vibranium spear through the opening.","es":"Okoye clava una lanza de vibranio en la abertura."}},"offensiveAbility":{"id":"okoye-offensive","name":"Dora Spearstorm","localizedName":{"en":"Dora Spearstorm","es":"Dora Spearstorm"},"description":{"en":"Okoye leads a precise spear assault across the enemy line.","es":"Okoye desata una ofensiva precisa de lanzas sobre la línea enemiga."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"okoye-support","name":"Formation Drill","localizedName":{"en":"Formation Drill","es":"Formation Drill"},"description":{"en":"Okoye uses Dora Milaje discipline to sharpen team movement.","es":"Okoye usa la disciplina de Dora Milaje para agudizar el movimiento del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["mbaku","shuri"],"rivals":[],"biography":{"en":"Okoye is a general of the Dora Milaje, Wakanda''s elite royal guard, known for discipline, spear mastery and unwavering service. She is practical, observant and fiercely loyal, able to speak hard truths while placing the safety of her people above personal comfort. She notices the small breach in a formation before it becomes a threat to the people behind it.","es":"Okoye es general de las Dora Milaje, la guardia real de élite de Wakanda, reconocida por su disciplina y dominio de la lanza. Es práctica, observadora y ferozmente leal, capaz de decir verdades incómodas mientras prioriza la seguridad de su pueblo. Percibe la pequeña falla de una formación antes de que amenace a quienes están detrás."},"tournamentMotivation":{"en":"Okoye joins as a protector first, not as a contestant seeking fame. She will gather intelligence, guard Wakandan interests and keep the teams disciplined enough to respond when the crisis reaches people who cannot defend themselves. Her duty is to keep the response disciplined when fear invites reckless action.","es":"Okoye se une como protectora, no como competidora en busca de fama. Reunirá información, defenderá los intereses de Wakanda y mantendrá a los equipos preparados para responder cuando la crisis alcance a quienes no pueden defenderse. Su deber es mantener disciplinada la respuesta cuando el miedo invita a actuar sin cuidado."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('shuri', 'avengers-doomsday', 'Shuri', 'COMPANION_ONLY', 'TACTICIAN', '/assets/heroes/shuri.webp', 'avengers-content-v1', '{"stats":{"power":77,"agility":60,"resistance":76,"ability":96},"maxEnergy":269,"maxAbilityPoints":99,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Panther Gauntlet","es":"Panther Gauntlet"},"description":{"en":"Shuri fires a kinetic pulse from her panther gauntlets.","es":"Shuri dispara un pulso cinético de sus guanteletes de pantera."}},"offensiveAbility":{"id":"shuri-offensive","name":"Kimoyo Pulse","localizedName":{"en":"Kimoyo Pulse","es":"Kimoyo Pulse"},"description":{"en":"Shuri unleashes a barrage of Wakandan sonic pulses.","es":"Shuri desata una ráfaga de pulsos sónicos wakandianos."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"shuri-support","name":"Kimoyo Purge","localizedName":{"en":"Kimoyo Purge","es":"Kimoyo Purge"},"description":{"en":"Shuri uses Kimoyo technology to clear harmful effects from the team.","es":"Shuri usa tecnología Kimoyo para limpiar efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["black-panther","okoye"],"rivals":["namor"],"biography":{"en":"Shuri is Wakanda''s brilliant inventor and princess, a scientist whose designs blend vibranium tradition with daring experimentation. She can fight when necessary, but her greatest contribution is turning knowledge into tools that let her people face threats without surrendering their identity. Her inventions are strongest when they expand what her people can choose for themselves.","es":"Shuri es la brillante inventora y princesa de Wakanda, una científica cuyos diseños combinan la tradición del vibranium con la experimentación audaz. Puede luchar cuando hace falta, pero su mayor aporte es convertir el conocimiento en herramientas para proteger la identidad de su pueblo. Sus inventos son más fuertes cuando amplían lo que su pueblo puede elegir por sí mismo."},"tournamentMotivation":{"en":"Shuri enters to understand a crisis that may affect every scientific system and every community. She wants to exchange ideas with other innovators, protect Wakanda''s future and make sure technology serves rescue and cooperation instead of becoming another reason for nations to fear one another. She will share what helps others survive while protecting knowledge that could endanger Wakanda.","es":"Shuri entra para comprender una crisis que puede afectar a cada sistema científico y comunidad. Quiere intercambiar ideas con otros innovadores, proteger el futuro de Wakanda y lograr que la tecnología sirva al rescate y la cooperación. Compartirá lo que ayude a sobrevivir y protegerá el conocimiento que ponga en riesgo a Wakanda."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('valkyrie', 'avengers-doomsday', 'Valkyrie', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/valkyrie.webp', 'avengers-content-v1', '{"stats":{"power":98,"agility":42,"resistance":94,"ability":56},"maxEnergy":319,"maxAbilityPoints":57,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Dragonfang Slash","es":"Dragonfang Slash"},"description":{"en":"Valkyrie cuts through the opening with Dragonfang.","es":"Valkyrie corta la abertura con Dragonfang."}},"offensiveAbility":{"id":"valkyrie-offensive","name":"Winged Charge","localizedName":{"en":"Winged Charge","es":"Winged Charge"},"description":{"en":"Valkyrie rides into the opposing formation with Asgardian fury.","es":"Valkyrie cabalga contra la formación rival con furia asgardiana."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"valkyrie-support","name":"Valkyrie Rally","localizedName":{"en":"Valkyrie Rally","es":"Valkyrie Rally"},"description":{"en":"Valkyrie turns warrior courage into momentum for the team.","es":"Valkyrie convierte el valor guerrero en impulso para el equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["sif","thor"],"rivals":[],"biography":{"en":"Valkyrie is an Asgardian warrior and ruler who carries the memory of fallen comrades into every battle. Her skill with the sword, experience guiding refugees and fierce independence make her a protector who understands that leadership begins with staying when others would flee. She leads survivors because she remembers every name that was not carried to safety.","es":"Valkyrie es una guerrera y gobernante asgardiana que lleva la memoria de sus camaradas caídos a cada batalla. Su habilidad con la espada, experiencia guiando refugiados e independencia feroz la convierten en una protectora que sabe que liderar comienza por quedarse. Guía a los supervivientes porque recuerda cada nombre que no llegó a salvo."},"tournamentMotivation":{"en":"Valkyrie joins because she has already watched a realm lose its home. She will stand with worlds facing that same fear, judge the courage of the teams beside her and protect refugees and survivors before anyone worries about honor or victory. She will judge the teams by who they carry when victory is no longer certain.","es":"Valkyrie se une porque ya vio a un reino perder su hogar. Estará junto a los mundos que enfrenten ese miedo, evaluará el coraje de los equipos y protegerá a refugiados y supervivientes antes de pensar en honor o victoria. Juzgará a los equipos por a quiénes cargan cuando la victoria deja de ser segura."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('sif', 'avengers-doomsday', 'Sif', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/sif.webp', 'avengers-content-v1', '{"stats":{"power":95,"agility":47,"resistance":98,"ability":55},"maxEnergy":322,"maxAbilityPoints":56,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Asgardian Blade","es":"Asgardian Blade"},"description":{"en":"Sif answers with a clean Asgardian sword strike.","es":"Sif responde con un golpe limpio de espada asgardiana."}},"offensiveAbility":{"id":"sif-offensive","name":"Swordstorm","localizedName":{"en":"Swordstorm","es":"Swordstorm"},"description":{"en":"Sif unleashes a disciplined storm of sword strikes.","es":"Sif desata una tormenta disciplinada de golpes de espada."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"sif-support","name":"Shieldmaid''s Footwork","localizedName":{"en":"Shieldmaid''s Footwork","es":"Shieldmaid''s Footwork"},"description":{"en":"Sif uses shieldmaiden discipline to strengthen the team''s attacks.","es":"Sif usa disciplina de escudera para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["korg","valkyrie"],"rivals":[],"biography":{"en":"Sif is an Asgardian champion, a master swordswoman and a steadfast friend of Thor. Her courage is not theatrical; it is the disciplined loyalty of a warrior who keeps her word, protects her allies and meets impossible odds without waiting for permission. Her loyalty is active: it means standing in the right place when the shield line breaks.","es":"Sif es una campeona asgardiana, maestra de la espada y amiga inquebrantable de Thor. Su coraje no es teatral: es la lealtad disciplinada de una guerrera que cumple su palabra, protege a sus aliados y enfrenta lo imposible sin pedir permiso. Su lealtad es activa: significa estar en el lugar correcto cuando la línea se rompe."},"tournamentMotivation":{"en":"Sif enters because Asgard''s duty extends to realms beyond its own borders. She wants to stand beside the threatened, keep Thor and the other teams grounded in honor and make certain that people who cannot wield a sword are not forgotten. She will protect allies without mistaking obedience for honor.","es":"Sif entra porque el deber de Asgard se extiende más allá de sus fronteras. Quiere acompañar a los amenazados, mantener a Thor y a los equipos fieles al honor y evitar que quienes no empuñan una espada sean olvidados. Protegerá a sus aliados sin confundir obediencia con honor."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('korg', 'avengers-doomsday', 'Korg', 'COMPANION_ONLY', 'GUARDIAN', '/assets/heroes/korg.webp', 'avengers-content-v1', '{"stats":{"power":68,"agility":68,"resistance":86,"ability":74},"maxEnergy":277,"maxAbilityPoints":99,"primaryRole":"SUPPORT","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Stone Fist","es":"Stone Fist"},"description":{"en":"Korg drives a stone fist through the opening.","es":"Korg descarga un puño de piedra sobre la abertura."}},"offensiveAbility":{"id":"korg-offensive","name":"Kronan Crush","localizedName":{"en":"Kronan Crush","es":"Kronan Crush"},"description":{"en":"Korg turns his rocky frame into a crushing charge.","es":"Korg convierte su cuerpo rocoso en una embestida demoledora."},"apCost":30,"multiplier":1},"supportAbility":{"id":"korg-support","name":"Stonewall Stance","localizedName":{"en":"Stonewall Stance","es":"Stonewall Stance"},"description":{"en":"Korg plants himself between danger and the team.","es":"Korg se planta entre el peligro y el equipo."},"apCost":25,"effect":"RESISTANCE","potency":0.15},"allies":["heimdall","sif"],"rivals":[],"biography":{"en":"Korg is a rock-skinned warrior from Kronan culture whose immense resilience is balanced by gentle humor and a talent for making companions feel welcome. He has survived conquest and displacement, yet chooses friendship and solidarity over bitterness. His humor gives frightened companions a moment to breathe before the next hard decision.","es":"Korg es un guerrero de piel rocosa de la cultura kronana cuya enorme resistencia se equilibra con humor amable y una habilidad especial para hacer sentir bienvenidos a sus compañeros. Sobrevivió a la conquista y el desplazamiento, pero elige amistad y solidaridad. Su humor da a los compañeros asustados un instante para respirar antes de decidir."},"tournamentMotivation":{"en":"Korg joins because he knows worlds can be broken by people who think survivors are too small to matter. He will help the teams stay together, protect those looking for a home and bring a little courage to a situation that could otherwise crush it. He will help build a safe place wherever the teams have to make a stand.","es":"Korg se une porque sabe que los mundos pueden ser destruidos por quienes creen que los supervivientes son demasiado pequeños para importar. Ayudará a mantener unidos a los equipos, protegerá a quienes buscan un hogar y aportará coraje. Ayudará a construir un lugar seguro donde los equipos deban resistir."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('heimdall', 'avengers-doomsday', 'Heimdall', 'COMPANION_ONLY', 'GUARDIAN', '/assets/heroes/heimdall.webp', 'avengers-content-v1', '{"stats":{"power":78,"agility":65,"resistance":96,"ability":80},"maxEnergy":290,"maxAbilityPoints":81,"primaryRole":"SUPPORT","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Hofund Cut","es":"Hofund Cut"},"description":{"en":"Heimdall draws Hofund through the opening with Asgardian precision.","es":"Heimdall traza Hofund por la abertura con precisión asgardiana."}},"offensiveAbility":{"id":"heimdall-offensive","name":"Bifrost Sever","localizedName":{"en":"Bifrost Sever","es":"Bifrost Sever"},"description":{"en":"Heimdall calls the Bifrost through a sweeping strike.","es":"Heimdall invoca el Bifrost en un golpe amplio."},"apCost":30,"multiplier":1},"supportAbility":{"id":"heimdall-support","name":"All-Seeing Guard","localizedName":{"en":"All-Seeing Guard","es":"All-Seeing Guard"},"description":{"en":"Heimdall uses his all-seeing awareness to protect the team.","es":"Heimdall usa su visión omnisciente para proteger al equipo."},"apCost":25,"effect":"RESISTANCE","potency":0.15},"allies":["beta-ray-bill","korg"],"rivals":[],"biography":{"en":"Heimdall is the far-seeing guardian of Asgard, able to perceive distant worlds and movements through the Bifrost. His vigilance is paired with quiet judgment and absolute loyalty, making him the watchman who notices danger before it reaches the gates. His sight is a duty, not a spectacle; he watches so others can sleep.","es":"Heimdall es el guardián clarividente de Asgard, capaz de percibir mundos y movimientos lejanos a través del Bifrost. Su vigilancia se une a un juicio sereno y una lealtad absoluta: es quien advierte el peligro antes de que llegue a las puertas. Su visión es un deber, no un espectáculo: vigila para que otros puedan dormir."},"tournamentMotivation":{"en":"Heimdall joins because the warning concerns paths between worlds, the very crossings he has guarded for ages. He will watch for those in danger, guide allies through uncertainty and ensure that distant peoples are not lost simply because no one saw them in time. He will warn the teams early enough for courage to be a choice rather than a surprise.","es":"Heimdall se une porque la advertencia afecta los caminos entre mundos, los mismos cruces que protegió durante siglos. Vigilará a quienes estén en peligro, guiará a sus aliados y evitará que pueblos lejanos se pierdan por no haber sido vistos a tiempo. Advertirá a los equipos a tiempo para que el valor sea una elección y no una sorpresa."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('hercules', 'avengers-doomsday', 'Hercules', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/hercules.webp', 'avengers-content-v1', '{"stats":{"power":95,"agility":66,"resistance":98,"ability":52},"maxEnergy":315,"maxAbilityPoints":51,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Olympian Punch","es":"Olympian Punch"},"description":{"en":"Hercules answers with the strength of an Olympian champion.","es":"Hercules responde con la fuerza de un campeón olímpico."}},"offensiveAbility":{"id":"hercules-offensive","name":"Twelve Labors Charge","localizedName":{"en":"Twelve Labors Charge","es":"Twelve Labors Charge"},"description":{"en":"Hercules charges through the opposing formation like a legendary labor.","es":"Hercules arremete contra la formación rival como en una gesta legendaria."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"hercules-support","name":"Heroic Roar","localizedName":{"en":"Heroic Roar","es":"Heroic Roar"},"description":{"en":"Hercules turns heroic pride into momentum for the team''s attacks.","es":"Hercules convierte el orgullo heroico en impulso para los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":[],"rivals":["thor"],"biography":{"en":"Hercules is the Olympian champion, a son of Zeus whose legendary strength is matched by a love of adventure, feasting and honest friendship. Beneath the boastful confidence is a hero who understands that courage means returning to the fight when pride has failed. His legends are loud, but his oldest lesson is that a champion serves the people who cheer.","es":"Hercules es el campeón olímpico, hijo de Zeus, cuya fuerza legendaria se acompaña de amor por la aventura, los banquetes y la amistad sincera. Bajo la confianza fanfarrona hay un héroe que sabe que el coraje es volver a luchar cuando el orgullo falla. Sus leyendas son ruidosas, pero su lección más antigua es servir a quienes lo aclaman."},"tournamentMotivation":{"en":"Hercules enters because a contest that gathers champions across worlds is impossible to ignore, but he stays for more than glory. He wants to defend mortals threatened by forces above them and prove that a heroic challenge can serve a purpose larger than pride. He will turn the contest into a defense of mortals, not a monument to himself.","es":"Hercules entra porque un desafío que reúne campeones de distintos mundos es imposible de ignorar, pero se queda por algo más que gloria. Quiere defender a los mortales frente a fuerzas superiores y demostrar que una gesta puede servir a un propósito mayor que el orgullo. Convertirá el desafío en defensa de los mortales, no en un monumento a sí mismo."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('echo', 'avengers-doomsday', 'Echo', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/echo.webp', 'avengers-content-v1', '{"stats":{"power":78,"agility":84,"resistance":64,"ability":67},"maxEnergy":233,"maxAbilityPoints":81,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Mimic Strike","es":"Mimic Strike"},"description":{"en":"Echo mirrors the opening and answers with perfect timing.","es":"Echo imita la abertura y responde con ritmo perfecto."}},"offensiveAbility":{"id":"echo-offensive","name":"Echoed Flurry","localizedName":{"en":"Echoed Flurry","es":"Echoed Flurry"},"description":{"en":"Echo reproduces the opponent''s rhythm in a rapid counter-assault.","es":"Echo reproduce el ritmo rival en un contraataque veloz."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"echo-support","name":"Adaptive Footwork","localizedName":{"en":"Adaptive Footwork","es":"Adaptive Footwork"},"description":{"en":"Echo uses mirrored movement to sharpen the team''s mobility.","es":"Echo usa movimientos reflejados para agudizar la movilidad del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["kate-bishop","shang-chi"],"rivals":[],"biography":{"en":"Maya Lopez is Echo, a gifted fighter who can reproduce movements after seeing them and who built her own identity after a childhood shaped by loss. Her combat skill is precise and adaptive, while her determination comes from refusing to let anyone else decide who she must become. She learns from movement without surrendering her own rhythm or voice.","es":"Maya Lopez es Echo, una luchadora talentosa que reproduce movimientos después de observarlos y construyó su identidad tras una infancia marcada por la pérdida. Su combate es preciso y adaptable, y su determinación nace de no dejar que otros decidan quién debe ser. Aprende de los movimientos sin renunciar a su propio ritmo ni a su voz."},"tournamentMotivation":{"en":"Maya joins because people caught in a crisis deserve a defender who understands what it means to be underestimated. She will protect communities without waiting for permission, learn from every opponent and choose her own path through a conflict that reaches far beyond one city. Maya will trust her reading of people more than the titles attached to them.","es":"Maya se une porque quienes quedan atrapados en una crisis merecen una defensora que sepa lo que significa ser subestimada. Protegerá comunidades sin esperar permiso, aprenderá de cada rival y elegirá su propio camino en un conflicto mayor que cualquier ciudad. Maya confiará en su lectura de las personas más que en sus títulos."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('kate-bishop', 'avengers-doomsday', 'Kate Bishop', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/kate-bishop.webp', 'avengers-content-v1', '{"stats":{"power":86,"agility":93,"resistance":64,"ability":74},"maxEnergy":265,"maxAbilityPoints":87,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Trick Arrow","es":"Trick Arrow"},"description":{"en":"Kate Bishop puts a trick arrow through the opening.","es":"Kate Bishop clava una flecha especial en la abertura."}},"offensiveAbility":{"id":"kate-bishop-offensive","name":"Trick Arrow Volley","localizedName":{"en":"Trick Arrow Volley","es":"Trick Arrow Volley"},"description":{"en":"Kate Bishop fills the opposing line with a volley of trick arrows.","es":"Kate Bishop llena la línea rival con una lluvia de flechas especiales."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"kate-bishop-support","name":"Covering Arrow","localizedName":{"en":"Covering Arrow","es":"Covering Arrow"},"description":{"en":"Kate Bishop uses precise arrows to give the team room to reposition.","es":"Kate Bishop usa flechas precisas para que el equipo se reposicione."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["america-chavez","echo","iron-fist","speed"],"rivals":[],"biography":{"en":"Kate Bishop is a determined archer who earned the Hawkeye name through training, nerve and a refusal to stand aside. She has no superpowers, but compensates with observation, athletic skill and the confidence to challenge experienced heroes when their plan needs another angle. Her confidence is earned shot by shot, not borrowed from the name she carries.","es":"Kate Bishop es una arquera decidida que ganó el nombre Hawkeye mediante entrenamiento, coraje y la negativa a quedarse al margen. No tiene superpoderes, pero los compensa con observación, habilidad atlética y confianza para cuestionar a héroes expertos. Su confianza se gana disparo a disparo, no se toma prestada del nombre que lleva."},"tournamentMotivation":{"en":"Kate enters because the people threatened by a multiversal crisis will need brave specialists as well as cosmic champions. She wants to learn, contribute and prove that a clear shot and a fast decision can matter even when the battlefield is larger than Earth. She will make herself useful wherever a team needs an angle nobody else can cover.","es":"Kate entra porque las personas amenazadas por una crisis multiversal necesitarán especialistas valientes además de campeones cósmicos. Quiere aprender, aportar y demostrar que un disparo certero y una decisión rápida importan aunque el campo de batalla sea mayor que la Tierra. Será útil donde un equipo necesite un ángulo que nadie más pueda cubrir."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('iron-fist', 'avengers-doomsday', 'Iron Fist', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/iron-fist.webp', 'avengers-content-v1', '{"stats":{"power":82,"agility":98,"resistance":58,"ability":74},"maxEnergy":237,"maxAbilityPoints":71,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Iron Fist","es":"Iron Fist"},"description":{"en":"Iron Fist drives chi through a focused fist.","es":"Iron Fist descarga chi en un puño concentrado."}},"offensiveAbility":{"id":"iron-fist-offensive","name":"Chi Dragon","localizedName":{"en":"Chi Dragon","es":"Chi Dragon"},"description":{"en":"Iron Fist unleashes a dragon-shaped wave of chi across the enemy line.","es":"Iron Fist desata una oleada de chi con forma de dragón sobre la línea enemiga."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"iron-fist-support","name":"Chi Meditation","localizedName":{"en":"Chi Meditation","es":"Chi Meditation"},"description":{"en":"Iron Fist uses disciplined chi control to sharpen the team''s movement.","es":"Iron Fist usa control disciplinado del chi para agudizar el movimiento del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["kate-bishop","luke-cage"],"rivals":[],"biography":{"en":"Danny Rand is Iron Fist, a martial artist who earned the right to channel the chi of Shou-Lao through his legendary fist. His training taught him patience, discipline and responsibility, while his wealth and past continually challenge him to serve rather than possess. His chi is a practice of balance, not simply a stronger way to hit.","es":"Danny Rand es Iron Fist, un artista marcial que ganó el derecho de canalizar el chi de Shou-Lao mediante su legendario puño. Su entrenamiento le enseñó paciencia, disciplina y responsabilidad, mientras su riqueza y pasado lo desafían a servir en lugar de poseer. Su chi es una práctica de equilibrio, no solo una forma más fuerte de golpear."},"tournamentMotivation":{"en":"Danny joins because a threat crossing realities can reach the communities he has sworn to protect. He will bring the discipline of K''un-Lun, listen before striking and help the teams resist fear, coercion and the temptation to solve every problem through force. He will teach patience to teams tempted to answer uncertainty with violence.","es":"Danny se une porque una amenaza que cruza realidades puede alcanzar a las comunidades que juró proteger. Llevará la disciplina de K''un-Lun, escuchará antes de atacar y ayudará a resistir el miedo, la coerción y la tentación de resolver todo por la fuerza. Enseñará paciencia a los equipos tentados de responder a la incertidumbre con violencia."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('luke-cage', 'avengers-doomsday', 'Luke Cage', 'COMPANION_ONLY', 'GUARDIAN', '/assets/heroes/luke-cage.webp', 'avengers-content-v1', '{"stats":{"power":72,"agility":71,"resistance":82,"ability":79},"maxEnergy":268,"maxAbilityPoints":95,"primaryRole":"SUPPORT","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Power Man Punch","es":"Power Man Punch"},"description":{"en":"Luke Cage answers with an unbreakable Power Man punch.","es":"Luke Cage responde con un puñetazo irrompible de Power Man."}},"offensiveAbility":{"id":"luke-cage-offensive","name":"Unbreakable Charge","localizedName":{"en":"Unbreakable Charge","es":"Unbreakable Charge"},"description":{"en":"Luke Cage crashes through the opposing formation with bulletproof strength.","es":"Luke Cage irrumpe contra la formación rival con fuerza a prueba de balas."},"apCost":30,"multiplier":1},"supportAbility":{"id":"luke-cage-support","name":"Bulletproof Cover","localizedName":{"en":"Bulletproof Cover","es":"Bulletproof Cover"},"description":{"en":"Luke Cage puts unbreakable skin between danger and the team.","es":"Luke Cage interpone su piel irrompible entre el peligro y el equipo."},"apCost":25,"effect":"RESISTANCE","potency":0.15},"allies":["iron-fist","jessica-jones"],"rivals":["punisher"],"biography":{"en":"Luke Cage is a Harlem hero with unbreakable skin and tremendous strength who turned painful experimentation into a commitment to his neighborhood. He protects people with a practical sense of justice, a direct voice and the belief that power should answer to the community. His strength is most meaningful when it gives someone else room to breathe and rebuild.","es":"Luke Cage es un héroe de Harlem con piel irrompible y una fuerza enorme que convirtió un experimento doloroso en compromiso con su barrio. Protege con un sentido práctico de la justicia, una voz directa y la convicción de que el poder debe responder a la comunidad. Su fuerza importa más cuando permite que otra persona respire y se reconstruya."},"tournamentMotivation":{"en":"Luke enters because multiversal danger still lands on streets, apartments and families. He wants the powerful teams to remember those places, protect people who cannot leave their homes and make sure any alliance built in the tournament serves communities rather than abstract glory. He will insist that any plan include the neighborhoods hidden behind the headlines.","es":"Luke entra porque el peligro multiversal también cae sobre calles, edificios y familias. Quiere que los equipos poderosos recuerden esos lugares, protejan a quienes no pueden huir y construyan alianzas al servicio de las comunidades, no de la gloria abstracta. Insistirá en que todo plan incluya los barrios ocultos detrás de los titulares."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('jessica-jones', 'avengers-doomsday', 'Jessica Jones', 'COMPANION_ONLY', 'GUARDIAN', '/assets/heroes/jessica-jones.webp', 'avengers-content-v1', '{"stats":{"power":80,"agility":77,"resistance":97,"ability":82},"maxEnergy":294,"maxAbilityPoints":88,"primaryRole":"SUPPORT","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Powerhouse Jab","es":"Powerhouse Jab"},"description":{"en":"Jessica Jones lands a blunt super-strength strike.","es":"Jessica Jones conecta un golpe directo de superfuerza."}},"offensiveAbility":{"id":"jessica-jones-offensive","name":"Investigator''s Takedown","localizedName":{"en":"Investigator''s Takedown","es":"Investigator''s Takedown"},"description":{"en":"Jessica Jones combines super-strength with a no-nonsense takedown.","es":"Jessica Jones combina superfuerza con un derribo directo."},"apCost":30,"multiplier":1},"supportAbility":{"id":"jessica-jones-support","name":"Hard Truth","localizedName":{"en":"Hard Truth","es":"Hard Truth"},"description":{"en":"Jessica Jones uses stubborn resolve to protect the team''s formation.","es":"Jessica Jones usa una determinación obstinada para proteger la formación del equipo."},"apCost":25,"effect":"RESISTANCE","potency":0.15},"allies":["luke-cage","white-tiger"],"rivals":[],"biography":{"en":"Jessica Jones is a super-strong private investigator who survived control and exploitation without losing her blunt honesty. She keeps people at a distance until trust is earned, then protects them with stubborn loyalty and a practical eye for the details that heroes overlook. She notices the story people tell to avoid saying what actually happened.","es":"Jessica Jones es una investigadora privada superfuerte que sobrevivió al control y la explotación sin perder su honestidad directa. Mantiene distancia hasta que la confianza se gana, pero entonces protege con lealtad obstinada y atención a los detalles que otros héroes pasan por alto. Percibe la historia que alguien cuenta para evitar decir qué ocurrió en verdad."},"tournamentMotivation":{"en":"Jessica joins because someone needs to ask who benefits when everyone is told to rush into a mystery. She will look for missing people, hidden risks and the human cost behind the official warning, protecting survivors even if they never call themselves heroes. She will follow the evidence even when the official version is easier to accept.","es":"Jessica se une porque alguien debe preguntar quién se beneficia cuando todos reciben la orden de correr hacia un misterio. Buscará desaparecidos, riesgos ocultos y el costo humano detrás de la advertencia, protegiendo supervivientes aunque nunca se llamen héroes. Seguirá las pruebas aunque la versión oficial sea más fácil de aceptar."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('war-machine', 'avengers-doomsday', 'War Machine', 'COMPANION_ONLY', 'TACTICIAN', '/assets/heroes/war-machine.webp', 'avengers-content-v1', '{"stats":{"power":82,"agility":61,"resistance":63,"ability":90},"maxEnergy":228,"maxAbilityPoints":111,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Armor Cannon","es":"Armor Cannon"},"description":{"en":"War Machine fires a controlled cannon burst from heavy armor.","es":"War Machine dispara una ráfaga controlada de su cañón acorazado."}},"offensiveAbility":{"id":"war-machine-offensive","name":"War Machine Salvo","localizedName":{"en":"War Machine Salvo","es":"War Machine Salvo"},"description":{"en":"War Machine unloads heavy armor firepower across the opposing formation.","es":"War Machine descarga la potencia de fuego de su armadura sobre la formación rival."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"war-machine-support","name":"Combat Systems Reset","localizedName":{"en":"Combat Systems Reset","es":"Combat Systems Reset"},"description":{"en":"War Machine uses armor systems to clear harmful effects from the team.","es":"War Machine usa los sistemas de la armadura para limpiar efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["ms-marvel","she-hulk"],"rivals":["punisher"],"biography":{"en":"James Rhodes is War Machine, a decorated military officer who operates a heavily armed suit built for defense and battlefield support. His friendship with Tony Stark never replaces his own judgment; Rhodey brings discipline, accountability and the experience of protecting people under fire. Rhodey''s armor is a tool for accountability as much as for firepower.","es":"James Rhodes es War Machine, un oficial militar condecorado que opera una armadura fuertemente armada para defensa y apoyo de combate. Su amistad con Tony Stark no reemplaza su criterio; Rhodey aporta disciplina, responsabilidad y experiencia protegiendo bajo fuego. La armadura de Rhodey es una herramienta de responsabilidad tanto como de potencia."},"tournamentMotivation":{"en":"Rhodey enters because the public warning calls for organized defense, not a collection of solo victories. He wants the teams to plan evacuations, coordinate power responsibly and make sure any response to the crisis protects civilians before it protects reputations. He will insist on a chain of care, not merely a chain of command.","es":"Rhodey entra porque la advertencia pública exige defensa organizada, no una colección de victorias individuales. Quiere que los equipos planifiquen evacuaciones, coordinen el poder con responsabilidad y protejan a los civiles antes que a sus reputaciones. Insistirá en una cadena de cuidado, no solo en una cadena de mando."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('ghost-rider', 'avengers-doomsday', 'Ghost Rider', 'COMPANION_ONLY', 'MYSTIC', '/assets/heroes/ghost-rider.webp', 'avengers-content-v1', '{"stats":{"power":45,"agility":66,"resistance":60,"ability":97},"maxEnergy":219,"maxAbilityPoints":125,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Hellfire Chain","es":"Hellfire Chain"},"description":{"en":"Ghost Rider lashes the opening with a chain of hellfire.","es":"Ghost Rider azota la abertura con una cadena de fuego infernal."}},"offensiveAbility":{"id":"ghost-rider-offensive","name":"Penance Stare","localizedName":{"en":"Penance Stare","es":"Penance Stare"},"description":{"en":"Ghost Rider unleashes the Penance Stare through the opposing line.","es":"Ghost Rider desata la Mirada de Penitencia sobre la línea rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"ghost-rider-support","name":"Hellfire Aegis","localizedName":{"en":"Hellfire Aegis","es":"Hellfire Aegis"},"description":{"en":"Ghost Rider channels hellfire to restore the team''s strength.","es":"Ghost Rider canaliza fuego infernal para devolver fuerzas al equipo."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["cloak","magik"],"rivals":["blade","doctor-strange"],"biography":{"en":"Johnny Blaze is Ghost Rider, a human bound to a Spirit of Vengeance whose hellfire, chain and supernatural strength punish the guilty. His rides are haunted by the cost of the pact, yet he continues to choose protection over surrender to the darkness inside him. The fire answers a spirit of vengeance, but Johnny remains responsible for where it burns.","es":"Johnny Blaze es Ghost Rider, un humano unido a un Espíritu de Venganza cuyo fuego infernal, cadena y fuerza sobrenatural castigan a los culpables. Sus viajes están marcados por el costo del pacto, pero sigue eligiendo proteger antes que rendirse a la oscuridad. El fuego responde a un espíritu de venganza, pero Johnny sigue siendo responsable de dónde arde."},"tournamentMotivation":{"en":"Johnny joins because a breach between realities could give supernatural predators a path into worlds that cannot defend themselves. He will follow the trail of those who prey on the innocent and keep the Spirit''s vengeance aimed at the guilty rather than the afraid. He will protect the innocent before judging anyone who claims to understand the darkness.","es":"Johnny se une porque una brecha entre realidades podría abrir camino a depredadores sobrenaturales hacia mundos indefensos. Seguirá el rastro de quienes cazan inocentes y mantendrá la venganza del Espíritu dirigida a los culpables, no a los asustados. Protegerá a los inocentes antes de juzgar a quien diga comprender la oscuridad."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('cloak', 'avengers-doomsday', 'Cloak', 'COMPANION_ONLY', 'MYSTIC', '/assets/heroes/cloak.webp', 'avengers-content-v1', '{"stats":{"power":69,"agility":60,"resistance":62,"ability":92},"maxEnergy":197,"maxAbilityPoints":143,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Darkforce Strike","es":"Darkforce Strike"},"description":{"en":"Cloak opens a darkforce portal through the opening.","es":"Cloak abre un portal de darkforce en la abertura."}},"offensiveAbility":{"id":"cloak-offensive","name":"Dark Dimension Crush","localizedName":{"en":"Dark Dimension Crush","es":"Dark Dimension Crush"},"description":{"en":"Cloak pulls the opposing formation toward the Dark Dimension.","es":"Cloak arrastra la formación rival hacia la Dimensión Oscura."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"cloak-support","name":"Darkforce Veil","localizedName":{"en":"Darkforce Veil","es":"Darkforce Veil"},"description":{"en":"Cloak wraps the team in darkforce and restores its strength.","es":"Cloak envuelve al equipo en darkforce y devuelve sus fuerzas."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["dagger","ghost-rider"],"rivals":[],"biography":{"en":"Tyrone Johnson is Cloak, a hero whose connection to the Darkforce lets him open portals through living darkness and shelter people inside it. His bond with Dagger gives that power purpose: together they confront exploitation, fear and the shadows surrounding vulnerable lives. His darkness can hide a person from danger, but it can also remind him of what fear feels like.","es":"Tyrone Johnson es Cloak, un héroe cuya conexión con la Darkforce le permite abrir portales en la oscuridad y refugiar personas dentro de ella. Su vínculo con Dagger da propósito a ese poder: juntos enfrentan la explotación, el miedo y las sombras sobre vidas vulnerables. Su oscuridad puede esconder a alguien del peligro, pero también le recuerda cómo se siente el miedo."},"tournamentMotivation":{"en":"Tyrone enters because people disappear first when worlds become unstable. He wants to create paths to safety, keep Dagger and other allies close and stop darkness from becoming a prison for communities that already have too few places to turn. He wants every team to have a way home before it enters a place it cannot understand.","es":"Tyrone entra porque las personas desaparecen primero cuando los mundos se vuelven inestables. Quiere abrir caminos seguros, mantener cerca a Dagger y evitar que la oscuridad se convierta en prisión para comunidades con pocas alternativas. Quiere que cada equipo tenga un camino de regreso antes de entrar en lo desconocido."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('dagger', 'avengers-doomsday', 'Dagger', 'COMPANION_ONLY', 'BLASTER', '/assets/heroes/dagger.webp', 'avengers-content-v1', '{"stats":{"power":76,"agility":76,"resistance":65,"ability":89},"maxEnergy":254,"maxAbilityPoints":114,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Lightforce Blade","es":"Lightforce Blade"},"description":{"en":"Dagger cuts through the opening with a blade of light.","es":"Dagger corta la abertura con una hoja de luz."}},"offensiveAbility":{"id":"dagger-offensive","name":"Lightforce Burst","localizedName":{"en":"Lightforce Burst","es":"Lightforce Burst"},"description":{"en":"Dagger unleashes a storm of light daggers across the enemy line.","es":"Dagger desata una tormenta de dagas de luz sobre la línea enemiga."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"dagger-support","name":"Lightforce Empowerment","localizedName":{"en":"Lightforce Empowerment","es":"Lightforce Empowerment"},"description":{"en":"Dagger channels light to strengthen the team''s attacks.","es":"Dagger canaliza luz para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["cloak","wiccan"],"rivals":[],"biography":{"en":"Tandy Bowen is Dagger, a hero who shapes radiant light into precise blades and can use that light to restore hope and strength. Her partnership with Cloak grew from shared trauma, and her compassion gives direction to the power she carries. Her light is sharp enough to fight and gentle enough to guide someone through terror.","es":"Tandy Bowen es Dagger, una heroína que moldea la luz radiante en hojas precisas y puede usarla para devolver esperanza y fuerzas. Su alianza con Cloak nació de un trauma compartido, y su compasión orienta el poder que lleva. Su luz es lo bastante afilada para luchar y lo bastante amable para guiar en el terror."},"tournamentMotivation":{"en":"Tandy joins because a crisis between realities will leave frightened people searching for a light they can trust. She wants to protect families, support Cloak and use her gift to guide survivors instead of allowing another catastrophe to turn the vulnerable into shadows. She will make protection visible to people who might otherwise believe they were forgotten.","es":"Tandy se une porque una crisis entre realidades dejará a personas asustadas buscando una luz en la que confiar. Quiere proteger familias, apoyar a Cloak y guiar a los supervivientes en lugar de permitir otra catástrofe. Hará visible la protección para quienes podrían creer que fueron olvidados."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('america-chavez', 'avengers-doomsday', 'America Chavez', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/america-chavez.webp', 'avengers-content-v1', '{"stats":{"power":96,"agility":53,"resistance":94,"ability":56},"maxEnergy":330,"maxAbilityPoints":66,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Star Punch","es":"Star Punch"},"description":{"en":"America Chavez drives a star-powered punch through the opening.","es":"America Chavez descarga un puñetazo estelar sobre la abertura."}},"offensiveAbility":{"id":"america-chavez-offensive","name":"Star Portal Crash","localizedName":{"en":"Star Portal Crash","es":"Star Portal Crash"},"description":{"en":"America Chavez smashes through a star portal into the opposing formation.","es":"America Chavez atraviesa un portal estelar y arremete contra la formación rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"america-chavez-support","name":"Portal Guard","localizedName":{"en":"Portal Guard","es":"Portal Guard"},"description":{"en":"America Chavez uses star portals to strengthen the team''s attacks.","es":"America Chavez usa portales estelares para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["kate-bishop","squirrel-girl"],"rivals":[],"biography":{"en":"America Chavez is a young hero from the Utopian Parallel who can punch star-shaped portals through the multiverse. Her strength, speed and confidence come with a personal understanding that realities are connected, while her loyalty is grounded in protecting the people she calls family. Every portal reminds her that home is a choice shared with people, not merely a place.","es":"America Chavez es una joven heroína del Paralelo Utópico que abre portales estelares a través del multiverso con sus puños. Su fuerza, velocidad y confianza nacen de comprender que las realidades están conectadas, y su lealtad protege a quienes llama familia. Cada portal le recuerda que el hogar es una elección compartida con personas, no solo un lugar."},"tournamentMotivation":{"en":"America enters because crossing realities is not a theory to her; it is part of her life and the reason she knows how many homes could be lost. She wants to protect younger worlds, connect the teams and make sure no one is trapped on the wrong side of a closing portal. She will keep the routes between teams open when fear makes everyone want to close them.","es":"America entra porque cruzar realidades no es una teoría para ella: forma parte de su vida y le muestra cuántos hogares podrían perderse. Quiere proteger mundos jóvenes, conectar a los equipos y evitar que alguien quede atrapado al cerrarse un portal. Mantendrá abiertos los caminos entre equipos cuando el miedo invite a cerrarlos."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('monica-rambeau', 'avengers-doomsday', 'Monica Rambeau / Photon', 'COMPANION_ONLY', 'BLASTER', '/assets/heroes/monica-rambeau.webp', 'avengers-content-v1', '{"stats":{"power":85,"agility":76,"resistance":77,"ability":93},"maxEnergy":227,"maxAbilityPoints":105,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Photon Jab","es":"Photon Jab"},"description":{"en":"Monica Rambeau / Photon strikes in a flash of photon energy.","es":"Monica Rambeau / Photon ataca en un destello de energía fotónica."}},"offensiveAbility":{"id":"monica-rambeau-offensive","name":"Spectrum Surge","localizedName":{"en":"Spectrum Surge","es":"Spectrum Surge"},"description":{"en":"Monica Rambeau / Photon cycles through energy forms in a sweeping assault.","es":"Monica Rambeau / Photon alterna formas de energía en una ofensiva amplia."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"monica-rambeau-support","name":"Energy Refraction","localizedName":{"en":"Energy Refraction","es":"Energy Refraction"},"description":{"en":"Monica Rambeau / Photon bends incoming energy to strengthen the team''s attacks.","es":"Monica Rambeau / Photon desvía la energía entrante para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["captain-marvel","nova"],"rivals":[],"biography":{"en":"Monica Rambeau, Photon, can transform into forms of electromagnetic energy and move through the spectrum at extraordinary speed. Her experience as an officer, leader and scientist gives her a practical understanding of how power becomes useful when it is guided by service. She can see the crisis as signals, energy and human lives at the same time.","es":"Monica Rambeau, Photon, puede transformarse en distintas formas de energía electromagnética y recorrer el espectro a velocidades extraordinarias. Su experiencia como oficial, líder y científica le da una comprensión práctica de cómo el poder se vuelve útil cuando sirve a otros. Puede ver la crisis como señales, energía y vidas humanas al mismo tiempo."},"tournamentMotivation":{"en":"Monica joins because a threat crossing realities requires someone who can move between scales, from a single rescue to a planetary emergency. She wants to coordinate the teams, protect communities during transitions and keep scientific curiosity tied to human responsibility. She will connect scientific understanding to the immediate work of getting people safe.","es":"Monica se une porque una amenaza que cruza realidades necesita a alguien capaz de pasar de un rescate a una emergencia planetaria. Quiere coordinar equipos, proteger comunidades durante las transiciones y mantener la curiosidad científica ligada a la responsabilidad humana. Conectará la comprensión científica con la tarea inmediata de poner a salvo a la gente."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('squirrel-girl', 'avengers-doomsday', 'Squirrel Girl', 'COMPANION_ONLY', 'GUARDIAN', '/assets/heroes/squirrel-girl.webp', 'avengers-content-v1', '{"stats":{"power":81,"agility":65,"resistance":92,"ability":71},"maxEnergy":258,"maxAbilityPoints":90,"primaryRole":"SUPPORT","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Acorn Strike","es":"Acorn Strike"},"description":{"en":"Squirrel Girl answers with a surprisingly fierce acorn-powered strike.","es":"Squirrel Girl responde con un golpe de bellota sorprendentemente feroz."}},"offensiveAbility":{"id":"squirrel-girl-offensive","name":"Squirrel Swarm","localizedName":{"en":"Squirrel Swarm","es":"Squirrel Swarm"},"description":{"en":"Squirrel Girl calls a squirrel swarm across the opposing formation.","es":"Squirrel Girl convoca una oleada de ardillas sobre la formación rival."},"apCost":30,"multiplier":1},"supportAbility":{"id":"squirrel-girl-support","name":"Squirrel Scouts","localizedName":{"en":"Squirrel Scouts","es":"Squirrel Scouts"},"description":{"en":"Squirrel Girl uses squirrel scouts to strengthen the team''s defense.","es":"Squirrel Girl usa ardillas exploradoras para reforzar la defensa del equipo."},"apCost":25,"effect":"RESISTANCE","potency":0.15},"allies":["america-chavez","moon-girl"],"rivals":["deadpool"],"biography":{"en":"Doreen Green is Squirrel Girl, an upbeat hero with enhanced strength, agility and a talent for communicating with squirrels. Her record of unlikely victories is less important than her empathy, creativity and refusal to assume that a frightening opponent cannot be reached or outsmarted. Her victories begin with noticing the person or creature everyone else has decided to ignore.","es":"Doreen Green es Squirrel Girl, una heroína optimista con fuerza y agilidad mejoradas y la capacidad de comunicarse con ardillas. Sus victorias improbables importan menos que su empatía, creatividad y negativa a creer que un rival aterrador no pueda ser comprendido o superado. Sus victorias comienzan al notar a quien todos los demás decidieron ignorar."},"tournamentMotivation":{"en":"Doreen enters because everyone deserves a champion who believes they can survive the scary part. She wants to keep communities hopeful, help stronger heroes think sideways and prove that kindness and cleverness belong in a response to a multiversal emergency. She will search for an unexpected solution before accepting that the situation is hopeless.","es":"Doreen entra porque todos merecen una campeona que crea que podrán superar la parte aterradora. Quiere mantener la esperanza de las comunidades, ayudar a pensar de otra manera y demostrar que la bondad también responde a una emergencia multiversal. Buscará una solución inesperada antes de aceptar que la situación no tiene salida."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('namor', 'avengers-doomsday', 'Namor', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/namor.webp', 'avengers-content-v1', '{"stats":{"power":96,"agility":52,"resistance":84,"ability":72},"maxEnergy":317,"maxAbilityPoints":65,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Trident Thrust","es":"Trident Thrust"},"description":{"en":"Namor drives the trident through the opening.","es":"Namor clava el tridente en la abertura."}},"offensiveAbility":{"id":"namor-offensive","name":"Tidal Spear","localizedName":{"en":"Tidal Spear","es":"Tidal Spear"},"description":{"en":"Namor summons a tidal assault across the opposing formation.","es":"Namor convoca una embestida de marea sobre la formación rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"namor-support","name":"Atlantean Rally","localizedName":{"en":"Atlantean Rally","es":"Atlantean Rally"},"description":{"en":"Namor turns Atlantean power into momentum for the team''s attacks.","es":"Namor convierte el poder atlante en impulso para los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":[],"rivals":["black-panther","human-torch","invisible-woman","reed-richards","shuri"],"biography":{"en":"Namor is the mutant ruler of Atlantis, an ancient and proud sovereign who commands the seas and fights with strength born of both land and ocean. He cooperates when it protects his people, but never forgets Atlantis''s independence or the cost of surface-world decisions. His pride comes with centuries of memory and a kingdom beneath waters the surface world depends on.","es":"Namor es el gobernante mutante de Atlantis, un soberano antiguo y orgulloso que domina los mares y lucha con la fuerza de la tierra y el océano. Coopera cuando protege a su pueblo, sin olvidar la independencia de Atlantis ni el costo de las decisiones de la superficie. Su orgullo nace de siglos de memoria y de un reino bajo mares de los que depende la superficie."},"tournamentMotivation":{"en":"Namor enters because collapsing boundaries could poison oceans, expose Atlantis and endanger a civilization that rarely receives surface-world protection. He will defend his kingdom on his own terms, test the intentions of the other rulers and negotiate only from strength. He will protect Atlantis first while refusing to pretend that the oceans end at its borders.","es":"Namor entra porque el colapso de las fronteras podría contaminar los océanos, exponer Atlantis y poner en peligro una civilización que rara vez recibe protección de la superficie. Defenderá su reino en sus propios términos y negociará desde la fuerza. Protegerá primero a Atlantis, sin fingir que los océanos terminan en sus fronteras."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('moon-girl', 'avengers-doomsday', 'Moon Girl', 'COMPANION_ONLY', 'TACTICIAN', '/assets/heroes/moon-girl.webp', 'avengers-content-v1', '{"stats":{"power":76,"agility":72,"resistance":68,"ability":91},"maxEnergy":244,"maxAbilityPoints":102,"primaryRole":"TECH","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Gadget Jab","es":"Gadget Jab"},"description":{"en":"Moon Girl uses a clever gadget to strike the opening.","es":"Moon Girl usa un dispositivo ingenioso para golpear la abertura."}},"offensiveAbility":{"id":"moon-girl-offensive","name":"Devil Dinosaur Directive","localizedName":{"en":"Devil Dinosaur Directive","es":"Devil Dinosaur Directive"},"description":{"en":"Moon Girl coordinates Devil Dinosaur in a sweeping assault.","es":"Moon Girl coordina a Devil Dinosaur en una ofensiva amplia."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"moon-girl-support","name":"Brainy Backup","localizedName":{"en":"Brainy Backup","es":"Brainy Backup"},"description":{"en":"Moon Girl uses science and gadgets to clear harmful effects from the team.","es":"Moon Girl usa ciencia y dispositivos para limpiar efectos perjudiciales del equipo."},"apCost":25,"effect":"CLEANSE","potency":1},"allies":["devil-dinosaur","squirrel-girl"],"rivals":[],"biography":{"en":"Lunella Lafayette is Moon Girl, a prodigious young inventor whose intellect and bond with Devil Dinosaur make her an extraordinary problem-solver. She can design under pressure, challenge assumptions and turn curiosity into practical technology without losing her sense of wonder. Her inventions begin as questions and become tools before adults finish explaining why they cannot work.","es":"Lunella Lafayette es Moon Girl, una joven inventora prodigiosa cuyo intelecto y vínculo con Devil Dinosaur la convierten en una solucionadora extraordinaria. Diseña bajo presión, cuestiona supuestos y convierte la curiosidad en tecnología práctica sin perder el asombro. Sus inventos comienzan como preguntas y se vuelven herramientas antes de que los adultos expliquen por qué no funcionarán."},"tournamentMotivation":{"en":"Lunella enters because a multiversal problem is exactly the kind of impossible question she refuses to leave unanswered. She wants to protect her community, learn from the world''s best minds and make sure younger people are treated as part of the solution. She will insist that the best answer includes the people who are usually left out of the room.","es":"Lunella entra porque un problema multiversal es el tipo de pregunta imposible que se niega a dejar sin respuesta. Quiere proteger a su comunidad, aprender de las mejores mentes y demostrar que los jóvenes también forman parte de la solución. Insistirá en que la mejor respuesta incluya a quienes suelen quedar fuera de la sala."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('devil-dinosaur', 'avengers-doomsday', 'Devil Dinosaur', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/devil-dinosaur.webp', 'avengers-content-v1', '{"stats":{"power":85,"agility":59,"resistance":96,"ability":70},"maxEnergy":288,"maxAbilityPoints":64,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Dino Bite","es":"Dino Bite"},"description":{"en":"Devil Dinosaur snaps down with a colossal bite.","es":"Devil Dinosaur muerde con una fuerza colosal."}},"offensiveAbility":{"id":"devil-dinosaur-offensive","name":"Colossal Stomp","localizedName":{"en":"Colossal Stomp","es":"Colossal Stomp"},"description":{"en":"Devil Dinosaur shakes the opposing formation with a colossal stomp.","es":"Devil Dinosaur sacude la formación rival con una pisada colosal."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"devil-dinosaur-support","name":"Pack Roar","localizedName":{"en":"Pack Roar","es":"Pack Roar"},"description":{"en":"Devil Dinosaur turns a thunderous roar into momentum for the team.","es":"Devil Dinosaur convierte un rugido atronador en impulso para el equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["moon-girl","wiccan"],"rivals":[],"biography":{"en":"Devil Dinosaur is a powerful red Tyrannosaurus whose bond with Moon Girl has made him a loyal protector rather than a creature of the past. His size, strength and instincts are formidable, while his trust in Lunella gives his ferocity a clear purpose. His loyalty is expressed through presence: he stays close when every unfamiliar sound becomes a threat.","es":"Devil Dinosaur es un poderoso tiranosaurio rojo cuyo vínculo con Moon Girl lo convirtió en un protector leal y no en una criatura del pasado. Su tamaño, fuerza e instintos son formidables, y la confianza en Lunella da propósito a su ferocidad. Su lealtad se expresa estando presente: permanece cerca cuando cada sonido desconocido es una amenaza."},"tournamentMotivation":{"en":"Devil follows Lunella because her safety is his pack''s safety. He does not need to understand every word about distant worlds to recognize fear, protect the small and stand beside the people who have earned his trust. He will follow the people he trusts and guard the path beneath their feet.","es":"Devil sigue a Lunella porque su seguridad es la seguridad de su manada. No necesita entender cada palabra sobre mundos lejanos para reconocer el miedo, proteger a los pequeños y estar junto a quienes ganaron su confianza. Seguirá a quienes confía y protegerá el camino bajo sus pies."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('beta-ray-bill', 'avengers-doomsday', 'Beta Ray Bill', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/beta-ray-bill.webp', 'avengers-content-v1', '{"stats":{"power":98,"agility":48,"resistance":87,"ability":72},"maxEnergy":319,"maxAbilityPoints":71,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Stormbreaker Blow","es":"Stormbreaker Blow"},"description":{"en":"Beta Ray Bill brings Stormbreaker down with Korbinite force.","es":"Beta Ray Bill descarga Stormbreaker con fuerza korbinita."}},"offensiveAbility":{"id":"beta-ray-bill-offensive","name":"Godstorm Charge","localizedName":{"en":"Godstorm Charge","es":"Godstorm Charge"},"description":{"en":"Beta Ray Bill calls a godstorm through the opposing formation.","es":"Beta Ray Bill desata una tormenta divina sobre la formación rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"beta-ray-bill-support","name":"Korbinite Valor","localizedName":{"en":"Korbinite Valor","es":"Korbinite Valor"},"description":{"en":"Beta Ray Bill turns warrior courage into momentum for the team''s attacks.","es":"Beta Ray Bill convierte el valor guerrero en impulso para los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["adam-warlock","captain-marvel","heimdall","thor"],"rivals":[],"biography":{"en":"Beta Ray Bill is a Korbinite champion transformed into a powerful warrior who proved worthy of divine strength and Stormbreaker. He carries a people''s survival in his memory, combining alien honor, compassion and the humility to wield power on behalf of others. Stormbreaker represents a people carried forward, not a trophy taken for personal glory.","es":"Beta Ray Bill es un campeón korbinita transformado en un poderoso guerrero, digno de una fuerza divina y de Stormbreaker. Lleva en la memoria la supervivencia de su pueblo y combina honor alienígena, compasión y humildad. Stormbreaker representa a un pueblo llevado hacia adelante, no un trofeo para la gloria personal."},"tournamentMotivation":{"en":"Bill joins because he knows what it means for a people to lose their world and search for a future elsewhere. He will defend other displaced civilizations, offer his strength without claiming ownership and stand with any team that protects survivors first. He will recognize displaced people in every reality and defend their right to continue.","es":"Bill se une porque sabe lo que significa que un pueblo pierda su mundo y busque un futuro en otra parte. Defenderá a otras civilizaciones desplazadas, ofrecerá su fuerza sin apropiarse de nada y priorizará a los supervivientes. Reconocerá a los desplazados en cada realidad y defenderá su derecho a continuar."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('wonder-man', 'avengers-doomsday', 'Wonder Man', 'COMPANION_ONLY', 'BLASTER', '/assets/heroes/wonder-man.webp', 'avengers-content-v1', '{"stats":{"power":80,"agility":80,"resistance":68,"ability":98},"maxEnergy":218,"maxAbilityPoints":102,"primaryRole":"MYSTIC","secondaryRole":"TECH","basicAttack":{"localizedName":{"en":"Ionic Punch","es":"Ionic Punch"},"description":{"en":"Wonder Man drives ionic energy through a focused punch.","es":"Wonder Man descarga energía iónica en un puñetazo concentrado."}},"offensiveAbility":{"id":"wonder-man-offensive","name":"Ionic Shockwave","localizedName":{"en":"Ionic Shockwave","es":"Ionic Shockwave"},"description":{"en":"Wonder Man releases an ionic shockwave across the enemy line.","es":"Wonder Man libera una onda de choque iónica sobre la línea enemiga."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"wonder-man-support","name":"Ionic Momentum","localizedName":{"en":"Ionic Momentum","es":"Ionic Momentum"},"description":{"en":"Wonder Man channels ionic power to strengthen the team''s attacks.","es":"Wonder Man canaliza poder iónico para fortalecer los ataques del equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["captain-america","she-hulk"],"rivals":["vision"],"biography":{"en":"Simon Williams is Wonder Man, an ionic-powered hero whose strength, flight and durability grew from a life that once revolved around business and public image. He has learned to value genuine service over celebrity, using his visibility to make heroism feel possible to others. He has learned that a public image matters only when it points people toward genuine help.","es":"Simon Williams es Wonder Man, un héroe de energía iónica cuya fuerza, vuelo y resistencia nacieron de una vida centrada en los negocios y la imagen pública. Aprendió a valorar el servicio genuino sobre la celebridad y usa su visibilidad para acercar el heroísmo. Aprendió que una imagen pública solo importa cuando orienta a la gente hacia una ayuda real."},"tournamentMotivation":{"en":"Simon enters because people facing an unknown threat need to see heroes who understand doubt as well as power. He wants to protect civilians, earn trust through action and show that public attention can be turned toward cooperation instead of spectacle. He will use attention to amplify the communities the powerful usually overlook.","es":"Simon entra porque quienes enfrentan una amenaza desconocida necesitan héroes que comprendan la duda además del poder. Quiere proteger civiles, ganar confianza con acciones y convertir la atención pública en cooperación, no en espectáculo. Usará la atención para amplificar a las comunidades que los poderosos suelen ignorar."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('quicksilver', 'avengers-doomsday', 'Quicksilver', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/quicksilver.webp', 'avengers-content-v1', '{"stats":{"power":69,"agility":94,"resistance":65,"ability":85},"maxEnergy":252,"maxAbilityPoints":92,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Velocity Jab","es":"Velocity Jab"},"description":{"en":"Quicksilver strikes before the opening can close.","es":"Quicksilver golpea antes de que la abertura pueda cerrarse."}},"offensiveAbility":{"id":"quicksilver-offensive","name":"Mach Dash","localizedName":{"en":"Mach Dash","es":"Mach Dash"},"description":{"en":"Quicksilver crosses the formation in a blur of supersonic strikes.","es":"Quicksilver atraviesa la formación en un borrón de golpes supersónicos."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"quicksilver-support","name":"Rapid Formation","localizedName":{"en":"Rapid Formation","es":"Rapid Formation"},"description":{"en":"Quicksilver uses speed to sharpen the team''s movement.","es":"Quicksilver usa su velocidad para agudizar el movimiento del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["bishop","wolverine"],"rivals":[],"biography":{"en":"Pietro Maximoff is Quicksilver, a mutant speedster whose impatience and sharp temper conceal fierce loyalty to his family. He can cross a battlefield in moments, but his harder discipline is learning when to slow down long enough to understand what others need. His speed outruns most hesitation, but his loyalty gives every rush a destination.","es":"Pietro Maximoff es Quicksilver, un velocista mutante cuya impaciencia y temperamento esconden una lealtad feroz hacia su familia. Puede cruzar un campo de batalla en instantes, pero su disciplina más difícil es frenar para comprender a los demás. Su velocidad supera casi toda duda, pero su lealtad da un destino a cada carrera."},"tournamentMotivation":{"en":"Pietro enters because a threat moving between realities could reach his family before anyone else notices. He will act quickly, protect the people he loves and make sure speed serves a plan rather than becoming another source of danger. He will reach his family first and then return for anyone who cannot keep up.","es":"Pietro entra porque una amenaza que se mueve entre realidades podría alcanzar a su familia antes de que otros la noten. Actuará rápido, protegerá a quienes ama y hará que la velocidad sirva a un plan, no a otro peligro. Llegará primero a su familia y luego volverá por quienes no puedan seguirle el ritmo."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('she-hulk', 'avengers-doomsday', 'She-Hulk', 'COMPANION_ONLY', 'BRUISER', '/assets/heroes/she-hulk.webp', 'avengers-content-v1', '{"stats":{"power":92,"agility":56,"resistance":92,"ability":52},"maxEnergy":329,"maxAbilityPoints":65,"primaryRole":"WARRIOR","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Gamma Gavel","es":"Gamma Gavel"},"description":{"en":"She-Hulk brings down a gamma-powered fist like a gavel.","es":"She-Hulk descarga un puño gamma como un martillo judicial."}},"offensiveAbility":{"id":"she-hulk-offensive","name":"Verdict Smash","localizedName":{"en":"Verdict Smash","es":"Verdict Smash"},"description":{"en":"She-Hulk delivers a decisive smash across the opposing formation.","es":"She-Hulk descarga un golpe decisivo sobre la formación rival."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"she-hulk-support","name":"Legal Counsel","localizedName":{"en":"Legal Counsel","es":"Legal Counsel"},"description":{"en":"She-Hulk turns confidence and discipline into momentum for the team.","es":"She-Hulk convierte confianza y disciplina en impulso para el equipo."},"apCost":25,"effect":"POWER","potency":0.12},"allies":["war-machine","wonder-man"],"rivals":[],"biography":{"en":"Jennifer Walters is She-Hulk, a gifted lawyer whose gamma-powered strength exists alongside her intelligence, confidence and precise sense of justice. She refuses to treat the law and heroism as opposing callings, arguing for people in court and defending them in the field. Her strength can win a fight, while her legal mind asks what justice requires afterward.","es":"Jennifer Walters es She-Hulk, una abogada brillante cuya fuerza gamma convive con inteligencia, confianza y un sentido preciso de la justicia. No ve la ley y el heroísmo como caminos opuestos: defiende a la gente en tribunales y en el campo. Su fuerza puede ganar una pelea, mientras su mente jurídica pregunta qué exige la justicia después."},"tournamentMotivation":{"en":"Jennifer enters because a multiversal emergency will create disputes, refugees and people whose rights can vanish in the confusion. She wants to protect them physically and speak for them afterward, insisting that survival must still include accountability. She will insist that frightened populations have a voice in decisions made about them.","es":"Jennifer entra porque una emergencia multiversal creará disputas, refugiados y personas cuyos derechos pueden desaparecer en la confusión. Quiere protegerlos físicamente y defenderlos después, insistiendo en que sobrevivir también exige responsabilidad. Insistirá en que las poblaciones asustadas tengan voz en las decisiones sobre ellas."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('wiccan', 'avengers-doomsday', 'Wiccan', 'COMPANION_ONLY', 'MYSTIC', '/assets/heroes/wiccan.webp', 'avengers-content-v1', '{"stats":{"power":66,"agility":56,"resistance":67,"ability":91},"maxEnergy":204,"maxAbilityPoints":120,"primaryRole":"MYSTIC","secondaryRole":"SUPPORT","basicAttack":{"localizedName":{"en":"Hex Bolt","es":"Hex Bolt"},"description":{"en":"Wiccan fires a focused bolt of spellcraft.","es":"Wiccan dispara un rayo concentrado de hechicería."}},"offensiveAbility":{"id":"wiccan-offensive","name":"Demiurge Surge","localizedName":{"en":"Demiurge Surge","es":"Demiurge Surge"},"description":{"en":"Wiccan unleashes reality-shaping magic across the enemy line.","es":"Wiccan desata magia que altera la realidad sobre la línea enemiga."},"apCost":35,"multiplier":1.1},"supportAbility":{"id":"wiccan-support","name":"Reality Anchor","localizedName":{"en":"Reality Anchor","es":"Reality Anchor"},"description":{"en":"Wiccan channels spellcraft to restore the team''s strength.","es":"Wiccan canaliza hechicería para devolver fuerzas al equipo."},"apCost":30,"effect":"HEAL","potency":0.7},"allies":["dagger","devil-dinosaur","doctor-strange","speed"],"rivals":[],"biography":{"en":"Billy Kaplan is Wiccan, a young sorcerer whose reality-shaping magic grows with imagination, empathy and confidence. He is still learning the limits of his gifts, but his instinct to protect family and friends makes him braver than his uncertainty suggests. His spells are shaped by emotion, which makes self-knowledge part of every act of courage.","es":"Billy Kaplan es Wiccan, un joven hechicero cuya magia capaz de alterar la realidad crece con imaginación, empatía y confianza. Todavía aprende los límites de sus dones, pero su instinto de proteger a su familia y amigos supera sus dudas. Sus hechizos nacen de la emoción, por lo que conocerse es parte de cada acto de coraje."},"tournamentMotivation":{"en":"Billy joins because younger heroes should not have to wait for the adults to solve a crisis that will shape their future. He wants to learn responsibly, protect the people he loves and use his magic to preserve possibilities rather than impose a single answer. He will learn carefully so his help expands possibilities instead of narrowing them.","es":"Billy se une porque los héroes jóvenes no deberían esperar a que los adultos resuelvan una crisis que definirá su futuro. Quiere aprender con responsabilidad, proteger a quienes ama y usar su magia para preservar posibilidades, no imponer una sola respuesta. Aprenderá con cuidado para que su ayuda amplíe las posibilidades en lugar de cerrarlas."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('speed', 'avengers-doomsday', 'Speed', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/speed.webp', 'avengers-content-v1', '{"stats":{"power":86,"agility":96,"resistance":74,"ability":78},"maxEnergy":269,"maxAbilityPoints":73,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Supersonic Strike","es":"Supersonic Strike"},"description":{"en":"Speed hits before the opening can close.","es":"Speed golpea antes de que la abertura pueda cerrarse."}},"offensiveAbility":{"id":"speed-offensive","name":"Momentum Rush","localizedName":{"en":"Momentum Rush","es":"Momentum Rush"},"description":{"en":"Speed turns impossible speed into a sweeping assault.","es":"Speed convierte una velocidad imposible en una ofensiva amplia."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"speed-support","name":"Speed Formation","localizedName":{"en":"Speed Formation","es":"Speed Formation"},"description":{"en":"Speed uses restless momentum to sharpen the team''s mobility.","es":"Speed usa su impulso incansable para agudizar la movilidad del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["kate-bishop","wiccan"],"rivals":[],"biography":{"en":"Tommy Shepherd is Speed, a young mutant whose velocity and impulsive confidence make him a difficult target and an even more difficult teammate to keep still. Beneath the restless energy is fierce loyalty to his family and the need to prove that he can choose what his power means. Tommy''s impatience is also a refusal to let danger become someone else''s problem.","es":"Tommy Shepherd es Speed, un joven mutante cuya velocidad y confianza impulsiva lo convierten en un objetivo difícil y un compañero difícil de mantener quieto. Bajo esa energía hay una lealtad feroz hacia su familia y la necesidad de decidir qué significa su poder. La impaciencia de Tommy también es una negativa a dejar el peligro en manos ajenas."},"tournamentMotivation":{"en":"Tommy enters because he refuses to let older heroes decide that young lives should stay on the sidelines. He will move people out of danger, protect his family and turn his impatience into momentum for a future he gets to help shape. He will turn restless movement into rescues that give his family time to act.","es":"Tommy entra porque se niega a que los héroes mayores decidan que los jóvenes deben quedarse al margen. Sacará a la gente del peligro, protegerá a su familia y convertirá su impaciencia en impulso para un futuro que también ayudará a construir. Convertirá su movimiento inquieto en rescates que den tiempo a su familia."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('white-tiger', 'avengers-doomsday', 'White Tiger', 'COMPANION_ONLY', 'SKIRMISHER', '/assets/heroes/white-tiger.webp', 'avengers-content-v1', '{"stats":{"power":78,"agility":84,"resistance":58,"ability":84},"maxEnergy":233,"maxAbilityPoints":85,"primaryRole":"AGILE","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Tiger Claw","es":"Tiger Claw"},"description":{"en":"White Tiger strikes with the power of the tiger amulets.","es":"White Tiger ataca con el poder de los amuletos del tigre."}},"offensiveAbility":{"id":"white-tiger-offensive","name":"Amulet Fury","localizedName":{"en":"Amulet Fury","es":"Amulet Fury"},"description":{"en":"White Tiger unleashes mystical martial fury across the opposing line.","es":"White Tiger desata una furia marcial mística sobre la línea rival."},"apCost":30,"multiplier":1.05},"supportAbility":{"id":"white-tiger-support","name":"Tiger''s Footwork","localizedName":{"en":"Tiger''s Footwork","es":"Tiger''s Footwork"},"description":{"en":"White Tiger uses mystical agility to sharpen the team''s movement.","es":"White Tiger usa agilidad mística para agudizar el movimiento del equipo."},"apCost":25,"effect":"AGILITY","potency":0.12},"allies":["jessica-jones","spider-man"],"rivals":[],"biography":{"en":"White Tiger is a martial hero empowered by mystical tiger amulets that grant enhanced strength, speed and combat ability. The mantle carries a legacy of responsibility, and its bearer must balance instinct, discipline and the protection of family and community. The tiger amulets connect personal courage to a legacy larger than one bearer.","es":"White Tiger es una heroína marcial fortalecida por amuletos místicos del tigre que le dan fuerza, velocidad y habilidad de combate. El manto lleva una herencia de responsabilidad y exige equilibrar instinto, disciplina y protección comunitaria. Los amuletos del tigre conectan el coraje personal con una herencia mayor que quien los lleva."},"tournamentMotivation":{"en":"White Tiger joins because a threat to many realities can endanger the neighborhoods and families that rarely receive cosmic attention. She will honor the amulets by defending people directly, learning from other champions and keeping power accountable to those it protects. She will make sure mystical power remains accountable to the people it serves.","es":"White Tiger se une porque una amenaza para muchas realidades puede poner en peligro barrios y familias que rara vez reciben atención cósmica. Honrará los amuletos defendiendo a la gente, aprendiendo de otros campeones y haciendo responsable al poder. Se asegurará de que el poder místico responda ante las personas a las que sirve."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}'),
  ('rescue', 'avengers-doomsday', 'Rescue', 'COMPANION_ONLY', 'GUARDIAN', '/assets/heroes/rescue.webp', 'avengers-content-v1', '{"stats":{"power":69,"agility":56,"resistance":85,"ability":87},"maxEnergy":257,"maxAbilityPoints":107,"primaryRole":"SUPPORT","secondaryRole":"WARRIOR","basicAttack":{"localizedName":{"en":"Repulsor Punch","es":"Repulsor Punch"},"description":{"en":"Rescue fires a focused repulsor-assisted strike.","es":"Rescue descarga un golpe asistido por repulsores."}},"offensiveAbility":{"id":"rescue-offensive","name":"Rescue Protocol","localizedName":{"en":"Rescue Protocol","es":"Rescue Protocol"},"description":{"en":"Rescue deploys the Rescue armor''s systems across the enemy line.","es":"Rescue despliega los sistemas de la armadura Rescue sobre la línea enemiga."},"apCost":30,"multiplier":1},"supportAbility":{"id":"rescue-support","name":"Armor Support","localizedName":{"en":"Armor Support","es":"Armor Support"},"description":{"en":"Rescue uses rescue technology to protect the team''s formation.","es":"Rescue usa tecnología de rescate para proteger la formación del equipo."},"apCost":25,"effect":"RESISTANCE","potency":0.15},"allies":[],"rivals":[],"biography":{"en":"Pepper Potts is Rescue, an armored protector whose advanced suit prioritizes defense, mobility and saving people from situations that technology alone cannot predict. Her leadership is practical and compassionate, built from years of seeing the human cost behind Tony Stark''s inventions. Pepper''s armor is designed around the moment after impact, when saving someone matters most.","es":"Pepper Potts es Rescue, una protectora acorazada cuyo traje avanzado prioriza defensa, movilidad y rescate en situaciones que la tecnología sola no puede prever. Su liderazgo es práctico y compasivo, nacido de años de ver el costo humano detrás de los inventos de Tony Stark. La armadura de Pepper está pensada para el instante posterior al impacto, cuando rescatar importa más."},"tournamentMotivation":{"en":"Pepper enters because the first need in any disaster is getting people out alive. She wants to coordinate rescue across realities, keep the inventors focused on consequences and prove that protection is not secondary to the heroes who deliver the biggest attack. She will make evacuation and care part of the response from the first alarm.","es":"Pepper entra porque la primera necesidad de todo desastre es sacar a la gente con vida. Quiere coordinar rescates entre realidades, mantener a los inventores atentos a las consecuencias y demostrar que proteger no es secundario frente al ataque más grande. Incluirá la evacuación y el cuidado desde la primera alarma."},"portraitFallback":"/assets/heroes/default-hero.svg","leadership":null}')
INSERT INTO "avengers_narrative_characters" ("id", "themeId", "displayName", "portrait", "contentVersion", "metadata") VALUES
  ('silver-surfer', 'avengers-doomsday', 'Silver Surfer', '/assets/narrative/silver-surfer.webp', 'avengers-content-v1', '{"role":"apparent-organizer","description":{"en":"The cosmic herald who returns with a warning and calls the Multiversal Tournament.","es":"El heraldo cósmico que regresa con una advertencia y convoca el Torneo Multiversal."},"portraitFallback":"/assets/narrative/default-character.svg"}'),
  ('doctor-doom', 'avengers-doomsday', 'Doctor Doom', '/assets/narrative/doctor-doom.webp', 'avengers-content-v1', '{"role":"final-boss","description":{"en":"The hidden architect of the tournament and the boss who enters during Doomsday.","es":"El arquitecto oculto del torneo y el jefe que entra en combate durante Doomsday."},"portraitFallback":"/assets/narrative/default-character.svg"}'),
  ('dormammu', 'avengers-doomsday', 'Dormammu', '/assets/narrative/dormammu.webp', 'avengers-content-v1', '{"role":"apparent-threat","description":{"en":"The ruler of the Dark Dimension presented publicly as the multiversal threat.","es":"El gobernante de la Dimensión Oscura presentado públicamente como la amenaza multiversal."},"portraitFallback":"/assets/narrative/default-character.svg"}')
INSERT INTO "team_profiles" ("id", "name", "description", "themeId", "configurationRevision", "contextRevision", "currentAttemptId", "metadata") VALUES
  ('spider-man', 'Spider-Man Team', 'The assigned Multiversal Tournament team led by Spider-Man.', 'avengers-doomsday', 0, 0, NULL, '{"leaderId":"spider-man","companionIds":["iron-man","punisher","scarlet-witch","doctor-strange","spider-woman"],"activeHeroIds":["spider-man","iron-man","punisher"],"strategy":"BALANCED","visualKey":"spider-man"}'),
  ('doctor-strange', 'Doctor Strange Team', 'The assigned Multiversal Tournament team led by Doctor Strange.', 'avengers-doomsday', 0, 0, NULL, '{"leaderId":"doctor-strange","companionIds":["scarlet-witch","america-chavez","wiccan","ghost-rider","magik"],"activeHeroIds":["doctor-strange","scarlet-witch","america-chavez"],"strategy":"BALANCED","visualKey":"doctor-strange"}'),
  ('captain-america', 'Captain America Team', 'The assigned Multiversal Tournament team led by Captain America.', 'avengers-doomsday', 0, 0, NULL, '{"leaderId":"captain-america","companionIds":["falcon","winter-soldier","black-widow","hawkeye","thor"],"activeHeroIds":["captain-america","falcon","winter-soldier"],"strategy":"BALANCED","visualKey":"captain-america"}'),
  ('thor', 'Thor Team', 'The assigned Multiversal Tournament team led by Thor.', 'avengers-doomsday', 0, 0, NULL, '{"leaderId":"thor","companionIds":["sif","valkyrie","heimdall","korg","beta-ray-bill"],"activeHeroIds":["thor","sif","valkyrie"],"strategy":"BALANCED","visualKey":"thor"}'),
  ('black-widow', 'Black Widow Team', 'The assigned Multiversal Tournament team led by Black Widow.', 'avengers-doomsday', 0, 0, NULL, '{"leaderId":"black-widow","companionIds":["hawkeye","winter-soldier","captain-america","falcon","spider-woman"],"activeHeroIds":["black-widow","hawkeye","winter-soldier"],"strategy":"BALANCED","visualKey":"black-widow"}'),
  ('wolverine', 'Wolverine Team', 'The assigned Multiversal Tournament team led by Wolverine.', 'avengers-doomsday', 0, 0, NULL, '{"leaderId":"wolverine","companionIds":["x-23","jean-grey","storm","nightcrawler","professor-x"],"activeHeroIds":["wolverine","x-23","jean-grey"],"strategy":"BALANCED","visualKey":"wolverine"}'),
